"use client";

import { useState, useEffect } from "react";
import { ImageIcon, Upload, Check, Trash2, Library, PlusCircle, Layout, Palette, Users, Image as LucideImage } from "lucide-react";
import { useAuction } from "../layout";
import { API_URL } from "../../../lib/apiConfig";

export default function AssetManager() {
  const { selectedAuction } = useAuction();
  const [library, setLibrary] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [activeTab, setActiveTab] = useState("splash"); // splash, background, team_bg, squad_bg, badge

  // Local auction assets state
  const [auctionAssets, setAuctionAssets] = useState({
    splashUrl: "",
    backgroundUrl: "",
    teamCardBgUrl: "",
    squadBgUrl: "",
    badges: { leftBadge: "", rightBadge: "" }
  });

  useEffect(() => {
    if (selectedAuction?._id) {
      setAuctionAssets(selectedAuction.assets || {
        splashUrl: "",
        backgroundUrl: "",
        teamCardBgUrl: "",
        squadBgUrl: "",
        badges: { leftBadge: "", rightBadge: "" }
      });
      fetchLibrary();
    }
  }, [selectedAuction]);

  const fetchLibrary = async () => {
    try {
      const res = await fetch(`${API_URL}/api/assets`);
      const data = await res.json();
      setLibrary(data);
    } catch (err) {console.error(err);} finally
    {setLoading(false);}
  };

  const handleUpload = async (e, type) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploading(true);
    try {
      // 1. Get S3 signed URL
      const res = await fetch(`${API_URL}/api/upload/get-upload-url?fileName=${file.name}&fileType=${file.type}`);
      const { uploadUrl, fileUrl } = await res.json();

      // 2. Upload to S3
      await fetch(uploadUrl, { method: "PUT", body: file });

      // 3. Save to Global Library
      const assetRes = await fetch(`${API_URL}/api/assets`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: file.name, type, url: fileUrl })
      });
      const newAsset = await assetRes.json();
      setLibrary([newAsset, ...library]);

      // 4. Auto-assign to current auction
      updateAuctionAsset(type, fileUrl);
    } catch (err) {
      console.error(err);
      alert("Upload failed");
    } finally {
      setUploading(false);
    }
  };

  const updateAuctionAsset = async (type, url) => {
    let updatedAssets = { ...auctionAssets };

    if (type === "splash") updatedAssets.splashUrl = url;else
    if (type === "background") updatedAssets.backgroundUrl = url;else
    if (type === "team_bg") updatedAssets.teamCardBgUrl = url;else
    if (type === "squad_bg") updatedAssets.squadBgUrl = url;else
    if (type === "badge_left") updatedAssets.badges.leftBadge = url;else
    if (type === "badge_right") updatedAssets.badges.rightBadge = url;

    setAuctionAssets(updatedAssets);

    // Save to DB
    try {
      await fetch(`${API_URL}/api/tournaments/${selectedAuction._id}/assets`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updatedAssets)
      });
    } catch (err) {console.error(err);}
  };

  const deleteAsset = async (id) => {
    if (!confirm("Remove from library?")) return;
    try {
      await fetch(`${API_URL}/api/assets/${id}`, { method: "DELETE" });
      setLibrary(library.filter((a) => a._id !== id));
    } catch (err) {console.error(err);}
  };

  const assetTabs = [
  { id: "splash", label: "Splash Screen", icon: LucideImage },
  { id: "background", label: "Main Background", icon: Layout },
  { id: "team_bg", label: "Team Card", icon: Palette },
  { id: "squad_bg", label: "Squad BG", icon: Users },
  { id: "badge", label: "Branding Badges", icon: PlusCircle }];


  const getSelectedUrl = () => {
    if (activeTab === 'splash') return auctionAssets.splashUrl;
    if (activeTab === 'background') return auctionAssets.backgroundUrl;
    if (activeTab === 'team_bg') return auctionAssets.teamCardBgUrl;
    if (activeTab === 'squad_bg') return auctionAssets.squadBgUrl;
    return ""; // Badges handled separately in UI
  };

  if (!selectedAuction) return <div className="p-20 text-center text-slate-500">Select context...</div>;

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-20">
      
      {/* ── HEADER ── */}
      <div>
        <h1 className="text-4xl font-black text-white">Auction <span className="text-emerald-500">Branding</span></h1>
        <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.4em] mt-2">Theme & Asset Management System</p>
      </div>

      <div className="flex flex-col lg:flex-row gap-10">
         
         {/* ── LEFT: NAVIGATION ── */}
         <div className="w-full lg:w-64 space-y-2">
            {assetTabs.map((tab) =>
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`w-full flex items-center gap-4 px-6 py-4 rounded-3xl font-black uppercase text-[10px] tracking-widest transition-all border ${
            activeTab === tab.id ? 'bg-emerald-600 border-emerald-500 text-white shadow-xl shadow-emerald-500/20' : 'bg-white/5 border-white/5 text-slate-500 hover:bg-white/10'}`
            }>
            
                <tab.icon className="w-4 h-4" />
                {tab.label}
              </button>
          )}
         </div>

         {/* ── RIGHT: GALLERY & CONTROL ── */}
         <div className="flex-1 space-y-8">
            
            {/* ACTIVE SELECTION PREVIEW */}
            <div className="bg-[#111827]/60 backdrop-blur-3xl rounded-[3rem] border border-white/10 p-10 overflow-hidden relative group">
               <div className="flex items-center justify-between mb-8">
                  <div className="flex items-center gap-4">
                     <div className="p-3 bg-emerald-500/10 rounded-2xl border border-emerald-500/20 text-emerald-500"><Check className="w-5 h-5" /></div>
                     <div>
                        <h3 className="text-sm font-black text-white uppercase tracking-widest">Active {activeTab.replace('_', ' ')}</h3>
                        <p className="text-[10px] text-slate-500 font-bold">Currently deployed to Live Auction</p>
                     </div>
                  </div>
                  <label className="flex items-center gap-2 px-6 py-3 bg-white/10 hover:bg-white/20 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white cursor-pointer transition-all">
                     <Upload className="w-4 h-4" /> {uploading ? "Uploading..." : "Upload New"}
                     <input type="file" className="hidden" onChange={(e) => handleUpload(e, activeTab === 'badge' ? 'badge' : activeTab)} disabled={uploading} />
                  </label>
               </div>

               {activeTab !== 'badge' ?
            <div className="w-full h-60 rounded-3xl overflow-hidden bg-slate-900 border border-white/5 flex items-center justify-center relative shadow-inner">
                     {getSelectedUrl() ?
              <img
                src={`${API_URL}/api/proxy-image?url=${encodeURIComponent(getSelectedUrl())}`}
                className="w-full h-full object-cover" alt="" /> :


              <div className="text-slate-700 italic font-bold">No Asset Selected</div>
              }
                  </div> :

            <div className="grid grid-cols-2 gap-8">
                     <div className="space-y-4">
                        <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1">Left Badge</p>
                        <div className="h-40 rounded-3xl bg-slate-900 border border-white/5 flex items-center justify-center p-6 shadow-inner">
                           {auctionAssets.badges.leftBadge ?
                  <img
                    src={`${API_URL}/api/proxy-image?url=${encodeURIComponent(auctionAssets.badges.leftBadge)}`}
                    className="max-h-full object-contain" alt="" /> :


                  <p className="text-xs text-slate-700 italic">Empty</p>
                  }
                        </div>
                     </div>
                     <div className="space-y-4">
                        <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest text-right pr-1">Right Badge</p>
                        <div className="h-40 rounded-3xl bg-slate-900 border border-white/5 flex items-center justify-center p-6 shadow-inner">
                           {auctionAssets.badges.rightBadge ?
                  <img
                    src={`${API_URL}/api/proxy-image?url=${encodeURIComponent(auctionAssets.badges.rightBadge)}`}
                    className="max-h-full object-contain" alt="" /> :


                  <p className="text-xs text-slate-700 italic">Empty</p>
                  }
                        </div>
                     </div>
                  </div>
            }
            </div>

            {/* LIBRARY GRID */}
            <div>
               <div className="flex items-center gap-3 mb-6">
                  <Library className="w-4 h-4 text-slate-500" />
                  <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Global Asset Library</h3>
               </div>
               
               <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                  {library.filter((a) => a.type === (activeTab === 'badge' ? 'badge' : activeTab)).map((asset) =>
              <div key={asset._id} className="group relative aspect-video bg-white/5 rounded-3xl border border-white/10 overflow-hidden hover:border-emerald-500/50 transition-all cursor-pointer">
                        <img
                  src={`${API_URL}/api/proxy-image?url=${encodeURIComponent(asset.url)}`}
                  className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" alt="" />
                
                        
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-3">
                           <button
                    onClick={() => updateAuctionAsset(activeTab === 'badge' ? auctionAssets.badges.leftBadge ? 'badge_right' : 'badge_left' : activeTab, asset.url)}
                    className="px-4 py-2 bg-emerald-600 rounded-xl text-[8px] font-black uppercase tracking-widest text-white shadow-xl">
                    Deploy Asset</button>
                           <button onClick={(e) => {e.stopPropagation();deleteAsset(asset._id);}} className="p-2 bg-red-500/20 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all"><Trash2 className="w-4 h-4" /></button>
                        </div>

                        {/* Deployed Indicator */}
                        {[auctionAssets.splashUrl, auctionAssets.backgroundUrl, auctionAssets.teamCardBgUrl, auctionAssets.squadBgUrl, auctionAssets.badges.leftBadge, auctionAssets.badges.rightBadge].includes(asset.url) &&
                <div className="absolute top-2 left-2 bg-emerald-500 text-black px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-widest shadow-lg">ACTIVE</div>
                }
                     </div>
              )}
               </div>
            </div>

         </div>
      </div>

    </div>);

}

"use client";

import { useState, useEffect } from "react";
import {
  ShieldCheck, AlertTriangle, Users, Search,
  ArrowLeft, Loader2, RefreshCw, Trash2,
  Eye, X, MapPin, Activity, Calendar,
  RotateCcw, Phone, CreditCard, ExternalLink, Download } from
"lucide-react";
import Link from "next/link";
import { useAuction } from "../layout";
import { useSession } from "next-auth/react";
import { API_URL, getMediaUrl } from "../../../lib/apiConfig";

import jsPDF from "jspdf";
import html2canvas from "html2canvas";

export default function RegistryAuditPage() {
  const { selectedAuction } = useAuction();
  const { data: session } = useSession();
  const [data, setData] = useState({ mobileConflicts: [], aadhaarConflicts: [], imageConflicts: [] });
  const [trash, setTrash] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isCapturing, setIsCapturing] = useState(false);
  const [view, setView] = useState("MOBILE"); // MOBILE | AADHAAR | PHOTO | TRASH
  const [selectedPlayer, setSelectedPlayer] = useState(null);

  const downloadPosterAsImage = async (p) => {
    setIsCapturing(true);
    const element = document.getElementById("audit-poster-canvas");
    if (!element) return;

    try {
      const canvas = await html2canvas(element, {
        useCORS: true,
        scale: 3,
        backgroundColor: "#0f172a",
        logging: false,
        onclone: (doc) => {
          // Universal Color Sanitizer (Fix for Tailwind v4 oklch/oklab)
          const allElements = doc.getElementsByTagName("*");
          for (let i = 0; i < allElements.length; i++) {
            const el = allElements[i];
            const computedStyle = window.getComputedStyle(el);

            if (computedStyle.color.includes("okl")) el.style.color = "#ffffff";
            if (computedStyle.backgroundColor.includes("okl")) el.style.backgroundColor = "#0f172a";
            if (computedStyle.borderColor.includes("okl")) el.style.borderColor = "#1e293b";
          }

          const p = doc.getElementById("audit-poster-canvas");
          if (p) {
            p.style.color = "#ffffff";
            p.style.backgroundColor = "#0f172a";
          }
        }
      });
      const data = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.download = `${p.name}_Official_Poster.png`;
      link.href = data;
      link.click();
    } catch (err) {
      console.error("Poster export failed", err);
    } finally {
      setIsCapturing(false);
    }
  };

  useEffect(() => {
    if (selectedAuction && session?.accessToken) fetchAudit();
  }, [selectedAuction, view, session]);

  const getImgUrl = (p) => {
    if (!p) return "/placeholder-player.png";
    const url = p.imageUrl || p.photo?.s3 || p.photo?.drive;
    return getMediaUrl(url, "/placeholder-player.png");
  };

  const fetchAudit = async () => {
    if (!session?.accessToken) return;
    setLoading(true);
    try {
      const headers = {
        "Authorization": `Bearer ${session.accessToken}`
      };

      if (view === "TRASH") {
        const res = await fetch(`${API_URL}/api/players/audit/trash?tournamentId=${selectedAuction._id}`, { headers });
        if (res.ok) setTrash(await res.json());
      } else {
        const res = await fetch(`${API_URL}/api/players/audit/duplicates?tournamentId=${selectedAuction._id}`, { headers });
        if (res.ok) setData(await res.json());
      }
    } catch (err) {
      console.error("Audit fetch failed:", err);
    }
    setLoading(false);
  };

  const downloadPlayerCard = async (p) => {
    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: [85, 120] // Vertical ID Card Size
    });

    const getBase64 = async (url) => {
      try {
        const res = await fetch(`${API_URL}/api/proxy-image?url=${encodeURIComponent(url)}`);
        const blob = await res.blob();
        return await new Promise((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result);
          reader.readAsDataURL(blob);
        });
      } catch {return null;}
    };

    // Card Background
    doc.setFillColor(15, 23, 42);
    doc.rect(0, 0, 85, 120, "F");

    // Header Glow
    doc.setFillColor(124, 58, 237); // Violet
    doc.ellipse(42.5, 0, 60, 30, "F");

    // Player Image
    const imgData = await getBase64(p.imageUrl);
    if (imgData) {
      doc.setFillColor(30, 41, 59);
      doc.roundedRect(12.5, 15, 60, 60, 10, 10, "F");
      doc.addImage(imgData, "JPEG", 15, 17.5, 55, 55);
    }

    // Name & Title
    doc.setTextColor(255, 255, 255);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(16);
    doc.text(p.name.toUpperCase(), 42.5, 85, { align: "center" });

    doc.setFontSize(8);
    doc.setTextColor(148, 163, 184); // Slate 400
    doc.setFont("helvetica", "normal");
    doc.text(p.role.toUpperCase(), 42.5, 92, { align: "center" });

    // ID Badge
    doc.setFillColor(124, 58, 237);
    doc.roundedRect(27.5, 98, 30, 8, 2, 2, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(8);
    doc.text(`ID #${p.applicationId}`, 42.5, 103, { align: "center" });

    // Footer
    doc.setFontSize(6);
    doc.setTextColor(71, 85, 105);
    doc.text(selectedAuction?.name?.toUpperCase() || "TOURNAMENT", 42.5, 112, { align: "center" });
    doc.text("PARMESHWAR CUP - OFFICIAL ID", 42.5, 115, { align: "center" });

    doc.save(`${p.name}_Player_Card.pdf`);
  };

  const handleSoftDelete = async (id) => {
    if (!confirm("Move this player to Recycle Bin?")) return;
    try {
      const res = await fetch(`${API_URL}/api/players/${id}`, {
        method: "DELETE",
        headers: { "Authorization": `Bearer ${session?.accessToken}` }
      });
      if (res.ok) fetchAudit();
    } catch {}
  };

  const handleRestore = async (id) => {
    try {
      const res = await fetch(`${API_URL}/api/players/audit/restore/${id}`, {
        method: "PUT",
        headers: { "Authorization": `Bearer ${session?.accessToken}` }
      });
      if (res.ok) fetchAudit();
    } catch {}
  };

  if (!selectedAuction) return (
    <div className="h-[80vh] flex items-center justify-center p-6 text-center">
       <div className="space-y-4">
          <AlertTriangle className="w-12 h-12 text-yellow-500 mx-auto" />
          <h2 className="text-xl font-black text-white uppercase italic">Context Required</h2>
          <p className="text-slate-500 text-xs font-bold tracking-widest uppercase">Select an auction to audit registry</p>
       </div>
    </div>);


  return (
    <div className="space-y-10 max-w-6xl mx-auto pb-20 p-6 selection:bg-red-500/30">
      
      {/* ── Header ── */}
      <div className="flex flex-col md:flex-row items-start justify-between gap-6">
         <div>
            <div className="flex items-center gap-3 mb-2">
               <Link href="/admin/dashboard" className="p-2 bg-white/5 rounded-xl text-slate-500 hover:text-white transition-colors">
                  <ArrowLeft size={16} />
               </Link>
               <p className="text-[10px] font-black text-red-500 uppercase tracking-[0.4em] leading-none">Security Protocol</p>
            </div>
            <h1 className="text-4xl font-black text-white italic tracking-tighter uppercase leading-none">Registry <span className="text-transparent bg-clip-text bg-gradient-to-r from-white to-slate-500">Auditor</span></h1>
            <p className="text-slate-500 text-[10px] font-bold uppercase tracking-[0.2em] mt-3">{selectedAuction.name}</p>
         </div>

         <div className="flex items-center gap-3">
            <button
            onClick={fetchAudit}
            className="p-4 bg-white/5 border border-white/10 rounded-2xl text-slate-400 hover:text-white transition-all shadow-lg">
            
               <RefreshCw size={18} className={loading ? "animate-spin" : ""} />
            </button>
         </div>
      </div>

      {loading ?
      <div className="h-96 flex flex-col items-center justify-center gap-6">
           <Loader2 className="w-12 h-12 text-red-500 animate-spin" />
           <p className="text-[10px] font-black text-slate-600 uppercase tracking-[0.5em] italic">Scanning Data Resource Nodes...</p>
        </div> :

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
           
           <div className="lg:col-span-1 space-y-4">
               <div className="bg-[#111827] border border-white/10 rounded-[2.5rem] p-6 space-y-2 overflow-hidden relative shadow-2xl">
                  <div className="absolute top-0 right-0 w-24 h-24 bg-red-500/10 blur-3xl pointer-events-none"></div>
                  
                  <button
              onClick={() => setView("MOBILE")}
              className={`w-full flex items-center justify-between p-5 rounded-2xl transition-all ${view === "MOBILE" ? 'bg-red-600/10 border border-red-500/20 text-white' : 'text-slate-500 hover:bg-white/5 hover:text-slate-300'}`}>
              
                     <div className="flex items-center gap-3">
                        <Phone size={16} />
                        <span className="text-[10px] font-black tracking-widest uppercase">Mobile Conflicts</span>
                     </div>
                     <span className="text-xs font-black">{data.mobileConflicts?.length || 0}</span>
                  </button>

                  <button
              onClick={() => setView("AADHAAR")}
              className={`w-full flex items-center justify-between p-5 rounded-2xl transition-all ${view === "AADHAAR" ? 'bg-red-600/10 border border-red-500/20 text-white' : 'text-slate-500 hover:bg-white/5 hover:text-slate-300'}`}>
              
                     <div className="flex items-center gap-3">
                        <CreditCard size={16} />
                        <span className="text-[10px] font-black tracking-widest uppercase">Aadhaar Conflicts</span>
                     </div>
                     <span className="text-xs font-black">{data.aadhaarConflicts?.length || 0}</span>
                  </button>

                  <button
              onClick={() => setView("PHOTO")}
              className={`w-full flex items-center justify-between p-5 rounded-2xl transition-all ${view === "PHOTO" ? 'bg-red-600/10 border border-red-500/20 text-white' : 'text-slate-500 hover:bg-white/5 hover:text-slate-300'}`}>
              
                     <div className="flex items-center gap-3">
                        <Users size={16} />
                        <span className="text-[10px] font-black tracking-widest uppercase">Photo Conflicts</span>
                     </div>
                     <span className="text-xs font-black">{data.imageConflicts?.length || 0}</span>
                  </button>

                  <div className="pt-4 border-t border-white/5">
                    <button
                onClick={() => setView("TRASH")}
                className={`w-full flex items-center justify-between p-5 rounded-2xl transition-all ${view === "TRASH" ? 'bg-yellow-600/10 border border-yellow-500/20 text-yellow-500' : 'bg-yellow-500/5 text-slate-600 hover:bg-yellow-500/10 hover:text-yellow-400'}`}>
                
                        <div className="flex items-center gap-3">
                            <Trash2 size={16} />
                            <span className="text-[10px] font-black tracking-widest uppercase">Recycle Bin</span>
                        </div>
                        <span className="text-xs font-black">{trash.length}</span>
                    </button>
                  </div>
               </div>
           </div>

           <div className="lg:col-span-3 space-y-6">
              {view === "TRASH" ?
          trash.length === 0 ?
          <div className="h-96 flex flex-col items-center justify-center gap-6 bg-white/5 border border-white/5 border-dashed rounded-[3rem]">
                        <div className="w-20 h-20 bg-slate-900 rounded-full flex items-center justify-center text-slate-800"><ShieldCheck size={40} /></div>
                        <p className="text-[9px] font-black text-slate-700 uppercase tracking-[0.3em] italic">Recycle bin is empty</p>
                    </div> :

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {trash.map((p) =>
            <div key={p._id} className="p-6 bg-[#111827]/80 border border-white/10 rounded-3xl group hover:border-yellow-500/30 transition-all flex items-center justify-between shadow-xl">
                                <div className="flex items-center gap-5">
                                    <div className="w-14 h-14 bg-white/5 rounded-2xl overflow-hidden border border-white/10 shrink-0 grayscale opacity-40">
                                        <img src={getMediaUrl(p.imageUrl || p.photo?.s3 || p.photo?.drive, '/placeholder-player.png')} className="w-full h-full object-cover" alt="" />
                                    </div>
                                    <div>
                                        <p className="text-xs font-black text-white uppercase italic tracking-tighter opacity-60 line-through">{p.name}</p>
                                        <p className="text-[8px] text-slate-600 font-bold uppercase tracking-widest mt-1">Deleted: {new Date(p.deletedAt).toLocaleTimeString()}</p>
                                    </div>
                                </div>
                                <button
                onClick={() => handleRestore(p._id)}
                className="p-3 bg-emerald-600/10 text-emerald-500 rounded-xl hover:bg-emerald-600 hover:text-white transition-all shadow-lg flex items-center gap-2">
                
                                    <RotateCcw size={14} />
                                    <span className="text-[8px] font-black uppercase">Restore</span>
                                </button>
                            </div>
            )}
                    </div> :

          (view === "MOBILE" ? data.mobileConflicts : view === "AADHAAR" ? data.aadhaarConflicts : data.imageConflicts).length === 0 ?
          <div className="h-96 flex flex-col items-center justify-center gap-6 bg-white/5 border border-white/5 border-dashed rounded-[3rem]">
