}

"use client";

import { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import { Star, Trophy, Users, ShieldCheck, User, Search, Hash, AlertCircle, Edit3, FileSpreadsheet, Upload, RefreshCw, X, Camera, Trash2, AlertTriangle } from "lucide-react";
import * as XLSX from "xlsx";
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import { useAuction } from "../layout";
// import { io } from "socket.io-client"; // Using shared socket from context
import { API_URL, getProxiedImageUrl, getMediaUrl } from "../../../lib/apiConfig";
import ImageEditModal from "../../../components/ImageEditModal";

// Socket shared from context

export default function IconPlayersPanel() {
  const { selectedAuction, socket } = useAuction();
  const { data: session } = useSession();
  const [icons, setIcons] = useState([]);
  const [teams, setTeams] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [editImageTarget, setEditImageTarget] = useState(null); // { id, url, name }
  const [isImporting, setIsImporting] = useState(false);
  const [importedData, setImportedData] = useState([]); // Store parsed CSV data for display
  const [editingPlayer, setEditingPlayer] = useState(null); // New state for editing name & details
  const [isDeleteRangeModalOpen, setIsDeleteRangeModalOpen] = useState(false);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [deleteRange, setDeleteRange] = useState({ from: "", to: "" });
  const [newIcon, setNewIcon] = useState({ name: "", mobile: "", village: "", role: "All-Rounder", team: "", imageUrl: "" });
  const [isUploading, setIsUploading] = useState(false);
  const [pdfProgress, setPdfProgress] = useState({ current: 0, total: 0, active: false });

  // Year logic removed as per user request to restore old system

  useEffect(() => {
    if (selectedAuction?._id) {
      fetchIcons();
    } else {
      setLoading(false);
    }
  }, [selectedAuction]);

  // Handle CSV Import for Icons
  const handleImportIcons = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Ask if they want to REPLACE or APPEND icons
    const mode = confirm("IMPORT MODE:\n\nClick 'OK' to REPLACE all existing icon players with this CSV (Removes old icons).\nClick 'Cancel' to APPEND new icons to the existing list.") ? "replaceIcons" : "append";

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = async (ev) => {
      try {
        const bstr = ev.target.result;
        const wb = XLSX.read(bstr, { type: 'binary', cellDates: true });
        const ws = wb.Sheets[wb.SheetNames[0]];
        const data = XLSX.utils.sheet_to_json(ws);

        const findValue = (row, keys) => {
          const rk = Object.keys(row);
          // First try exact matches
          for (const k of keys) {
            const f = rk.find(key => key.toLowerCase().trim() === k.toLowerCase().trim());
            if (f) return row[f];
          }
          // Then try includes
          for (const k of keys) {
            const f = rk.find(key => key.toLowerCase().includes(k.toLowerCase()));
            if (f) return row[f];
          }
          return null;
        };

        const proxyUrl = (url) => {
          return getProxiedImageUrl(url);
        };

        const importedIcons = [];
        const tableData = [];

        data.forEach((row, rowIndex) => {
          const seenNames = new Set();
          const teamName = (findValue(row, ["team name", "team", "teamname", "ತಂಡ"]) || "Unassigned").trim();

          const possibleIconNames = [
            "icon name", "iconname", "player name", "playername", "name", "player",
            "Captain Name", "Vice Captain Name", "Retain Player Name", "Retained Player",
            "Captain", "Vice Captain"
          ];
          const rowImageUrl = findValue(row, ["iconPhot", "iconphot", "photo", "image", "imageUrl", "link", "url"]);
          const rowMobile = findValue(row, ["iconNo", "iconno", "mobile", "phone", "contact"]) || "-";
          const rowVillage = findValue(row, ["village", "town", "city", "ಸ್ಥಳ"]) || "-";
          const rowRole = findValue(row, ["role", "category", "position", "ಸ್ಥಾನ"]) || "All-Rounder";

          possibleIconNames.forEach(key => {
            const rawVal = findValue(row, [key]);
            const strVal = rawVal != null ? String(rawVal) : "";

            if (strVal.trim() !== "") {
              const cleanVal = strVal.toLowerCase().trim();
              const cleanTeam = teamName.toLowerCase().trim();

              // 1. Skip if name is exactly the team name (placeholder)
              if (cleanVal === cleanTeam) return;

              // 2. Skip if we've already seen this player in this import
              if (seenNames.has(cleanVal)) return;
              seenNames.add(cleanVal);

              const icon = {
                name: strVal.trim(),
                mobile: rowMobile,
                imageUrl: rowImageUrl || "",
                role: rowRole,
                village: rowVillage,
                age: 0,
                teamName: teamName,
                iconRole: key.toLowerCase().includes("captain") ? "captain" :
                  key.toLowerCase().includes("vice") ? "viceCaptain" :
                    key.toLowerCase().includes("retain") ? "retained" : null,
                isIcon: true
              };
              importedIcons.push(icon);
              tableData.push({ ...icon, type: icon.iconRole || 'Icon' });
            }
          });
        });

        if (tableData.length > 0) {
          setImportedData(tableData);
        }

        if (importedIcons.length > 0) {
          const teamsRes = await fetch(`${API_URL}/api/teams?tournamentId=${selectedAuction._id}`);
          const teamsData = await teamsRes.json();
          const teamMap = {};
          const teamList = teamsData || [];

          teamList.forEach(t => {
            const name = t.name.toLowerCase().trim();
            const shortName = (t.shortName || "").toLowerCase().trim();
            teamMap[name] = t._id;
            if (shortName) teamMap[shortName] = t._id;
          });

          const playersWithTeamIds = importedIcons.map(icon => {
            const searchName = icon.teamName.toLowerCase().trim();
            // 1. Exact match
            let teamId = teamMap[searchName];

            // 2. Fuzzy match: check if CSV name is contained in DB name or vice-versa
            if (!teamId) {
              const found = teamList.find(t => {
                const dbName = t.name.toLowerCase().trim();
                const dbShort = (t.shortName || "").toLowerCase().trim();
                return dbName.includes(searchName) ||
                  searchName.includes(dbName) ||
                  (dbShort && (dbShort.includes(searchName) || searchName.includes(dbShort)));
              });
              if (found) teamId = found._id;
            }

            return { ...icon, team: teamId || null };
          });

          const res = await fetch(`${API_URL}/api/players/import`, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${session?.accessToken}`
            },
            body: JSON.stringify({
              players: playersWithTeamIds,
              tournamentId: selectedAuction._id,
              mode: mode
            })
          });

          if (res.ok) {
            const result = await res.json();
            alert(`Successfully added ${result.added} icon players! (Skipped: ${result.skipped} duplicates)`);
            fetchIcons();
            if (socket && socket.connected) {
              socket.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
            }
          } else {
            alert("Failed to import icon players");
          }
        } else {
          alert("No icon players found in CSV");
        }
      } catch (err) {
        console.error("Import error:", err);
        alert("Error parsing file");
      } finally {
        setIsImporting(false);
        if (e.target) e.target.value = null;
      }
    };
    reader.readAsBinaryString(file);
  };

  const fetchIcons = async () => {
    setLoading(true);
    try {
      const [pRes, tRes] = await Promise.all([
        fetch(`${API_URL}/api/players?tournamentId=${selectedAuction._id}&isIcon=true`),
        fetch(`${API_URL}/api/teams?tournamentId=${selectedAuction._id}`)
      ]);

      if (!pRes.ok) {
        const errorText = await pRes.text();
        throw new Error(`Failed to fetch players: ${pRes.status} ${errorText}`);
      }
      if (!tRes.ok) {
        const errorText = await tRes.text();
        throw new Error(`Failed to fetch teams: ${tRes.status} ${errorText}`);
      }

      const pData = await pRes.json();
      const tData = await tRes.json();

      // Filter for icons only
      const iconPlayers = pData.filter(p => p.isIcon);
      setIcons(iconPlayers);
      setTeams(tData);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddIcon = async () => {
    if (!newIcon.name || !newIcon.team) {
      alert("Name and Team are required");
      return;
    }

    try {
      setLoading(true);
      const res = await fetch(`${API_URL}/api/players`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${session?.accessToken}`
        },
        body: JSON.stringify({
          ...newIcon,
          isIcon: true,
          tournamentId: selectedAuction._id,
          status: "sold"
        })
      });

      if (res.ok) {
        alert("Icon player added successfully");
        setIsAddModalOpen(false);
        setNewIcon({ name: "", mobile: "", village: "", role: "All-Rounder", team: "", imageUrl: "" });
        fetchIcons();
        if (socket && socket.connected) {
          socket.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
        }
      } else {
        const err = await res.json();
        alert(`Failed: ${err.message}`);
      }
    } catch (err) {
      alert("Error adding icon player");
    } finally {
      setLoading(false);
    }
  };

  const handlePhotoUpload = async (file) => {
    try {
      setIsUploading(true);
      const fileType = file.type;
      const response = await fetch(`${API_URL}/api/upload/get-upload-url?fileType=${fileType}&folder=players`);
      if (!response.ok) throw new Error(`Upload URL failed: ${response.status}`);
      const { uploadUrl, fileUrl } = await response.json();

      await fetch(uploadUrl, { method: "PUT", body: file, headers: { "Content-Type": fileType } });
      setNewIcon({ ...newIcon, imageUrl: fileUrl });
    } catch (err) {
      console.error("Upload failed", err);
      alert("Upload failed");
    } finally {
      setIsUploading(false);
    }
  };

  const handleDeleteRange = async () => {
    const fromVal = parseInt(deleteRange.from);
    const toVal = parseInt(deleteRange.to);

    if (isNaN(fromVal) || isNaN(toVal)) {
      alert("Please enter valid numeric IDs for the range");
      return;
    }

    // Target players based on their visible ICON ID
    const iconsToDelete = icons.filter(p => {
      const id = parseInt(p.iconId);
      return !isNaN(id) && id >= fromVal && id <= toVal;
    });

    if (iconsToDelete.length === 0) {
      alert(`No icon players found with IDs between ${fromVal} and ${toVal}. Check the ICON ID shown on the player cards.`);
      return;
    }

    if (!window.confirm(`Are you sure you want to delete ${iconsToDelete.length} elite icon players?`)) return;

    try {
      setLoading(true);
      const res = await fetch(`${API_URL}/api/players/bulk-delete`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${session?.accessToken}`
        },
        body: JSON.stringify({ playerIds: iconsToDelete.map(p => p._id) }),
      });

      if (res.ok) {
        alert(`${iconsToDelete.length} icon players deleted successfully`);
        setIsDeleteRangeModalOpen(false);
        setDeleteRange({ from: "", to: "" });
        fetchIcons();
        socket?.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
      } else {
        alert("Failed to delete the selected range");
      }
    } catch (err) {
      console.error(err);
      alert("Error during bulk delete");
    } finally {
      setLoading(false);
    }
  };

  const getTeamName = (p) => {
    if (!p) return "Unassigned";
    const teamId = p.team;
    const team = teams.find(t => t._id === (teamId?._id || teamId));
    if (team) return team.name;
    // Fallback to raw teamName string if ID lookup fails
    return p.teamName || "Unassigned";
  };

  const downloadPDF = async () => {
    try {
      setLoading(true);
      const doc = new jsPDF();

      // Optimized Helper to get compressed image as base64
      const getBase64Image = (url, isHighQuality = false) => {
        return new Promise((resolve) => {
          const img = new Image();
          img.crossOrigin = 'Anonymous';
          const timeout = setTimeout(() => {
            img.src = '';
            resolve(null);
          }, 8000);

          img.onload = () => {
            clearTimeout(timeout);
            try {
              const canvas = document.createElement('canvas');
              // If high quality requested (like for branding), keep larger dimensions
              const maxDim = isHighQuality ? 1200 : 400;
              let width = img.width;
              let height = img.height;

              if (width > height) {
                if (width > maxDim) {
                  height *= maxDim / width;
                  width = maxDim;
                }
              } else {
                if (height > maxDim) {
                  width *= maxDim / height;
                  height = maxDim;
                }
              }

              canvas.width = width;
              canvas.height = height;
              const ctx = canvas.getContext('2d');
              ctx.drawImage(img, 0, 0, width, height);
              // Use 0.8 quality for better clarity (High Priority)
              resolve(canvas.toDataURL('image/jpeg', isHighQuality ? 0.95 : 0.8));
            } catch (e) {
              console.error("Canvas compression failed", e);
              resolve(null);
            }
          };
          img.onerror = () => {
            clearTimeout(timeout);
            resolve(null);
          };
          img.src = getProxiedImageUrl(url);
        });
      };

      // Pre-load logos with full URL construction
      const tournamentLogo = selectedAuction?.organizerLogo ? await getBase64Image(getMediaUrl(selectedAuction.organizerLogo)) : null;
      const manifestLogo = await getBase64Image('/icon-512.png');

      // Pre-load all images with progress tracking
      const total = filteredIcons.length;
      setPdfProgress({ current: 0, total, active: true });

      const base64Images = [];
      for (let i = 0; i < filteredIcons.length; i++) {
        const p = filteredIcons[i];
        setPdfProgress(prev => ({ ...prev, current: i + 1 }));

        let imgBase64 = null;
        if (p.imageUrl) {
          imgBase64 = await getBase64Image(p.imageUrl);
        }
        base64Images.push(imgBase64);
      }

      const tableData = filteredIcons.map((p, idx) => ({
        id: idx + 1,
        name: p.name.toUpperCase(),
        team: getTeamName(p).toUpperCase(),
        image: base64Images[idx]
      }));

      autoTable(doc, {
        startY: 45,
        head: [['#', 'PHOTO', 'PLAYER NAME', 'TEAM NAME']],
        body: tableData.map(row => [row.id, '', row.name, row.team]),
        theme: 'grid',
        headStyles: {
          fillColor: [234, 179, 8],
          textColor: 0,
          halign: 'center',
          fontStyle: 'bold',
          fontSize: 10
        },
        styles: {
          fontSize: 9,
          cellPadding: 4,
          minCellHeight: 50, // More height for safety
          valign: 'middle'
        },
        rowPageBreak: 'avoid', // Prevent row from splitting across pages
        columnStyles: {
          0: { cellWidth: 15, halign: 'center' },
          1: { cellWidth: 40, halign: 'center' },
          2: { cellWidth: 65, fontStyle: 'bold' },
          3: { fontStyle: 'bold', textColor: [100, 100, 100] }
        },
        margin: { top: 45 },
        didDrawPage: (data) => {
          // Draw Header Background on every page
          doc.setFillColor(17, 24, 39);
          doc.rect(0, 0, 210, 40, 'F');

          // Draw Tournament Logo (Left)
          if (tournamentLogo) {
            try {
              doc.addImage(tournamentLogo, 'PNG', 15, 5, 25, 25);
            } catch (e) { console.error("T-Logo failed", e); }
          }

          // Draw Manifest Logo (Right)
          if (manifestLogo) {
            try {
              doc.addImage(manifestLogo, 'PNG', 170, 5, 25, 25);
            } catch (e) { console.error("M-Logo failed", e); }
          }

          // Draw Text
          doc.setFontSize(20);
          doc.setTextColor(255, 255, 255);
          doc.setFont("helvetica", "bold");
          doc.text(`${selectedAuction?.name || 'Tournament'}`, 105, 20, { align: 'center' });

          doc.setFontSize(10);
          doc.setTextColor(234, 179, 8);
          doc.text("ELITE ICON PLAYERS REGISTRY", 105, 30, { align: 'center' });

          // Page Numbering & Contact Info (FOOTER)
          const pageCount = doc.internal.getNumberOfPages();
          doc.setFontSize(8);
          doc.setTextColor(150);

          // Left: Contact Info
          doc.text("Contact: +91 81470 89330", 15, doc.internal.pageSize.getHeight() - 15);
          doc.text("Insta: @lakshmish_virat", 15, doc.internal.pageSize.getHeight() - 10);

          // Right: Page Number
          doc.text(`Page ${pageCount}`, 195, doc.internal.pageSize.getHeight() - 10, { align: "right" });

          // Center: Credits
          doc.text("Designed by Ravikumar K P", 105, doc.internal.pageSize.getHeight() - 10, { align: "center" });
        },
        didDrawCell: (data) => {
          if (data.section === 'body' && data.column.index === 1) {
            const row = tableData[data.row.index];
            if (row?.image) {
              try {
                // FORCE scale to 30x30 and center
                const s = 30;
                const x = data.cell.x + (data.cell.width - s) / 2;
                const y = data.cell.y + (data.cell.height - s) / 2;
                doc.addImage(row.image, 'PNG', x, y, s, s, undefined, 'FAST');
              } catch (e) {
                console.error("AddImage failed", e);
              }
            }
          }
        }
      });

      // ADD LAST PAGE: Creator Contact Card (HIGH QUALITY)
      try {
        const creatorImg = await getBase64Image('/creator-contact.png', true);
        if (creatorImg) {
          doc.addPage();
          doc.setFillColor(15, 23, 42);
          doc.rect(0, 0, 210, 297, 'F');

          const imgWidth = 180;
          const imgHeight = 180;
          const x = (210 - imgWidth) / 2;
          const y = (297 - imgHeight) / 2;
          // Use "SLOW" for better rendering quality on the final page
          doc.addImage(creatorImg, 'JPEG', x, y, imgWidth, imgHeight, undefined, "SLOW");

          doc.setFontSize(14);
          doc.setTextColor(255, 255, 255);
          doc.text("LAKSHMISH CRICKET EVENTS", 105, y + imgHeight + 15, { align: 'center' });
        }
      } catch (e) {
        console.error("Failed to add creator contact page", e);
      }

      doc.save(`${selectedAuction?.name?.replace(/\s+/g, '_') || 'tournament'}_icons.pdf`);
    } catch (err) {
      console.error("PDF Generation failed:", err);
      alert(`Error generating PDF: ${err.message}`);
    } finally {
      setLoading(false);
      setPdfProgress({ current: 0, total: 0, active: false });
    }
  };

  const filteredIcons = icons
    .filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()))
    .sort((a, b) => (a.iconId || 0) - (b.iconId || 0));

  if (!selectedAuction) {
    return (
      <div className="flex flex-col items-center justify-center py-20 bg-white/5 border border-white/5 rounded-[3rem] text-center">
        <AlertCircle className="w-12 h-12 text-yellow-500/50 mb-4" />
        <h2 className="text-xl font-black text-white">No Auction Selected</h2>
        <p className="text-slate-500 text-sm mt-2 max-w-xs font-semibold">Select an auction system from the topbar to view icon rosters.</p>
      </div>
    );
  }

  return (
    <div className="space-y-10 max-w-7xl mx-auto pb-20">

      {/* ── HEADER AREA ── */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <div className="p-4 bg-yellow-500/10 border border-yellow-500/30 rounded-4xl text-yellow-500 shadow-[0_0_30px_rgba(234,179,8,0.1)]">
            <Star className="w-8 h-8 fill-yellow-500" />
          </div>
          <div>
            <h1 className="text-4xl font-black text-white tracking-tight">Icon <span className="text-yellow-500">Players</span> List</h1>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.4em] mt-1">Pre-Retained Players for Selected Tournament</p>
          </div>
        </div>

        <div className="relative group min-w-[320px]">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-yellow-500 transition-colors" />
          <input
            placeholder="Search icon roster..."
            className="w-full bg-white/5 border border-white/10 rounded-2xl pl-11 pr-4 py-3.5 font-bold text-white focus:border-yellow-500 outline-none transition-all placeholder:text-slate-700"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <button
            onClick={downloadPDF}
            className="p-3.5 bg-blue-500/10 text-blue-500 border border-blue-500/20 rounded-2xl hover:bg-blue-500/20 transition-all active:scale-95 shadow-xl"
            title="Download PDF"
          >
            <FileSpreadsheet className="w-4 h-4" />
          </button>

          <button
            onClick={() => setIsDeleteRangeModalOpen(true)}
            className="p-3.5 bg-red-500/10 text-red-500 border border-red-500/20 rounded-2xl hover:bg-red-500/20 transition-all active:scale-95 shadow-xl"
            title="Delete Range"
          >
            <Trash2 className="w-4 h-4" />
          </button>

          <button
            onClick={() => setIsAddModalOpen(true)}
            className="px-6 py-3.5 bg-white/5 border border-white/10 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white hover:bg-white/10 transition-all flex items-center gap-2 shadow-xl"
          >
            <Users className="w-4 h-4 text-yellow-500" />
            Add Icon
          </button>

          <label
            className="px-6 py-3.5 bg-linear-to-r from-yellow-600 to-amber-500 border border-yellow-500/20 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white shadow-xl shadow-yellow-500/20 hover:scale-105 transition-all flex items-center gap-2 cursor-pointer disabled:opacity-50"
          >
            {isImporting ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
            {isImporting ? "Processing..." : "Upload CSV"}
            <input type="file" className="hidden" accept=".xlsx,.xls,.csv" onChange={handleImportIcons} disabled={isImporting} />
          </label>
        </div>
      </div>

      {/* ── PDF GENERATION OVERLAY ── */}
      {pdfProgress.active && (
        <div className="fixed inset-0 z-200 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-md" />
          <div className="relative w-full max-w-md bg-slate-900 border border-white/10 rounded-3xl p-10 text-center shadow-2xl">
            <div className="relative w-32 h-32 mx-auto mb-8">
              <div className="absolute inset-0 rounded-full border-4 border-white/5" />
              <div
                className="absolute inset-0 rounded-full border-4 border-yellow-500 border-t-transparent animate-spin"
                style={{ animationDuration: '2s' }}
              />
              <div className="absolute inset-0 flex items-center justify-center flex-col">
                <span className="text-2xl font-black text-white">{Math.round((pdfProgress.current / pdfProgress.total) * 100)}%</span>
                <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Complete</span>
              </div>
            </div>
            <h3 className="text-xl font-black text-white uppercase tracking-tight mb-2">Preparing <span className="text-yellow-500">PDF Roster</span></h3>
            <p className="text-sm text-slate-400 font-medium mb-6">Processing {pdfProgress.current} of {pdfProgress.total} players...</p>
            <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
              <div
                className="h-full bg-yellow-500 transition-all duration-300 shadow-[0_0_15px_rgba(234,179,8,0.5)]"
                style={{ width: `${(pdfProgress.current / pdfProgress.total) * 100}%` }}
              />
            </div>
          </div>
        </div>
      )}

      {/* ── PARSED DATA TABLE ── */}
      {importedData.length > 0 && (
        <div className="bg-[#111827]/40 backdrop-blur-3xl rounded-[2.5rem] border border-white/5 overflow-hidden">
          <div className="px-8 py-6 border-b border-white/5 flex items-center justify-between">
            <h2 className="text-xl font-black text-white">Parsed <span className="text-yellow-500">Icon Data</span></h2>
            <button
              onClick={() => setImportedData([])}
              className="p-2 hover:bg-white/5 rounded-full"
            >
              <AlertCircle className="w-5 h-5 text-slate-500" />
            </button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-white/5 border-b border-white/10">
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Team Name</th>
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Player Name</th>
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Icon No</th>
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Village</th>
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-500">Photo</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {importedData.map((row, idx) => (
                  <tr key={idx} className="group hover:bg-white/2 transition-all">
                    <td className="px-6 py-4">
                      <span className="text-sm font-black text-white">{row.teamName}</span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        {row.imageUrl ? (
                          <img src={getMediaUrl(row.imageUrl)} alt={row.name} className="w-8 h-8 rounded-lg object-cover border border-white/10" />
                        ) : (
                          <div className="w-8 h-8 rounded-lg bg-slate-800 flex items-center justify-center text-[10px] font-black text-slate-600 uppercase">
                            {row.name?.[0] || 'P'}
                          </div>
                        )}
                        <div>
                          <p className="text-sm font-bold text-white leading-none">{row.name}</p>
                          <span className="text-[8px] font-black uppercase tracking-widest text-slate-500 mt-1 block">{row.type}</span>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-sm font-bold text-slate-400">{row.mobile}</span>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-sm font-bold text-slate-400">{row.village || "-"}</span>
                    </td>
                    <td className="px-6 py-4">
                      {row.imageUrl ? (
                        <a href={row.imageUrl} target="_blank" rel="noopener noreferrer" className="text-xs font-bold text-yellow-500 hover:text-yellow-400 hover:underline">
                          View Photo →
                        </a>
                      ) : (
                        <span className="text-xs text-slate-600">No Photo</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="px-8 py-6 bg-white/2 border-t border-white/5 flex items-center justify-between">
            <p className="text-sm font-bold text-slate-400">
              Total Icons: <span className="text-yellow-500 font-black">{importedData.length}</span>
            </p>
            <button
              onClick={() => setImportedData([])}
              className="px-6 py-3 bg-red-500/10 border border-red-500/20 rounded-xl text-xs font-black uppercase tracking-widest text-red-400 hover:bg-red-500/20 transition-all"
            >
              Clear Table
            </button>
          </div>
        </div>
      )}

      {/* ── ELITE ROSTER GRID ── */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredIcons.map((p) => (
          <div key={p._id} className="relative group overflow-hidden bg-[#111827]/40 backdrop-blur-3xl rounded-[2.5rem] border border-white/5 hover:border-yellow-500/30 transition-all duration-500 shadow-2xl">

            {/* Background Accent */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-yellow-500/5 blur-[60px] rounded-full pointer-events-none" />

            {/* Profile Header */}
            <div className="p-8">
              <div className="flex items-start justify-between mb-6">
                <div className="relative">
                  <div
                    onClick={() => setEditImageTarget({ id: p._id, url: p.imageUrl, name: p.name })}
                    className="w-20 h-20 rounded-4xl overflow-hidden border-2 border-yellow-500/20 shadow-xl group-hover:scale-110 transition-transform duration-700 cursor-pointer relative group/img"
                  >
                    {p.imageUrl ? (
                      <img
                        src={getMediaUrl(p.imageUrl)}
                        alt={p.name}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          const parent = e.target.parentElement;
                          e.target.style.display = 'none';
                          if (parent && !parent.querySelector('.fallback-initial')) {
                            const span = document.createElement('span');
                            span.className = 'fallback-initial text-3xl font-black text-slate-600 uppercase';
                            span.innerText = p.name?.[0] || 'P';
                            parent.appendChild(span);
                          }
                        }}
                      />
                    ) : (
                      <div className="w-full h-full bg-slate-800 flex items-center justify-center font-black text-3xl text-slate-600">
                        {p.name?.[0]}
                      </div>
                    )}
                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity">
                      <Edit3 className="w-6 h-6 text-yellow-500" />
                    </div>
                  </div>
                  <div className="absolute -bottom-2 -right-2 bg-yellow-500 text-black px-2 py-1 rounded-lg text-[8px] font-black uppercase tracking-tighter shadow-lg shadow-yellow-500/20 z-10">
                    ⭐ ICON
                  </div>
                </div>

                <div className="text-right flex flex-col items-end gap-2">
                  <div className="text-[10px] font-black text-yellow-500 bg-yellow-500/10 px-2.5 py-1 rounded-full border border-yellow-500/20 uppercase tracking-widest inline-flex items-center gap-1">
                    ICON ID: {p.iconId}
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => setEditingPlayer(p)}
                      className="p-2 bg-white/5 hover:bg-yellow-500/20 rounded-xl text-slate-400 hover:text-yellow-500 transition-all border border-white/5 hover:border-yellow-500/30 shadow-lg"
                      title="Edit Player Details"
                    >
                      <Edit3 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={async (e) => {
                        e.stopPropagation();
                        if (window.confirm(`Are you sure you want to delete ${p.name}?`)) {
                          try {
                            setLoading(true);
                            const res = await fetch(`${API_URL}/api/players/${p._id}`, {
                              method: "DELETE",
                              headers: {
                                "Authorization": `Bearer ${session?.accessToken}`
                              }
                            });
                            if (res.ok) {
                              alert("Icon player deleted successfully");
                              fetchIcons();
                              socket?.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
                            } else {
                              alert("Failed to delete icon player");
                            }
                          } catch (err) {
                            alert("Error deleting icon player");
                          } finally {
                            setLoading(false);
                          }
                        }
                      }}
                      className="p-2 bg-white/5 hover:bg-red-500/20 rounded-xl text-slate-400 hover:text-red-500 transition-all border border-white/5 hover:border-red-500/30 shadow-lg"
                      title="Delete Icon Player"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>

              <div className="space-y-1">
                <h3 className="text-2xl font-black text-white group-hover:text-yellow-500 transition-colors uppercase leading-none">{p.name}</h3>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em]">{p.role}</p>
              </div>
            </div>

            {/* Allocation Matrix */}
            <div className="px-8 py-6 bg-white/2 border-t border-white/5 grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Village</p>
                <div className="flex items-center gap-2">
                  <p className="text-sm font-black text-white truncate">{p.village || "-"}</p>
                </div>
              </div>
              <div className="space-y-1 text-right">
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Assigned Team</p>
                <div className="flex items-center justify-end gap-2">
                  <Trophy className="w-3.5 h-3.5 text-yellow-500/60" />
                  <p className="text-sm font-black text-white">{getTeamName(p)}</p>
                </div>
              </div>
            </div>
          </div>
        ))}

        {filteredIcons.length === 0 && (
          <div className="col-span-full py-40 flex flex-col items-center justify-center text-center opacity-30 italic font-black uppercase tracking-[0.5em] text-slate-500">
            No Icon Players Found
          </div>
        )}
      </div>

      {/* ── ADD ICON MODAL ── */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-150 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => setIsAddModalOpen(false)} />
          <div className="relative w-full max-w-lg bg-slate-900 border border-white/10 rounded-[3rem] p-10 shadow-2xl overflow-hidden">
            {/* Background Glow */}
            <div className="absolute -top-24 -right-24 w-48 h-48 bg-yellow-500/10 blur-[80px] rounded-full" />

            <div className="relative">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-2xl font-black text-white uppercase tracking-tight">Add New <span className="text-yellow-500">Icon</span></h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Manual Player Registry</p>
                </div>
                <button onClick={() => setIsAddModalOpen(false)} className="p-3 hover:bg-white/5 rounded-2xl transition-all">
                  <X className="w-6 h-6 text-slate-500" />
                </button>
              </div>

              <div className="space-y-6">
                {/* Photo Section */}
                <div className="flex flex-col items-center gap-4 py-4">
                  <div className="relative group">
                    <div className="w-32 h-32 rounded-4xl bg-white/5 border-2 border-dashed border-white/10 overflow-hidden flex items-center justify-center group-hover:border-yellow-500/50 transition-all">
                      {newIcon.imageUrl ? (
                        <img src={getProxiedImageUrl(newIcon.imageUrl)} alt="Preview" className="w-full h-full object-cover" />
                      ) : (
                        <div className="text-center">
                          <Camera className="w-8 h-8 text-slate-600 mx-auto mb-2" />
                          <span className="text-[8px] font-black text-slate-600 uppercase">No Photo</span>
                        </div>
                      )}
                      {isUploading && (
                        <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center">
                          <RefreshCw className="w-6 h-6 text-yellow-500 animate-spin" />
                        </div>
                      )}
                    </div>
                    <label className="absolute -bottom-2 -right-2 bg-yellow-500 text-black p-2.5 rounded-2xl shadow-xl cursor-pointer hover:scale-110 active:scale-95 transition-all">
                      <Upload className="w-4 h-4" />
                      <input
                        type="file"
                        className="hidden"
                        accept="image/*"
                        onChange={(e) => {
                          if (e.target.files?.[0]) handlePhotoUpload(e.target.files[0]);
                        }}
                      />
                    </label>
                  </div>
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Player Photograph</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Player Name</label>
                    <input
                      type="text"
                      placeholder="Full Name"
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-white font-bold outline-none focus:border-yellow-500 transition-all"
                      value={newIcon.name}
                      onChange={e => setNewIcon({ ...newIcon, name: e.target.value })}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Team Retained</label>
                    <select
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-white font-bold outline-none focus:border-yellow-500 transition-all appearance-none cursor-pointer"
                      value={newIcon.team}
                      onChange={e => setNewIcon({ ...newIcon, team: e.target.value })}
                    >
                      <option value="" className="bg-slate-900">Select Team</option>
                      {teams.map(t => (
                        <option key={t._id} value={t._id} className="bg-slate-900">{t.name}</option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Mobile Number</label>
                    <input
                      type="text"
                      placeholder="Optional"
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-white font-bold outline-none focus:border-yellow-500 transition-all"
                      value={newIcon.mobile}
                      onChange={e => setNewIcon({ ...newIcon, mobile: e.target.value })}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Village/Town</label>
                    <input
                      type="text"
                      placeholder="Optional"
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-white font-bold outline-none focus:border-yellow-500 transition-all"
                      value={newIcon.village}
                      onChange={e => setNewIcon({ ...newIcon, village: e.target.value })}
                    />
                  </div>
                </div>

                <div className="pt-6">
                  <button
                    onClick={handleAddIcon}
                    disabled={loading || isUploading}
                    className="w-full py-5 bg-linear-to-r from-yellow-600 to-amber-500 border border-yellow-500/20 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white shadow-xl shadow-yellow-500/20 hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50"
                  >
                    {loading ? "Adding Player..." : "Create Icon Player"}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── DELETE RANGE MODAL ── */}
      {isDeleteRangeModalOpen && (
        <div className="fixed inset-0 z-150 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => setIsDeleteRangeModalOpen(false)} />
          <div className="relative w-full max-w-md bg-slate-900 border border-white/10 rounded-3xl p-8 shadow-2xl">
            <h3 className="text-xl font-black text-white mb-6 uppercase tracking-wider flex items-center gap-3">
              <AlertTriangle className="w-6 h-6 text-red-500" />
              Delete <span className="text-red-500">Icon Range</span>
            </h3>

            <div className="space-y-4 mb-8">
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2 block">From Row Number</label>
                <input
                  type="number"
                  placeholder="e.g. 1"
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white font-bold outline-none focus:border-red-500 transition-all"
                  value={deleteRange.from}
                  onChange={e => setDeleteRange({ ...deleteRange, from: e.target.value })}
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2 block">To Row Number</label>
                <input
                  type="number"
                  placeholder="e.g. 5"
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white font-bold outline-none focus:border-red-500 transition-all"
                  value={deleteRange.to}
                  onChange={e => setDeleteRange({ ...deleteRange, to: e.target.value })}
                />
              </div>
              <p className="text-[10px] text-slate-500 italic leading-relaxed">
                Note: This will delete icon players based on their current order in the list (from row X to row Y).
              </p>
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setIsDeleteRangeModalOpen(false)}
                className="flex-1 py-4 bg-white/5 hover:bg-white/10 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-400 transition-all"
              >
                Cancel
              </button>
              <button
                onClick={handleDeleteRange}
                className="flex-1 py-4 bg-red-600 hover:bg-red-700 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white shadow-xl shadow-red-500/20 transition-all"
              >
                Delete Range
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── IMAGE EDIT MODAL ── */}
      {editImageTarget && (
        <ImageEditModal
          title={`Edit Photo: ${editImageTarget.name}`}
          initialImage={getProxiedImageUrl(editImageTarget.url)}
          onClose={() => setEditImageTarget(null)}
          onSave={async (file) => {
            try {
              const fileType = file.type;
              const response = await fetch(`${API_URL}/api/upload/get-upload-url?fileType=${fileType}&folder=players`);
              if (!response.ok) throw new Error(`Upload URL failed: ${response.status}`);
              const { uploadUrl, fileUrl } = await response.json();

              await fetch(uploadUrl, { method: "PUT", body: file, headers: { "Content-Type": fileType } });

              const res = await fetch(`${API_URL}/api/players/${editImageTarget.id}`, {
                method: "PATCH",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ imageUrl: fileUrl })
              });

              if (res.ok) {
                socket?.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
                fetchIcons();
              } else {
                const errorData = await res.json().catch(() => ({ message: "Update failed" }));
                throw new Error(errorData.message || "Failed to update player image");
              }
            } catch (err) {
              console.error("Photo update failed", err);
              alert("Photo update failed");
            }
          }}
        />
      )}

      {/* ── PLAYER EDIT MODAL (Name & Details) ── */}
      {editingPlayer && (
        <div className="fixed inset-0 z-110 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setEditingPlayer(null)} />
          <div className="relative w-full max-w-md bg-[#111827] border border-white/10 rounded-[2.5rem] overflow-hidden shadow-2xl animate-in fade-in zoom-in-95 duration-200">
            <div className="p-8">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-xl font-black text-white">Edit <span className="text-yellow-500">Player</span></h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Modify registry records</p>
                </div>
                <button onClick={() => setEditingPlayer(null)} className="p-2 hover:bg-white/5 rounded-full transition-colors">
                  <X className="w-5 h-5 text-slate-500" />
                </button>
              </div>

              <div className="max-h-[60vh] overflow-y-auto pr-2 space-y-6 scrollbar-thin scrollbar-thumb-white/10">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Full Name</label>
                    <input
                      type="text"
                      value={editingPlayer.name}
                      onChange={(e) => setEditingPlayer({ ...editingPlayer, name: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 font-bold text-white focus:border-yellow-500 outline-none transition-all"
                      placeholder="Enter name"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Mobile</label>
                    <input
                      type="text"
                      value={editingPlayer.mobile || ""}
                      onChange={(e) => setEditingPlayer({ ...editingPlayer, mobile: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 font-bold text-white focus:border-yellow-500 outline-none transition-all"
                      placeholder="Mobile number"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Village</label>
                    <input
                      type="text"
                      value={editingPlayer.village || ""}
                      onChange={(e) => setEditingPlayer({ ...editingPlayer, village: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 font-bold text-white focus:border-yellow-500 outline-none transition-all"
                      placeholder="Village name"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Primary Role</label>
                    <select
                      value={editingPlayer.role}
                      onChange={(e) => setEditingPlayer({ ...editingPlayer, role: e.target.value })}
                      className="w-full bg-[#1e293b] border border-white/10 rounded-2xl px-5 py-4 font-bold text-white focus:border-yellow-500 outline-none transition-all"
                    >
                      <option value="All-Rounder" className="bg-[#1e293b] text-white">All-Rounder</option>
                      <option value="Batting All-Rounder" className="bg-[#1e293b] text-white">Batting All-Rounder</option>
                      <option value="Bowling All-Rounder" className="bg-[#1e293b] text-white">Bowling All-Rounder</option>
                      <option value="Batsman" className="bg-[#1e293b] text-white">Batsman</option>
                      <option value="Opening Batsman" className="bg-[#1e293b] text-white">Opening Batsman</option>
                      <option value="Middle Order Batsman" className="bg-[#1e293b] text-white">Middle Order Batsman</option>
                      <option value="Bowler" className="bg-[#1e293b] text-white">Bowler</option>
                      <option value="Fast Bowler" className="bg-[#1e293b] text-white">Fast Bowler</option>
                      <option value="Spin Bowler" className="bg-[#1e293b] text-white">Spin Bowler</option>
                      <option value="Wicket-Keeper" className="bg-[#1e293b] text-white">Wicket-Keeper</option>
                      <option value="Wicket-Keeper Batsman" className="bg-[#1e293b] text-white">Wicket-Keeper Batsman</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Icon Role</label>
                    <select
                      value={editingPlayer.iconRole || "none"}
                      onChange={(e) => setEditingPlayer({ ...editingPlayer, iconRole: e.target.value === "none" ? null : e.target.value })}
                      className="w-full bg-[#1e293b] border border-white/10 rounded-2xl px-5 py-4 font-bold text-white focus:border-yellow-500 outline-none transition-all"
                    >
                      <option value="none" className="bg-[#1e293b] text-white">Standard Icon</option>
                      <option value="captain" className="bg-[#1e293b] text-white">Captain</option>
                      <option value="viceCaptain" className="bg-[#1e293b] text-white">Vice Captain</option>
                      <option value="retained" className="bg-[#1e293b] text-white">Retained</option>
                    </select>
                  </div>
                </div>

                <div className="flex items-center gap-4 pt-4">
                  <button
                    onClick={() => {
                      const target = { id: editingPlayer._id, url: editingPlayer.imageUrl, name: editingPlayer.name };
                      setEditingPlayer(null);
                      setEditImageTarget(target);
                    }}
                    className="flex-1 px-6 py-4 bg-white/5 border border-white/10 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white hover:bg-white/10 transition-all flex items-center justify-center gap-2"
                  >
                    <Camera className="w-4 h-4 text-yellow-500" />
                    Change Photo
                  </button>
                  <button
                    onClick={async () => {
                      if (window.confirm("Are you sure you want to remove this player from the elite registry?")) {
                        try {
                          const res = await fetch(`${API_URL}/api/players/${editingPlayer._id}`, {
                            method: "DELETE"
                          });
                          if (res.ok) {
                            socket?.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
                            fetchIcons();
                            setEditingPlayer(null);
                          } else {
                            const errorData = await res.json().catch(() => ({ message: "Delete failed" }));
                            alert(`Delete failed: ${errorData.message || res.statusText}`);
                          }
                        } catch (err) {
                          console.error("Delete failed", err);
                        }
                      }
                    }}
                    className="px-6 py-4 bg-red-500/10 border border-red-500/20 rounded-2xl text-[10px] font-black uppercase tracking-widest text-red-500 hover:bg-red-500/20 transition-all flex items-center justify-center gap-2"
                  >
                    Delete Player
                  </button>
                </div>
              </div>

              <div className="mt-8">
                <button
                  onClick={async () => {
                    try {
                      setIsImporting(true);
                      const res = await fetch(`${API_URL}/api/players/${editingPlayer._id}`, {
                        method: "PATCH",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({
                          name: editingPlayer.name,
                          role: editingPlayer.role,
                          mobile: editingPlayer.mobile,
                          village: editingPlayer.village,
                          iconRole: editingPlayer.iconRole
                        })
                      });

                      if (res.ok) {
                        socket?.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
                        fetchIcons();
                        setEditingPlayer(null);
                      } else {
                        const errorData = await res.json().catch(() => ({ message: "Unknown error" }));
                        alert(`Failed to update player: ${errorData.message || res.statusText}`);
                      }
                    } catch (err) {
                      console.error("Save failed", err);
                    } finally {
                      setIsImporting(false);
                    }
                  }}
                  disabled={isImporting}
                  className="w-full py-4 bg-linear-to-r from-yellow-600 to-amber-500 border border-yellow-500/20 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white shadow-xl shadow-yellow-500/20 hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50"
                >
                  {isImporting ? "Processing..." : "Save Changes"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import {
  PlusCircle, Trash2, RefreshCw,
  Eye, Camera, Upload, AlertCircle, Home,
  Edit2, Check, X, Crop } from
"lucide-react";
import { uploadToS3 } from "../../../lib/uploadToS3";
import { API_URL } from "../../../lib/apiConfig";
import ImageCropperModal from "../../../components/ImageCropperModal";

// ── Section Component ─────────────────────────────────────
const Section = ({ title, desc, icon: Icon, children }) =>
<div className="bg-[#111827]/40 backdrop-blur-xl border border-white/5 rounded-4xl overflow-hidden shadow-2xl">
    <div className="px-8 py-6 border-b border-white/5 flex items-center gap-4">
      <div className="p-3 rounded-2xl bg-violet-600/10 border border-violet-500/20 text-violet-400">
        <Icon className="w-5 h-5" />
      </div>
      <div>
        <h2 className="text-xl font-black text-white">{title}</h2>
        <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-0.5">{desc}</p>
      </div>
    </div>
    <div className="p-8">{children}</div>
  </div>;


export default function LandingSettings() {
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [newImageData, setNewImageData] = useState({
    name: "",
    location: "",
    year: new Date().getFullYear().toString(),
    teams: ""
  });

  // Edit State
  const [editingImage, setEditingImage] = useState(null);
  const [isCropping, setIsCropping] = useState(false);

  useEffect(() => {
    fetchAssets();
  }, []);

  const fetchAssets = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_URL}/api/tournament-images?tournamentId=landing&all=true`);
      const data = await res.json();
      setImages(data.data || []);
    } catch (err) {
      console.error("Asset fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleToggleActive = async (id, currentStatus) => {
    try {
      const res = await fetch(`${API_URL}/api/tournament-images/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: !currentStatus })
      });
      if (res.ok) fetchAssets();
    } catch (err) {
      console.error("Toggle error:", err);
    }
  };

  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    if (!newImageData.name || !newImageData.location) {
      alert("Please enter a name and location for this image first.");
      return;
    }

    setUploading(true);
    try {
      const url = await uploadToS3(file, 'gallery');

      const body = {
        ...newImageData,
        imageUrl: url,
        tournamentId: null
      };

      const res = await fetch(`${API_URL}/api/tournament-images`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });

      if (res.ok) {
        alert("Success! New image added to the carousel.");
        fetchAssets();
        setNewImageData({
          name: "",
          location: "",
          year: new Date().getFullYear().toString(),
          teams: ""
        });
      } else {
        const errorData = await res.json();
        alert("Server Error: " + (errorData.message || "Failed to save image info"));
      }
    } catch (err) {
      alert("Upload error: " + err.message);
    } finally {
      setUploading(false);
      if (e && e.target) e.target.value = "";
    }
  };

  const handleDelete = async (id) => {
    if (!confirm("Are you sure you want to remove this image from the home page?")) return;

    try {
      const res = await fetch(`${API_URL}/api/tournament-images/${id}`, {
        method: 'DELETE'
      });
      if (res.ok) fetchAssets();
    } catch (err) {
      alert("Delete error: " + err.message);
    }
  };

  const handleUpdate = async () => {
    if (!editingImage) return;
    setUploading(true);
    try {
      const res = await fetch(`${API_URL}/api/tournament-images/${editingImage._id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(editingImage)
      });
      if (res.ok) {
        setEditingImage(null);
        fetchAssets();
      }
    } catch (err) {
      alert("Update error: " + err.message);
    } finally {
      setUploading(false);
    }
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-64 gap-3">
      <div className="w-8 h-8 border-4 border-violet-500/20 border-t-violet-500 rounded-full animate-spin" />
      <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Loading Landing Assets</p>
    </div>);


  return (
    <div className="space-y-10 max-w-5xl mx-auto pb-20">

      <div className="flex items-center justify-between px-2">
        <div>
          <h1 className="text-3xl font-black text-white tracking-tight">
            Home <span className="text-violet-500">Carousel</span>
          </h1>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-widest mt-1 opacity-60">Manage images shown on the public landing page</p>
        </div>
        <button onClick={fetchAssets} className="p-3 bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 text-slate-400 transition-all">
          <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <Section title="Add Image" desc="Upload new carousel slide" icon={Upload}>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 block">Tournament Name</label>
                <input
                  type="text"
                  value={newImageData.name}
                  onChange={(e) => setNewImageData({ ...newImageData, name: e.target.value })}
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:border-violet-500 outline-none placeholder-slate-700"
                  placeholder="e.g. Jakanachari Cup" />
                
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 block">Location</label>
                <input
                  type="text"
                  value={newImageData.location}
                  onChange={(e) => setNewImageData({ ...newImageData, location: e.target.value })}
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:border-violet-500 outline-none placeholder-slate-700"
                  placeholder="e.g. Tumkur" />
                
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 block">Year</label>
                  <input
                    type="text"
                    value={newImageData.year}
                    onChange={(e) => setNewImageData({ ...newImageData, year: e.target.value })}
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:border-violet-500 outline-none placeholder-slate-700"
                    placeholder="2026" />
                  
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 block">Teams</label>
                  <input
                    type="text"
                    value={newImageData.teams}
                    onChange={(e) => setNewImageData({ ...newImageData, teams: e.target.value })}
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:border-violet-500 outline-none placeholder-slate-700"
                    placeholder="10 Teams" />
                  
                </div>
              </div>

              <label className={`w-full flex items-center justify-center gap-3 py-4 rounded-xl font-black text-xs transition-all border-2 border-dashed
                ${uploading ? 'bg-violet-500/10 border-violet-500/20 text-violet-400' : 'bg-white/5 border-white/10 text-slate-400 hover:border-violet-500/40 cursor-pointer'}`}>
                {uploading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Camera className="w-4 h-4" />}
                {uploading ? "UPLOADING..." : "SELECT & UPLOAD PHOTO"}
                <input type="file" className="hidden" accept="image/*" onChange={handleUpload} disabled={uploading} />
              </label>
            </div>
          </Section>
        </div>

        <div className="lg:col-span-2">
          <Section title="Current Carousel" desc="Shuffle or remove active slides" icon={Camera}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {images.length === 0 &&
              <div className="col-span-full py-12 text-center border-2 border-dashed border-white/5 rounded-3xl">
                  <p className="text-slate-600 text-sm uppercase tracking-widest italic font-black">No images in carousel</p>
                </div>
              }
              {images.map((img) =>
              <div key={img._id} className="relative aspect-4/3 rounded-2xl overflow-hidden border border-white/10 group shadow-lg">
                  <img src={img.imageUrl} alt={img.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                  <div className="absolute inset-0 bg-linear-to-t from-black/90 via-black/20 to-transparent p-6 flex flex-col justify-end">
                    <div className="flex items-center justify-between gap-4">
                      <div className="min-w-0">
                        <p className="text-[10px] font-black text-violet-400 uppercase tracking-widest">{img.year} • {img.teams}</p>
                        <p className="text-sm font-black text-white truncate">{img.name}</p>
                      </div>
                      <div className="flex gap-2">
                        <button
                        onClick={(e) => {e.stopPropagation();handleToggleActive(img._id, img.isActive);}}
                        className={`p-2 rounded-lg transition-all ${img.isActive ? 'bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500 hover:text-white' : 'bg-slate-500/20 text-slate-400 hover:bg-slate-500 hover:text-white'}`}
                        title={img.isActive ? "Turn OFF" : "Turn ON"}>
                        
                          <Check className={`w-4 h-4 ${!img.isActive && 'opacity-30'}`} />
                        </button>
                        <button onClick={() => setEditingImage(img)} className="p-2 bg-white/10 text-white rounded-lg hover:bg-white/20 transition-all opacity-0 group-hover:opacity-100">
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDelete(img._id)} className="p-2 bg-red-500/20 text-red-400 rounded-lg hover:bg-red-500 hover:text-white transition-all">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                  {!img.isActive &&
                <div className="absolute top-4 left-4 z-10 px-3 py-1 bg-black/60 backdrop-blur-md rounded-full border border-white/10 flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-slate-500 animate-pulse" />
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hidden</span>
                    </div>
                }
                  {img.isActive &&
                <div className="absolute top-4 left-4 z-10 px-3 py-1 bg-emerald-600/20 backdrop-blur-md rounded-full border border-emerald-500/30 flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                      <span className="text-[9px] font-black text-emerald-400 uppercase tracking-widest">Active</span>
                    </div>
                }
                </div>
              )}
            </div>
          </Section>
        </div>
      </div>

      {/* ── Edit Modal ── */}
      {editingImage &&
      <div className="fixed inset-0 z-100 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-[#0f172a] border border-white/10 rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
            <div className="px-8 py-5 border-b border-white/5 flex items-center justify-between bg-white/2 shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-violet-600/20 rounded-xl flex items-center justify-center text-violet-400 border border-violet-500/30">
                  <Edit2 className="w-4 h-4" />
                </div>
                <div>
                  <h3 className="text-lg font-black text-white leading-none">Edit Slide</h3>
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">Asset ID: {editingImage._id.slice(-6).toUpperCase()}</p>
                </div>
              </div>
              <button onClick={() => setEditingImage(null)} className="w-10 h-10 rounded-full bg-white/5 hover:bg-white/10 flex items-center justify-center text-slate-400">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto flex-1 custom-scrollbar">
              <div className="relative aspect-video rounded-2xl overflow-hidden border border-white/10 group">
                <img src={editingImage.imageUrl} className="w-full h-full object-cover" alt="" />
                <button
                onClick={() => setIsCropping(true)}
                className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all gap-2 text-white font-black text-xs uppercase">
                
                  <Crop className="w-4 h-4" /> CROP IMAGE
                </button>
              </div>

              <div className="grid grid-cols-1 gap-4">
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Tournament Name</label>
                  <input
                  type="text"
                  value={editingImage.name}
                  onChange={(e) => setEditingImage({ ...editingImage, name: e.target.value })}
                  className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-3 text-sm text-white focus:border-violet-500 outline-none" />
                
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Location</label>
                  <input
                  type="text"
                  value={editingImage.location}
                  onChange={(e) => setEditingImage({ ...editingImage, location: e.target.value })}
                  className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-3 text-sm text-white focus:border-violet-500 outline-none" />
                
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Year</label>
                    <input
                    type="text"
                    value={editingImage.year}
                    onChange={(e) => setEditingImage({ ...editingImage, year: e.target.value })}
                    className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-3 text-sm text-white focus:border-violet-500 outline-none" />
                  
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block">Teams</label>
                    <input
                    type="text"
                    value={editingImage.teams}
                    onChange={(e) => setEditingImage({ ...editingImage, teams: e.target.value })}
                    className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-3 text-sm text-white focus:border-violet-500 outline-none" />
                  
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-xl border ${editingImage.isActive ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' : 'bg-slate-500/10 border-slate-500/20 text-slate-400'}`}>
                    <Check className="w-4 h-4" />
                  </div>
                  <div>
                    <p className="text-sm font-bold text-white uppercase tracking-wide">Show on Home Page</p>
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Visibility status of this slide</p>
                  </div>
                </div>
                <button
                onClick={() => setEditingImage({ ...editingImage, isActive: !editingImage.isActive })}
                className={`relative w-12 h-6 rounded-full transition-all duration-300 ${editingImage.isActive ? 'bg-violet-600' : 'bg-slate-700'}`}>
                
                  <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all duration-300 ${editingImage.isActive ? 'left-7' : 'left-1'}`} />
                </button>
              </div>
            </div>

            <div className="px-8 py-6 bg-black/40 flex items-center gap-4 shrink-0">
              <button onClick={() => setEditingImage(null)} className="flex-1 py-4 bg-white/5 hover:bg-white/10 text-white rounded-2xl font-black text-xs uppercase transition-all">
                Cancel
              </button>
              <button onClick={handleUpdate} disabled={uploading} className="flex-1 py-4 bg-violet-600 hover:bg-violet-500 text-white rounded-2xl font-black text-xs uppercase shadow-xl shadow-violet-500/20 transition-all flex items-center justify-center gap-2">
                {uploading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
                Save Changes
              </button>
            </div>
          </div>
        </div>
      }

      {/* ── Cropper Modal Integration ── */}
      {isCropping && editingImage &&
      <ImageCropperModal
        imageUrl={editingImage.imageUrl}
        onClose={() => setIsCropping(false)}
        folder="gallery"
        initialAspect={16 / 9}
        onSave={(newUrl) => {
          setEditingImage({ ...editingImage, imageUrl: newUrl });
          setIsCropping(false);
        }} />

      }
    </div>);

}

"use client";

import { useSession, signOut } from "next-auth/react";
import { useRouter, usePathname } from "next/navigation";
import { useEffect, useState, createContext, useContext, useRef } from "react";
import Link from "next/link";
import {
  LayoutDashboard,
  PlusCircle,
  Trophy,
  Users,
  Zap,
  Image as ImageIcon,
  Settings,
  LogOut,
  Menu,
  X,
  ChevronRight,
  ChevronLeft,
  User,
  Layout,
  Star,
  ChevronDown,
  Check,
  Palette,
  Home,
  Eye
} from "lucide-react";
import { API_URL, getMediaUrl } from "../../lib/apiConfig";

// Create a Context for the selected Auction and shared Socket
const AuctionContext = createContext({
  selectedAuction: null,
  setSelectedAuction: () => {},
  allTournaments: [],
  socket: null,
  isConnected: false
});

export const useAuction = () => useContext(AuctionContext);

const navigation = [
  { name: "Dashboard", href: "/admin/dashboard", icon: LayoutDashboard, emoji: "📊" },
  { name: "Auctions", href: "/admin/tournaments", icon: Trophy, emoji: "🏏" },
  { name: "Teams", href: "/admin/teams", icon: Layout, emoji: "👥" },
  { name: "Players", href: "/admin/players", icon: User, emoji: "🧍" },
  { name: "Icon Players", href: "/admin/icons", icon: Star, emoji: "⭐" },
  { name: "Live Control", href: "/live-auction", icon: Zap, emoji: "⚡" },
  { name: "Live Scoring", href: "/scoring", icon: LayoutDashboard, emoji: "📱" },
  { name: "Match Control", href: "/admin/matches", icon: LayoutDashboard, emoji: "🎮" },
  { name: "Branding", href: "/admin/assets", icon: Palette, emoji: "🎨" },
  { name: "Landing Editor", href: "/admin/landing", icon: Layout, emoji: "🏗️" },
  { name: "Pricing & Services", href: "/admin/services", icon: LayoutDashboard, emoji: "💰" },
  { name: "Settings", href: "/admin/settings", icon: ImageIcon, emoji: "⚙️" },
];

export default function AdminLayout({ children }) {
  const { data: session, status } = useSession();
  const router = useRouter();
  const pathname = usePathname();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [tournaments, setTournaments] = useState([]);
  const [selectedAuction, setSelectedAuction] = useState(null);
  const [pendingApplications, setPendingApplications] = useState(0);

  useEffect(() => {
    if (typeof window !== "undefined") {
      const savedAuction = localStorage.getItem("selectedAuction");
      if (savedAuction) {
        try {
          setSelectedAuction(JSON.parse(savedAuction));
        } catch (e) { }
      }
      const savedCollapsed = localStorage.getItem("sidebarCollapsed");
      if (savedCollapsed) {
        setCollapsed(savedCollapsed === "true");
      }
    }
  }, []);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const dropdownRef = useRef(null);
  const socketRef = useRef(null);

  // System-wide socket monitoring
  useEffect(() => {
    import("socket.io-client").then(({ io }) => {
      const socket = io(API_URL, {
        transports: ["websocket", "polling"],
        withCredentials: true
      });
      socketRef.current = socket;

      socket.on("connect", () => setIsConnected(true));
      socket.on("disconnect", () => setIsConnected(false));
      socket.on("connect_error", () => setIsConnected(false));
    });

    return () => {
      socketRef.current?.disconnect();
    };
  }, []);

  // Close dropdown on outside click
  useEffect(() => {
    const handleClick = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setDropdownOpen(false);
      }
    };
    if (dropdownOpen) {
      document.addEventListener("mousedown", handleClick);
    }
    return () => document.removeEventListener("mousedown", handleClick);
  }, [dropdownOpen]);

  const handleSelectAuction = (auction) => {
    setSelectedAuction(auction);
    localStorage.setItem("selectedAuction", JSON.stringify(auction));
    setDropdownOpen(false);
  };

  async function fetchTournaments() {
    try {
      const url = `${API_URL}/api/tournaments`;
      console.log("Fetching tournaments from:", url);
      const res = await fetch(url);
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Server error: ${res.status} ${text}`);
      }
      const data = await res.json();

      // Safety check: Ensure data is an array to prevent .map crashes
      const tournamentsArray = Array.isArray(data) ? data : [];
      setTournaments(tournamentsArray);

      const saved = localStorage.getItem("selectedAuction");
      if (!saved && tournamentsArray.length > 0) {
        const active = tournamentsArray.find(t => t.status === "active") || tournamentsArray[0];
        handleSelectAuction(active);
      }
    } catch (err) {
      console.error("Fetch error:", err);
      setTournaments([]); // Fallback to empty array
    }
  }

  // Fetch all tournaments for the selector
  useEffect(() => {
    if (status === "authenticated") {
      const timeoutId = setTimeout(() => {
        fetchTournaments();
      }, 0);
      return () => clearTimeout(timeoutId);
    }
  }, [status]);

  // Poll for pending applications
  useEffect(() => {
    if (status === "authenticated") {
      const fetchPending = async () => {
        try {
          const res = await fetch(`${API_URL}/api/players`);
          if (res.ok) {
            const data = await res.json();
            const pendingCount = data.filter(p => p.status === 'pending' && (!selectedAuction || p.tournamentId === selectedAuction._id)).length;
            setPendingApplications(prev => {
              if (pendingCount > prev && prev !== 0) {
                // Flash alert or sound could be triggered here
              }
              return pendingCount;
            });
          }
        } catch (e) { }
      };

      fetchPending();
      const intervalId = setInterval(fetchPending, 15000); // Check every 15s
      return () => clearInterval(intervalId);
    }
  }, [status]);

  useEffect(() => {
    if (status === "loading") return;
    if (!session) { router.push("/login"); return; }
    if (session.user?.role !== "admin") { router.push("/"); return; }
  }, [session, status, router]);

  if (status === "loading") {
    return (
      <div className="min-h-screen bg-[#0B0F2A] flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-violet-500/30 border-t-violet-500 rounded-full animate-spin" />
          <p className="text-slate-400 font-bold tracking-widest uppercase text-xs">Loading Admin</p>
        </div>
      </div>
    );
  }

  if (!session || session.user?.role !== "admin") return null;

  const initials = session.user?.name?.[0]?.toUpperCase() || "A";

  return (
    <AuctionContext.Provider value={{ 
      selectedAuction, 
      setSelectedAuction: handleSelectAuction, 
      allTournaments: tournaments,
      socket: socketRef.current,
      isConnected
    }}>
      <div className="flex h-screen bg-[#0B0F2A] text-white overflow-hidden">

        {/* ── Mobile overlay ── */}
        {sidebarOpen && (
          <div
            className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm lg:hidden"
            onClick={() => setSidebarOpen(false)}
          />
        )}

        {/* ══════════ SIDEBAR ══════════ */}
        <aside className={`
          fixed inset-y-0 left-0 z-50 
          bg-[#0f172a]/90 backdrop-blur-2xl
          border-r border-white/10
          flex flex-col
          transition-all duration-300 ease-in-out
          lg:static lg:translate-x-0
          ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}
          ${collapsed ? "w-20" : "w-64"}
        `}>

          {/* Logo */}
          <div className={`flex items-center ${collapsed ? 'justify-center' : 'justify-between'} px-6 h-16 border-b border-white/10 shrink-0 relative`}>
            <Link href="/" className="flex items-center gap-2 group">
              <span className={`text-lg font-black tracking-tight group-hover:text-violet-400 transition-colors ${collapsed ? 'hidden' : 'block'}`}>
                🟡 Admin <span className="text-white">Panel</span>
              </span>
              {collapsed && <span className="text-xl">🟡</span>}
            </Link>
            {!collapsed && (
              <button
                onClick={() => setSidebarOpen(false)}
                className="lg:hidden text-slate-400 hover:text-white transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            )}

            {/* Collapse Toggle (Desktop Only Ribbon) */}
            <button
              onClick={() => {
                const newState = !collapsed;
                setCollapsed(newState);
                localStorage.setItem("sidebarCollapsed", newState);
              }}
              className="hidden lg:flex absolute top-1/2 -right-3 -translate-y-1/2 w-6 h-12 bg-[#1e293b] border border-white/10 rounded-lg items-center justify-center text-slate-400 hover:text-white hover:bg-violet-600 transition-all z-50 shadow-xl"
            >
              {collapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
            </button>
          </div>

          {/* New: Quick link to Public Site */}
          <div className={`px-4 pt-4 ${collapsed ? 'flex justify-center' : ''}`}>
            <Link
              href="/"
              className={`flex items-center justify-between bg-violet-600/10 hover:bg-violet-600/20 border border-violet-500/20 rounded-xl text-[10px] font-black uppercase tracking-widest text-violet-400 hover:text-white transition-all
                ${collapsed ? 'w-10 h-10 justify-center' : 'px-4 py-3 w-full'}
              `}
              title="View Public Site"
            >
              <span className={collapsed ? 'hidden' : 'block'}>Return to Home</span>
              <Home className={collapsed ? 'w-5 h-5' : 'w-4 h-4 text-violet-500'} />
            </Link>
          </div>

          {/* Global Action */}
          <div className={`px-4 py-6 ${collapsed ? 'flex justify-center' : ''}`}>
            <Link
              href="/admin/create-tournament"
              className={`flex items-center justify-center gap-2 rounded-2xl font-black text-xs text-black transition-all
                bg-linear-to-r from-violet-400 to-cyan-400
                shadow-[0_0_15px_rgba(139,92,246,0.3)]
                hover:shadow-[0_0_25px_rgba(139,92,246,0.6)]
                hover:scale-105 active:scale-95
                ${collapsed ? 'w-12 h-12' : 'w-full py-3'}
              `}
              onClick={() => setSidebarOpen(false)}
              title="Create Auction"
            >
              <PlusCircle className="w-5 h-5" />
              <span className={collapsed ? 'hidden' : 'block'}>🏗️ CREATE AUCTION</span>
            </Link>
          </div>

          {/* Nav links */}
          <nav className="flex-1 px-3 space-y-1 overflow-y-auto custom-scrollbar overflow-x-hidden">
            {!collapsed && <p className="px-5 mb-2 text-[10px] font-black uppercase tracking-[0.2em] text-slate-600">Console</p>}
            {navigation.map((item) => {
              const isActive = pathname === item.href || (item.href !== "/admin/dashboard" && pathname.startsWith(item.href));
              return (
                <Link
                  key={item.name}
                  href={item.href}
                  onClick={() => setSidebarOpen(false)}
                  title={collapsed ? item.name : ""}
                  className={`
                    group flex items-center gap-3 rounded-xl text-sm font-semibold
                    transition-all duration-200 relative overflow-hidden
                    ${collapsed ? 'px-0 justify-center h-12' : 'px-4 py-3'}
                    ${isActive
                      ? "bg-linear-to-r from-violet-600 to-cyan-500 text-white shadow-[0_0_20px_rgba(139,92,246,0.4)]"
                      : "text-slate-400 hover:text-white hover:bg-white/5"
                    }
                  `}
                >
                  <span className={`text-base grayscale group-hover:grayscale-0 transition-[filter] ${collapsed ? 'scale-110' : ''}`}>{item.emoji}</span>
                  <span className={`flex-1 transition-opacity duration-300 ${collapsed ? 'opacity-0 w-0' : 'opacity-100'}`}>{item.name}</span>
                  {item.name === "Players" && pendingApplications > 0 && !collapsed && (
                    <span className="flex h-5 w-5 items-center justify-center rounded-full bg-red-500 text-[10px] font-black text-white shrink-0 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.5)]">
                      {pendingApplications}
                    </span>
                  )}
                  {item.name === "Players" && pendingApplications > 0 && collapsed && (
                    <span className="absolute top-2 right-2 w-2 h-2 rounded-full bg-red-500 animate-pulse shadow-[0_0_8px_rgba(239,68,68,0.8)]"></span>
                  )}
                  {(isActive && !collapsed) && <ChevronRight className="w-4 h-4 opacity-70" />}
                </Link>
              );
            })}
          </nav>

          {/* User footer */}
          <div className={`shrink-0 border-t border-white/10 p-4 space-y-3 ${collapsed ? 'flex flex-col items-center' : ''}`}>
            <div className={`flex items-center gap-3 ${collapsed ? 'px-0' : 'px-2'}`}>
              <div className="w-10 h-10 rounded-2xl bg-linear-to-br from-violet-500 to-cyan-500 flex items-center justify-center font-black text-lg shadow-lg shadow-violet-500/30 shrink-0">
                {initials}
              </div>
              {!collapsed && (
                <div className="min-w-0">
                  <p className="text-sm font-black text-white truncate">{session.user?.name}</p>
                  <p className="text-[10px] text-yellow-400 font-black uppercase tracking-widest opacity-80">Root Master</p>
                </div>
              )}
            </div>
            <button
              onClick={() => signOut({ callbackUrl: "/" })}
              title="Sign Out"
              className={`flex items-center gap-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all
                ${collapsed ? 'w-10 h-10 justify-center p-0' : 'w-full px-4 py-2.5 hover:bg-red-500/10 hover:border-red-500/20 border border-transparent'}
                text-slate-500 hover:text-white
              `}
            >
              <LogOut className="w-4 h-4" />
              {!collapsed && <span>Sign Out</span>}
            </button>
          </div>
        </aside>

        {/* ══════════ MAIN AREA ══════════ */}
        <div className={`flex-1 flex flex-col min-w-0 overflow-hidden relative transition-all duration-300`}>

          {/* Background glow behind content */}
          <div className="absolute top-0 right-0 w-125 h-125 bg-violet-600/5 blur-[120px] rounded-full -translate-y-1/2 translate-x-1/2 pointer-events-none" />

          {/* ── Topbar ── */}
          <header className="shrink-0 h-14 md:h-16 flex items-center justify-between px-3 md:px-8
            border-b border-white/5 bg-[#0B0F2A]/70 backdrop-blur-xl z-30">

            <div className="flex items-center gap-2 md:gap-4 flex-1 min-w-0">
              <button
                onClick={() => setSidebarOpen(true)}
                className="lg:hidden p-2 rounded-xl text-slate-400 hover:text-white hover:bg-white/5 transition-all"
              >
                <Menu className="w-5 h-5 md:w-6 md:h-6" />
              </button>

              {/* AUCTION SELECTOR */}
              <div className="relative flex-1 max-w-60" ref={dropdownRef}>
                <button
                  onClick={() => setDropdownOpen(!dropdownOpen)}
                  className="flex items-center gap-2 px-3 py-1.5 md:px-4 md:py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl transition-all w-full"
                >
                  <Trophy className="w-3.5 h-3.5 text-yellow-400 shrink-0" />
                  <div className="flex-1 text-left min-w-0">
                    <p className="text-[7px] md:text-[8px] font-black uppercase tracking-widest text-slate-500">Selected Auction</p>
                    <p className="text-[10px] md:text-xs font-black text-white truncate">{selectedAuction ? selectedAuction.name : "Select Auction"}</p>
                  </div>
                  <ChevronDown className={`w-3.5 h-3.5 text-slate-500 transition-transform shrink-0 ${dropdownOpen ? 'rotate-180' : ''}`} />
                </button>

                {dropdownOpen && (
                  <div className="absolute top-full left-0 mt-2 w-70 bg-[#0f172a] border border-white/10 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2">
                    <div className="p-3 bg-white/5 border-b border-white/10">
                      <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Available Systems</p>
                    </div>
                    <div className="max-h-75 overflow-y-auto custom-scrollbar">
                      {tournaments.map((t) => (
                        <button
                          key={t._id}
                          onClick={() => handleSelectAuction(t)}
                          className="w-full flex items-center justify-between px-4 py-3 hover:bg-violet-600/20 text-left transition-all border-b border-white/5 last:border-0"
                        >
                          <div>
                            <p className="text-sm font-bold text-white leading-tight">{t.name}</p>
                            <p className="text-[10px] text-slate-500 font-semibold uppercase">{t.status}</p>
                          </div>
                          {selectedAuction?._id === t._id && <Check className="w-4 h-4 text-violet-400" />}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-4">
              {/* Live Status Pill (Dynamic) */}
              <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border transition-all ${isConnected ? 'bg-emerald-500/10 border-emerald-500/20' : 'bg-red-500/10 border-red-500/20'}`}>
                <span className={`w-2 h-2 rounded-full animate-pulse ${isConnected ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]'}`} />
                <span className={`text-[9px] font-black uppercase tracking-widest ${isConnected ? 'text-emerald-500' : 'text-red-500'}`}>
                  {isConnected ? "Server Online" : "Disconnected"}
                </span>
              </div>

              {/* Prioritize the LIVE auction for the Go Live button, regardless of what's selected in the editor */}
              {(() => {
                const live = tournaments.find(t => t.status === "active");
                const target = live || selectedAuction;
                return (
                  <Link
                    href={target ? `/live-auction?id=${target._id}&role=admin` : "#"}
                    className="px-3 py-2 md:px-4 md:py-2 rounded-xl text-[9px] md:text-[10px] font-black uppercase tracking-widest text-black
                      bg-linear-to-r from-yellow-400 to-yellow-600
                      shadow-lg shadow-yellow-500/20
                      hover:scale-105 active:scale-95 transition-all"
                  >
                    {live && live._id !== selectedAuction?._id ? (
                      <span className="flex items-center gap-1">
                        LIVE: <span className="opacity-70">{live.shortId || live.name.slice(0, 3)}</span>
                      </span>
                    ) : "Go Live"}
                  </Link>
                );
              })()}
            </div>

          </header>

          {/* ── Page content ── */}
          <main className="flex-1 overflow-y-auto p-4 lg:p-10 custom-scrollbar relative z-10">
            {children}
          </main>
        </div>
      </div>
    </AuctionContext.Provider>
  );
}

