const findValue = (row, keys) => {
  const rk = Object.keys(row);
  for (const k of keys) {
    const f = rk.find((key) =>
    key.toLowerCase().trim() === k.toLowerCase().trim() ||
    key.toLowerCase().includes(k.toLowerCase())
    );
    if (f) return row[f];
  }
  return null;
};

