                    onChange={(e) => setNewPlayer({ ...newPlayer, role: e.target.value })}>
                    
                      <option value="">Select Role</option>
                      {["Batsman", "Bowler", "All-Rounder", "Wicketkeeper", "WK-Batsman"].map((r) => <option key={r} value={r}>{r}</option>)}
