                    value={newPlayer.basePrice}
                    onChange={(e) => setNewPlayer({ ...newPlayer, basePrice: parseInt(e.target.value) || 0 })}
                    placeholder="Enter amount (e.g., 100)" />
                  
                    {formErrors.basePrice && <p className="text-[8px] text-red-400 font-bold mt-1">{formErrors.basePrice}</p>}
                  </div>

                  {/* Contact Number - REQUIRED with Validation */}
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 flex items-center gap-1">
                      Contact Number <span className="text-red-500">*</span>
                    </label>
                    <input
                    type="tel"
                    maxLength={10}
                    className={`w-full bg-slate-900 border ${formErrors.mobile ? 'border-red-500' : 'border-white/10'} rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500`}
                    value={newPlayer.mobile}
                    onChange={(e) => {
                      const val = e.target.value.replace(/\D/g, ''); // Only digits
                      setNewPlayer({ ...newPlayer, mobile: val });
                    }}
                    placeholder="10-digit mobile number" />
                  
                    {formErrors.mobile && <p className="text-[8px] text-red-400 font-bold mt-1">{formErrors.mobile}</p>}
                  </div>
                </div>

                {/* Right Column - Price & Photo */}
                <div className="space-y-4">
                  {/* Mobile Number - REQUIRED */}
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 flex items-center gap-1">
                      Contact Number <span className="text-red-500">*</span>
                    </label>
                    <input
                    type="tel"
                    maxLength={10}
                    className={`w-full bg-slate-900 border ${formErrors.mobile ? 'border-red-500' : 'border-white/10'} rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500`}
                    value={newPlayer.mobile}
                    onChange={(e) => {
                      const val = e.target.value.replace(/\D/g, '');
                      setNewPlayer({ ...newPlayer, mobile: val });
                    }}
                    placeholder="10-digit mobile number" />
                  
                    {formErrors.mobile && <p className="text-[8px] text-red-400 font-bold mt-1">{formErrors.mobile}</p>}
                  </div>

                  {/* Age & Village (Optional) */}
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Age (Optional)</label>
                      <input type="number" className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500" value={newPlayer.age} onChange={(e) => setNewPlayer({ ...newPlayer, age: parseInt(e.target.value) || 0 })} />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Location (Optional)</label>
                      <input className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500" value={newPlayer.village} onChange={(e) => setNewPlayer({ ...newPlayer, village: e.target.value })} placeholder="Village/Town" />
                    </div>
                  </div>

                  {/* Photo Upload */}
                  <div className="space-y-1.5 pt-2 border-t border-white/5">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">
                      Player Photo
                    </label>

                    <div className={`relative h-28 bg-white/5 border-2 ${formErrors.photo ? 'border-red-500' : 'border-dashed border-white/10'} rounded-2xl flex flex-col items-center justify-center group hover:border-violet-500/50 transition-all overflow-hidden`}>
                      {newPlayer.photo ?
                    <div className="text-center w-full h-full">
                          <img src={newPlayer.photo instanceof File ? URL.createObjectURL(newPlayer.photo) : newPlayer.photo} alt="Preview" className="w-full h-full object-cover" />
                          <button type="button" onClick={() => setNewPlayer({ ...newPlayer, photo: null })} className="absolute top-2 right-2 bg-red-500 text-white p-1 rounded-full hover:bg-red-600"><X size={12} /></button>
                        </div> :

                    <>
                          <Plus className="w-6 h-6 text-slate-600 group-hover:text-violet-500 transition-colors" />
                          <p className="text-[10px] font-black text-slate-600 uppercase mt-1">Upload Photo</p>
                          <input type="file" accept="image/*" onChange={(e) => setNewPlayer({ ...newPlayer, photo: e.target.files[0] })} className="absolute inset-0 opacity-0 cursor-pointer" />
                        </>
                    }
                    </div>
                  </div>

                  {/* Batting & Bowling Styles (Optional) */}
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Batting (Optional)</label>
                      <select className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500 cursor-pointer" value={newPlayer.battingStyle} onChange={(e) => setNewPlayer({ ...newPlayer, battingStyle: e.target.value })}>
                        <option value="Right Hand Bat">Right Hand</option>
                        <option value="Left Hand Bat">Left Hand</option>
                      </select>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Bowling (Optional)</label>
                      <input className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500" value={newPlayer.bowlingStyle} onChange={(e) => setNewPlayer({ ...newPlayer, bowlingStyle: e.target.value })} placeholder="Style" />
                    </div>
                  </div>
                </div>
              </div>

              {/* Icon Player Section */}
              {newPlayer.isIcon &&
            <div className="space-y-1.5 animate-in slide-in-from-top-2 border-t border-white/5 pt-4">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Assigned Team</label>
                  <select className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500" value={newPlayer.teamId} onChange={(e) => setNewPlayer({ ...newPlayer, teamId: e.target.value })}>
                    <option value="">Select Team</option>
                    {teams.map((t) => <option key={t._id} value={t._id}>{t.name}</option>)}
                  </select>
                </div>
            }

              <div className="flex items-center gap-2 p-3 bg-white/5 rounded-xl border border-white/5">
                <input type="checkbox" className="w-4 h-4 rounded border-white/10 accent-violet-500" checked={newPlayer.isIcon} onChange={(e) => setNewPlayer({ ...newPlayer, isIcon: e.target.checked })} id="icon-check" />
                <label htmlFor="icon-check" className="text-xs font-black text-slate-400 uppercase tracking-widest cursor-pointer">Mark as Icon Player</label>
              </div>

              <button
              onClick={handleAddPlayer}
              disabled={loading}
              className="w-full py-4 bg-linear-to-r from-violet-600 to-cyan-500 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-white shadow-xl shadow-violet-500/20 hover:scale-[1.02] active:scale-[0.98] transition-all mt-4 flex items-center justify-center gap-2 disabled:opacity-50">
              
                {loading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <ShieldCheck className="w-4 h-4" />}
                {loading ? "SAVING..." : "SAVE PLAYER TO DATABASE"}
              </button>
            </div>
          </div>
        </div>
      }


      {/* ── MANAGE/EDIT MODAL ── */}
      {isManageModalOpen &&
      <div className="fixed inset-0 z-100 flex items-center justify-center p-4 bg-black/90 backdrop-blur-sm">
          <div className="bg-[#0f172a] border border-white/10 rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl">
            <div className="px-8 py-6 border-b border-white/5 flex items-center justify-between">
              <h2 className="text-xl font-black text-white">System <span className="text-violet-500">Override</span></h2>
              <button onClick={() => setIsManageModalOpen(false)} className="p-2 hover:bg-white/5 rounded-full"><X className="w-5 h-5 text-slate-500" /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Name</label>
                  <input className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} /></div>
                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Role</label>
                  <select className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500" value={formData.role} onChange={(e) => setFormData({ ...formData, role: e.target.value })}>
                    {["Batsman", "Bowler", "All-Rounder", "Wicket Keeper", "WK-Batsman"].map((r) => <option key={r}>{r}</option>)}
                  </select></div>
              </div>

              <div className="space-y-1.5"><label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Life Status</label>
                <div className="flex gap-2">
                  {["available", "sold", "unsold"].map((s) =>
                <button key={s} onClick={() => setFormData({ ...formData, status: s })} className={`flex-1 py-3 rounded-xl text-[8px] font-black uppercase tracking-[0.2em] border transition-all ${formData.status === s ? 'bg-violet-600 border-violet-500 text-white shadow-xl' : 'bg-white/5 border-white/10 text-slate-500 hover:bg-white/10'}`}>{s}</button>
                )}
                </div></div>

              {formData.status === 'sold' &&
            <div className="grid grid-cols-2 gap-4 border-t border-white/5 pt-4 animate-in slide-in-from-top-2">
                  <div className="space-y-1.5"><label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Sold Price (₹)</label>
                    <input type="number" className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500" value={formData.soldPrice} onChange={(e) => setFormData({ ...formData, soldPrice: e.target.value })} /></div>
                  <div className="space-y-1.5"><label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Drafted Team</label>
                    <select className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500" value={formData.team} onChange={(e) => setFormData({ ...formData, team: e.target.value })}>
                      <option value="">Select Team</option>
                      {teams.map((t) => <option key={t._id} value={t._id}>{t.name}</option>)}
                    </select></div>
                </div>
            }

              <div className="flex items-center gap-2 p-3 bg-white/5 rounded-xl border border-white/5">
                <input type="checkbox" className="w-4 h-4 rounded border-white/10 accent-violet-500" checked={formData.isIcon} onChange={(e) => setFormData({ ...formData, isIcon: e.target.checked })} id="icon-edit" />
                <label htmlFor="icon-edit" className="text-xs font-black text-slate-400 uppercase tracking-widest cursor-pointer">Icon Player Status</label>
              </div>

              <button onClick={() => {setIsManageModalOpen(false);setIsConfirmModalOpen(true);}} className="w-full py-4 bg-linear-to-r from-violet-600 to-cyan-500 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white shadow-xl shadow-violet-500/20 hover:scale-105 transition-all">Stage Override</button>
            </div>
          </div>
        </div>
      }

      {/* ── SECURITY CONFIRMATION ── */}
      {isConfirmModalOpen &&
      <div className="fixed inset-0 z-110 flex items-center justify-center p-4 bg-black/95 backdrop-blur-md">
          <div className="bg-[#0f172a] border border-red-500/20 rounded-[2.5rem] w-full max-w-sm overflow-hidden shadow-[0_0_50px_rgba(239,68,68,0.2)]">
            <div className="p-8 text-center space-y-4">
              <div className="w-16 h-16 bg-red-500/10 rounded-3xl flex items-center justify-center mx-auto border border-red-500/20"><AlertTriangle className="w-8 h-8 text-red-500 animate-pulse" /></div>
              <div><h3 className="text-xl font-black text-white">Manual Write?</h3><p className="text-xs text-slate-500 mt-2">You are modifying sensitive live data for <span className="text-white font-black">{editingPlayer.name}</span>.</p></div>
              <div className="space-y-1.5 text-left"><label className="text-[9px] font-black uppercase tracking-widest text-slate-600">Type &quot;CONFIRM&quot; to proceed</label>
                <input className="w-full bg-slate-900 border border-red-500/20 rounded-xl px-4 py-3 text-center text-sm font-black text-red-400 outline-none" placeholder="CONFIRM" value={confirmText} onChange={(e) => setConfirmText(e.target.value.toUpperCase())} /></div>
              <div className="flex gap-2"><button onClick={() => setIsConfirmModalOpen(false)} className="flex-1 py-3 text-[10px] font-black uppercase text-slate-600">Abort</button>
                <button disabled={confirmText !== 'CONFIRM'} onClick={handleFinalConfirm} className="flex-1 py-3 bg-red-600 disabled:opacity-20 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-1"><ShieldCheck className="w-3 h-3" /> Commit</button></div>
            </div>
          </div>
        </div>
      }

      {/* ── IMAGE EDIT MODAL ── */}
      {editImageTarget &&
      <ImageEditModal
        title={`Edit Photo: ${editImageTarget.name}`}
        initialImage={editImageTarget.url}
        onClose={() => setEditImageTarget(null)}
        onSave={async (file) => {
          // Handle photo update via S3 and PATCH
          try {
            // 1. Get upload URL
            const fileType = file.type;
            const { uploadUrl, fileUrl } = await fetch(`${API_URL}/api/upload/get-upload-url?fileType=${fileType}&folder=players`).then((r) => r.json());

            // 2. Upload to S3
            await fetch(uploadUrl, { method: "PUT", body: file, headers: { "Content-Type": fileType } });

            // 3. Update DB
            const res = await fetch(`${API_URL}/api/players/${editImageTarget.id}`, {
              method: "PATCH",
              headers: {
                "Content-Type": "application/json",
                "Authorization": `Bearer ${session?.accessToken}`
              },
              body: JSON.stringify({ imageUrl: fileUrl })
            });

            if (res.ok) {
              socket.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
              fetchData();
            }
          } catch (err) {
            console.error("Photo update failed", err);
            alert("Photo update failed");
          }
        }} />

      }

      {/* ── BID HISTORY MODAL ── */}
      {historyPlayer &&
      <div className="fixed inset-0 z-120 flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-[#0B0F2A] border border-white/10 rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl flex flex-col max-h-[85vh]">
            <div className="px-8 py-6 border-b border-white/5 flex items-center justify-between bg-white/1">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-2xl bg-violet-600/20 flex items-center justify-center text-violet-400 border border-violet-500/20">
                  <RefreshCw className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-xl font-black text-white tracking-tight">Bid History</h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{historyPlayer.name}</p>
                </div>
              </div>
              <button onClick={() => setHistoryPlayer(null)} className="w-10 h-10 rounded-xl bg-white/5 hover:bg-white/10 flex items-center justify-center text-slate-400 hover:text-white transition-all border border-white/10">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-4 custom-scrollbar">
              {!historyPlayer.bidHistory || historyPlayer.bidHistory.length === 0 ?
            historyPlayer.status === 'sold' ?
            <div className="flex items-center justify-between p-4 bg-white/4 border border-violet-500/30 rounded-2xl group transition-all">
                    <div className="flex items-center gap-4">
                      <div className="w-8 h-8 rounded-lg bg-emerald-500/20 flex items-center justify-center text-[10px] font-black text-emerald-400 border border-emerald-500/20">
                        <ShieldCheck className="w-4 h-4" />
                      </div>
                      <div>
                        <Link
                    href={`/team/${historyPlayer.team?._id || historyPlayer.team}?tournament=${selectedAuction._id}&from=sold&highlight=${historyPlayer._id}`}
                    className="text-xs font-black text-white hover:text-violet-400 transition-colors uppercase tracking-tight block">
                    
                          {historyPlayer.team?.name || 'Assigned Team'}
                        </Link>
                        <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest italic">Final Award Entry</p>
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-1 text-right">
                      {historyPlayer.teamSlotId &&
                <Link
                  href={`/team/${historyPlayer.team?._id || historyPlayer.team}?tournament=${selectedAuction._id}&from=sold&highlight=${historyPlayer._id}`}
                  className="text-[8px] font-black text-cyan-400 bg-cyan-500/10 border border-cyan-500/20 px-2 py-0.5 rounded-md hover:bg-cyan-500/20 transition-all">
                  
                          {historyPlayer.teamSlotId}
                        </Link>
                }
                      <p className="text-sm font-black text-emerald-400">₹{historyPlayer.soldPrice?.toLocaleString()}</p>
                      <p className="text-[8px] text-emerald-500/40 font-black uppercase tracking-tighter">Legacy Record</p>
                    </div>
                  </div> :

            <div className="py-20 text-center space-y-4 opacity-40">
                    <ShieldAlert className="w-12 h-12 text-slate-500 mx-auto" />
                    <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">No Bidding Traffic Recorded</p>
                  </div> :


            <div className="space-y-3">
                  {[...historyPlayer.bidHistory].reverse().map((bid, idx) =>
              <div key={idx} className="flex items-center justify-between p-4 bg-white/2 border border-white/5 rounded-2xl group hover:border-violet-500/30 transition-all">
                      <div className="flex items-center gap-4">
                        <div className="w-8 h-8 rounded-lg bg-slate-800 flex items-center justify-center text-[10px] font-black text-slate-500 border border-white/5">
                          #{historyPlayer.bidHistory.length - idx}
                        </div>
                        <div>
                          <Link
                      href={`/team/${bid.teamId}?tournament=${selectedAuction._id}&from=sold&highlight=${historyPlayer._id}`}
                      className="text-xs font-black text-white hover:text-violet-400 transition-colors uppercase tracking-tight block">
                      
                            {bid.teamName}
                          </Link>
                          <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">
                            {new Date(bid.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                          </p>
                          <img
                      src={getProxiedImageUrl(historyPlayer)}
                      alt=""
                      className="w-full h-full object-cover"
                      onError={(e) => {
                        const parent = e.target.parentElement;
                        e.target.style.display = 'none';
                        if (parent && !parent.querySelector('.fallback-initial')) {
                          const span = document.createElement('span');
                          span.className = 'fallback-initial text-[10px] font-black text-white uppercase';
                          span.innerText = historyPlayer.name?.[0] || 'P';
                          parent.appendChild(span);
                        }
                      }} />
                    
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="text-sm font-black text-emerald-400">₹{bid.bidAmount?.toLocaleString()}</p>
                        <p className="text-[8px] text-slate-600 font-black uppercase tracking-tighter">Verified Bid</p>
                      </div>
                    </div>
              )}
                </div>
            }
            </div>

            <div className="p-8 bg-black/40 border-t border-white/5 flex items-center justify-between">
              <div className="flex flex-col">
                <span className="text-[9px] font-black uppercase text-slate-600 tracking-widest">Winning Status</span>
                <span className={`text-xs font-black uppercase ${historyPlayer.status === 'sold' ? 'text-emerald-400' : 'text-red-400'}`}>
                  {historyPlayer.status}
                </span>
              </div>
              <div className="text-right">
                <span className="text-[9px] font-black uppercase text-slate-600 tracking-widest">Final Price</span>
                <p className="text-xl font-black text-white">₹{historyPlayer.soldPrice?.toLocaleString() || '0'}</p>
              </div>
            </div>
          </div>
        </div>
      }
      {/* ── VERIFICATION MODAL ── */}
      {selectedVerifyPlayer &&
      <div className="fixed inset-0 z-1000 flex items-center justify-center p-6 bg-[#020617]/95 backdrop-blur-3xl animate-in fade-in duration-300">
          <div className="max-w-4xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] overflow-hidden shadow-2xl relative">
            <button onClick={() => setSelectedVerifyPlayer(null)} className="absolute top-8 right-8 w-12 h-12 bg-white/5 hover:bg-white/10 rounded-full flex items-center justify-center text-slate-400 transition-all z-20"><X size={20} /></button>
            <div className="grid grid-cols-1 md:grid-cols-12">
              <div className="md:col-span-5 bg-black/40 p-10 flex flex-col items-center gap-8 justify-center border-r border-white/5">
                <div id="admin-poster-canvas" style={{ backgroundColor: '#0f172a' }} className="p-6 rounded-[2.5rem] border border-white/10 shadow-2xl flex flex-col items-center gap-6">
                  <div className="text-center">
                    <h2 className="text-[8px] font-black uppercase tracking-[0.3em] text-[#a78bfa] opacity-80">PARMESHWAR CUP</h2>
                    <h1 className="text-sm font-black text-white italic tracking-tighter uppercase">Official Poster</h1>
                  </div>
                  <img
                  src={getImgUrl(selectedVerifyPlayer)}
                  crossOrigin="anonymous"
                  onError={(e) => {e.currentTarget.src = '/placeholder-player.png';}}
                  className="w-56 h-56 object-cover rounded-[2.5rem] border-4 border-white/10 shadow-xl" alt="" />
                
                  <div className="text-center space-y-1">
                    <h3 className="text-2xl font-black text-white italic tracking-tighter leading-none">{selectedVerifyPlayer.name}</h3>
                    <p className="text-[9px] font-black text-[#94a3b8] uppercase tracking-widest leading-none">ID #{selectedVerifyPlayer.applicationId}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-4 w-full pt-4 border-t border-white/5">
                    <div className="text-center"><p className="text-[7px] font-black text-[#475569] uppercase">ROLE</p><p className="text-[9px] font-black text-white">{selectedVerifyPlayer.role}</p></div>
                    <div className="text-center"><p className="text-[7px] font-black text-[#475569] uppercase">STYLE</p><p className="text-[9px] font-black text-white">{selectedVerifyPlayer.battingStyle || "RHB"}</p></div>
                  </div>
                </div>
                <div className="w-full space-y-6">
                  <div className="p-5 bg-white/5 rounded-2xl border border-white/10 group cursor-pointer hover:bg-white/10 transition-all" onClick={() => window.open(selectedVerifyPlayer.aadhaarUrl, '_blank')}>
                    <div className="flex items-center justify-between mb-3"><p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Aadhaar Evidence</p><ExternalLink size={12} className="text-violet-500" /></div>
                    {selectedVerifyPlayer.aadhaarUrl ? <img src={selectedVerifyPlayer.aadhaarUrl} className="w-full h-32 object-cover rounded-xl" alt="" /> : <div className="h-32 rounded-xl bg-slate-900 flex items-center justify-center text-[9px] font-black text-slate-800 uppercase italic">No identity proof attached</div>}
                  </div>
                </div>
              </div>
              <div className="md:col-span-7 p-12 space-y-10">
                <div>
                  <p className="text-[10px] font-black text-violet-500 uppercase tracking-[0.4em] mb-2 leading-none">Registry Record Verification</p>
                  <h2 className="text-4xl font-black text-white italic tracking-tighter leading-none">{selectedVerifyPlayer.name}</h2>
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-3">FATHER: {selectedVerifyPlayer.fatherName || "UNSPECIFIED"}</p>
                </div>
                <div className="grid grid-cols-2 gap-8">
                  <DetailNode icon={Phone} label="Mobile Node" value={selectedVerifyPlayer.mobile} />
                  <DetailNode icon={CreditCard} label="Aadhaar ID" value={selectedVerifyPlayer.aadhaarNumber} />
                  <DetailNode icon={MapPin} label="Regional Sector" value={`${selectedVerifyPlayer.taluk} > ${selectedVerifyPlayer.hobli}`} />
                  <DetailNode icon={Activity} label="Village / Ward" value={selectedVerifyPlayer.village} />
                  <DetailNode icon={Activity} label="Skill Profile" value={`${selectedVerifyPlayer.role} (${selectedVerifyPlayer.battingStyle || selectedVerifyPlayer.playingStyle})`} />
                  <DetailNode icon={Activity} label="Wicket Keeper" value={selectedVerifyPlayer.wicketKeeper ? "YES (ACTIVE)" : "NO (INACTIVE)"} color={selectedVerifyPlayer.wicketKeeper ? "text-emerald-400" : "text-red-400"} />
                </div>
                <div className="pt-10 border-t border-white/5 flex flex-wrap gap-4">
                  <button
                  onClick={() => downloadPosterAsImage(selectedVerifyPlayer)}
                  className="px-6 py-5 bg-linear-to-r from-emerald-600 to-teal-500 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-500/20 hover:scale-105 transition-all flex items-center gap-2"
                  disabled={isCapturing}>
                  
                    {isCapturing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Download size={14} />}
                    {isCapturing ? "Capturing..." : "Download Poster (PNG Image)"}
                  </button>
                  <button onClick={() => downloadPlayerCard(selectedVerifyPlayer)} className="px-6 py-5 bg-violet-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-violet-600/20 hover:scale-105 transition-all flex items-center gap-2">
                    <Download size={14} /> Download PDF ID
                  </button>
                  <button onClick={() => setSelectedVerifyPlayer(null)} className="flex-1 py-5 bg-white text-black rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:scale-[1.02] transition-all">Done</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      }
      {/* ── PDF GENERATION OVERLAY ── */}
      {pdfProgress.active &&
      <div className="fixed inset-0 z-200 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-md" />
          <div className="relative w-full max-w-md bg-slate-900 border border-white/10 rounded-3xl p-10 text-center shadow-2xl">
            <div className="relative w-32 h-32 mx-auto mb-8">
              <div className="absolute inset-0 rounded-full border-4 border-white/5" />
              <div
              className="absolute inset-0 rounded-full border-4 border-violet-500 border-t-transparent animate-spin"
              style={{ animationDuration: '2s' }} />
            
              <div className="absolute inset-0 flex items-center justify-center flex-col">
                <span className="text-2xl font-black text-white">{Math.round(pdfProgress.current / pdfProgress.total * 100)}%</span>
                <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Complete</span>
              </div>
            </div>
            <h3 className="text-xl font-black text-white uppercase tracking-tight mb-2">Preparing <span className="text-violet-500">PDF Roster</span></h3>
            <p className="text-sm text-slate-400 font-medium mb-6">Processing {pdfProgress.current} of {pdfProgress.total} players...</p>
            <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
              <div
              className="h-full bg-violet-500 transition-all duration-300 shadow-[0_0_15px_rgba(139,92,246,0.5)]"
              style={{ width: `${pdfProgress.current / pdfProgress.total * 100}%` }} />
            
            </div>
          </div>
        </div>
      }
    </div>);

}

function DetailNode({ icon: Icon, label, value, color = "text-white" }) {
  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2 opacity-40"><Icon size={12} className="text-slate-400" /><p className="text-[9px] font-black uppercase tracking-widest">{label}</p></div>
      <p className={`text-xs font-bold uppercase tracking-widest truncate ${color}`}>{value || "---"}</p>
    </div>);

}

const ExternalLink = ({ size, className }) =>
<svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>;

const MapPin = ({ size, className }) =>
<svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path><circle cx="12" cy="10" r="3"></circle></svg>;

const Activity = ({ size, className }) =>
<svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"></polyline></svg>;

const Phone = ({ size, className }) =>
<svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"></path></svg>;

const CreditCard = ({ size, className }) =>
<svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}><rect x="1" y="4" width="22" height="16" rx="2" ry="2"></rect><line x1="1" y1="10" x2="23" y2="10"></line></svg>;

"use client";

import { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import {
  Settings, Image, Layout, Shield, Bell,
  PlusCircle, Trash2, CheckCircle, RefreshCw,
  Eye, Info, Palette, Camera, Upload, AlertCircle, Zap
} from "lucide-react";
import { uploadToS3 } from "../../../lib/uploadToS3";
import { useAuction } from "../layout";
import { API_URL } from "../../../lib/apiConfig";

// ── Toggle Component ──────────────────────────────────────
const Toggle = ({ active, onToggle }) => (
  <button
    onClick={onToggle}
    className={`relative w-10 h-5 rounded-full transition-all duration-300 ${active ? 'bg-violet-600' : 'bg-slate-700'}`}
  >
    <div className={`absolute top-1 w-3 h-3 rounded-full bg-white transition-all duration-300 ${active ? 'left-6' : 'left-1'}`} />
  </button>
);

// ── Section Component ─────────────────────────────────────
const Section = ({ title, desc, icon: Icon, children }) => (
  <div className="bg-[#111827]/40 backdrop-blur-xl border border-white/5 rounded-4xl overflow-hidden">
    <div className="px-8 py-6 border-b border-white/5 flex items-center gap-4">
      <div className="p-3 rounded-2xl bg-violet-600/10 border border-violet-500/20 text-violet-400">
        <Icon className="w-5 h-5" />
      </div>
      <div>
        <h2 className="text-xl font-black text-white">{title}</h2>
        <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-0.5">{desc}</p>
      </div>
    </div>
    <div className="p-8">{children}</div>
  </div>
);

export default function AdminSettings() {
  const { selectedAuction } = useAuction();
  const { data: session } = useSession();
  const [backgrounds, setBackgrounds] = useState([]);
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [auctionConfig, setAuctionConfig] = useState({
    startingBid: 0,
    bidIncrement: 0,
    auctionMode: 'money'
  });
  const [registrationConfig, setRegistrationConfig] = useState({
    registrationEndDate: '',
    registrationEndTime: '23:59',
    closedMessage: 'Registration is currently closed. Please contact the tournament organizer for more details.'
  });
  const [savingConfig, setSavingConfig] = useState(false);

  useEffect(() => {
    if (selectedAuction?._id) {
      fetchAssets();
      setAuctionConfig({
        startingBid: selectedAuction.startingBid || 0,
        bidIncrement: selectedAuction.bidIncrement || 0,
        auctionMode: selectedAuction.auctionMode || 'money'
      });
      setRegistrationConfig({
        registrationEndDate: selectedAuction.registrationEndDate ? String(selectedAuction.registrationEndDate).split('T')[0] : '',
        registrationEndTime: selectedAuction.registrationEndTime || '23:59',
        closedMessage: selectedAuction.closedMessage || 'Registration is currently closed. Please contact the tournament organizer for more details.'
      });
    } else {
      setLoading(false);
    }
  }, [selectedAuction]);

  const fetchAssets = async () => {
    setLoading(true);
    try {
      const [bgRes, imgRes] = await Promise.all([
        fetch(`${API_URL}/api/backgrounds?tournamentId=${selectedAuction._id}`),
        fetch(`${API_URL}/api/tournament-images?tournamentId=${selectedAuction._id}`)
      ]);
      const bgData = await bgRes.json();
      const imgData = await imgRes.json();
      setBackgrounds(bgData);
      setImages(imgData.data || []);
    } catch (err) {
      console.error("Asset fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleUpload = async (e, type) => {
    const file = e.target.files[0];
    if (!file || !selectedAuction) return;

    setUploading(true);
    try {
      const url = await uploadToS3(file, type === 'bg' ? 'backgrounds' : 'gallery');

      const endpoint = type === 'bg' ? '/api/backgrounds' : '/api/tournament-images';
      const body = type === 'bg'
        ? { name: `Custom_${Date.now()}`, imageUrl: url, tournamentId: selectedAuction._id }
        : { name: `Img_${Date.now()}`, location: "Unknown", year: "2026", teams: "All", imageUrl: url, tournamentId: selectedAuction._id };

      const res = await fetch(`${API_URL}${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });

      if (res.ok) fetchAssets();
    } catch (err) {
      alert("Upload error: " + err.message);
    } finally {
      setUploading(false);
    }
  };

  const handleSaveAuctionConfig = async () => {
    if (!selectedAuction) return;
    setSavingConfig(true);
    try {
      const payload = {
        ...auctionConfig,
        ...registrationConfig,
      };
      const res = await fetch(`${API_URL}/api/tournaments/${selectedAuction._id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          ...(session?.accessToken ? { 'Authorization': `Bearer ${session.accessToken}` } : {}),
        },
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        alert("Auction configuration updated successfully!");
        // Update local storage so other components see the change
        const updated = { ...selectedAuction, ...payload };
        localStorage.setItem("selectedAuction", JSON.stringify(updated));
      } else {
        const data = await res.json();
        alert("Failed to update: " + (data.message || "Unknown error"));
      }
    } catch (err) {
      alert("Save error: " + err.message);
    } finally {
      setSavingConfig(false);
    }
  };

  if (!selectedAuction) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center bg-white/5 rounded-[3rem] border border-white/5">
        <AlertCircle className="w-12 h-12 text-yellow-400 mb-4 opacity-50" />
        <h3 className="text-xl font-black text-white">No Auction Selected</h3>
        <p className="text-slate-500 mt-2 max-w-xs mx-auto text-sm font-semibold">Please select an auction from the topbar to manage its specific assets and settings.</p>
      </div>
    );
  }

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-64 gap-3">
      <div className="w-8 h-8 border-4 border-violet-500/20 border-t-violet-500 rounded-full animate-spin" />
      <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Loading {selectedAuction.name} Configuration</p>
    </div>
  );

  return (
    <div className="space-y-10 max-w-5xl mx-auto pb-20">

      <div className="flex items-center justify-between px-2">
        <div>
          <h1 className="text-3xl font-black text-white tracking-tight">
            System <span className="text-violet-500">Assets</span>
          </h1>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-widest mt-1 opacity-60">Context: {selectedAuction.name}</p>
        </div>
        <button onClick={fetchAssets} className="p-3 bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 text-slate-400 transition-all">
          <RefreshCw className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      <Section title="Auction Engine" desc="Bidding and rule configuration" icon={Zap}>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-4">
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">Starting Bid (Global Min)</p>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold">₹</span>
                <input
                  type="number"
                  value={auctionConfig.startingBid}
                  onChange={e => setAuctionConfig({ ...auctionConfig, startingBid: Number(e.target.value) })}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 pl-10 font-black text-white outline-none focus:border-violet-500 transition-all"
                />
              </div>
              <p className="text-[9px] text-slate-600 mt-2 font-bold uppercase">Fallback if player base price is not set</p>
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">Fixed Bid Increment</p>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold">₹</span>
                <input
                  type="number"
                  value={auctionConfig.bidIncrement}
                  onChange={e => setAuctionConfig({ ...auctionConfig, bidIncrement: Number(e.target.value) })}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 pl-10 font-black text-white outline-none focus:border-violet-500 transition-all"
                />
              </div>
              <p className="text-[9px] text-slate-600 mt-2 font-bold uppercase">Applies to Money/RS mode auctions</p>
            </div>

            <button
              onClick={handleSaveAuctionConfig}
              disabled={savingConfig}
              className="w-full py-4 bg-violet-600 hover:bg-violet-700 disabled:opacity-50 text-white font-black uppercase tracking-widest rounded-2xl transition-all shadow-lg shadow-violet-600/20 flex items-center justify-center gap-2"
            >
              {savingConfig ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Settings className="w-4 h-4" />}
              Save Configuration
            </button>
          </div>

          <div className="bg-violet-600/10 border border-violet-500/20 rounded-3xl p-6 flex flex-col justify-center">
            <div className="flex items-center gap-3 mb-4">
              <Info className="w-5 h-5 text-violet-400" />
              <h4 className="text-sm font-black text-white uppercase">Engine Behavior</h4>
            </div>
            <ul className="space-y-3">
              {[
                "Starting bid acts as the global floor price",
                "Increments are added to current bid on each click",
                "Points mode uses custom band-based increments",
                "Updates take effect immediately on the live stage"
              ].map((item, i) => (
                <li key={i} className="flex items-start gap-3 text-[11px] font-bold text-slate-400 uppercase tracking-tight">
                  <span className="w-1.5 h-1.5 rounded-full bg-violet-500 mt-1 shrink-0" />
                  {item}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </Section>

      <Section title="Registration Window" desc="Application deadline visible to players" icon={Bell}>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div>
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">End Date</p>
            <input
              type="date"
              value={registrationConfig.registrationEndDate}
              onChange={e => setRegistrationConfig(prev => ({ ...prev, registrationEndDate: e.target.value }))}
              className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 font-black text-white outline-none focus:border-violet-500 transition-all"
            />
          </div>
          <div>
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">End Time</p>
            <input
              type="time"
              value={registrationConfig.registrationEndTime}
              onChange={e => setRegistrationConfig(prev => ({ ...prev, registrationEndTime: e.target.value }))}
              className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 font-black text-white outline-none focus:border-violet-500 transition-all"
            />
          </div>
          <div>
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">Closed Message</p>
            <textarea
              rows={3}
              value={registrationConfig.closedMessage}
              onChange={e => setRegistrationConfig(prev => ({ ...prev, closedMessage: e.target.value }))}
              className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 font-medium text-white outline-none focus:border-violet-500 transition-all resize-none"
            />
          </div>
        </div>
        <p className="mt-4 text-[10px] font-bold uppercase tracking-widest text-slate-500">
          Players will see the countdown and this message on the application page.
        </p>
      </Section>

      <Section title="Auction Backgrounds" desc="Visual branding for the live stage" icon={Palette}>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {backgrounds.map(bg => (
            <div key={bg._id} className="group relative aspect-video rounded-3xl overflow-hidden border border-white/10 group shadow-lg">
              <img src={bg.imageUrl} alt={bg.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
              <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-6">
                <div className="flex items-center justify-between gap-4">
                  <div className="min-w-0">
                    <p className="text-sm font-black text-white truncate">{bg.name}</p>
                  </div>
                  <button className="p-2 bg-red-500/20 text-red-400 rounded-xl hover:bg-red-500 hover:text-white transition-all shrink-0">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
              {bg.isActive && (
                <div className="absolute top-4 left-4 flex items-center gap-1.5 px-3 py-1 bg-violet-600 rounded-full text-[10px] font-black uppercase tracking-widest shadow-xl">
                  <CheckCircle className="w-3 h-3" /> Active
                </div>
              )}
            </div>
          ))}
          <label className="relative aspect-video rounded-3xl border-2 border-dashed border-violet-500/20 bg-violet-500/5 hover:bg-violet-500/10 flex flex-col items-center justify-center cursor-pointer transition-all">
            {uploading ? <RefreshCw className="w-8 h-8 text-violet-500 animate-spin" /> : <Upload className="w-8 h-8 text-violet-500/40" />}
            <span className="text-xs font-black text-violet-400/60 uppercase tracking-widest mt-4">Add Background</span>
            <input type="file" className="hidden" accept="image/*" onChange={e => handleUpload(e, 'bg')} />
          </label>
        </div>
      </Section>

      <Section title="Tournament Gallery" desc="Promotional and historical images" icon={Camera}>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {images.map(img => (
            <div key={img._id} className="relative aspect-square rounded-2xl overflow-hidden border border-white/10 group">
              <img src={img.imageUrl} alt={img.name} className="w-full h-full object-cover" />
              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                <button className="p-2 bg-white/10 rounded-lg hover:bg-white/20 text-white"><Eye className="w-4 h-4" /></button>
                <button className="p-2 bg-red-500/20 text-red-400 rounded-lg hover:bg-red-500 hover:text-white"><Trash2 className="w-4 h-4" /></button>
              </div>
            </div>
          ))}
          <label className="relative aspect-square rounded-2xl border-2 border-dashed border-white/10 hover:border-violet-500/30 bg-white/5 flex items-center justify-center cursor-pointer transition-all">
            <PlusCircle className="w-6 h-6 text-slate-600" />
            <input type="file" className="hidden" accept="image/*" onChange={e => handleUpload(e, 'gallery')} />
          </label>
        </div>
      </Section>

      <Section title="System Security" desc="Access control and monitoring" icon={Shield}>
        <div className="space-y-6">
          <div className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
            <div>
              <p className="text-sm font-bold text-white uppercase tracking-wide">Admin Lockdown</p>
              <p className="text-xs text-slate-500">Prevent all other logins during live auction</p>
            </div>
            <Toggle active={true} />
          </div>
          <div className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
            <div>
              <p className="text-sm font-bold text-white uppercase tracking-wide">Public View</p>
              <p className="text-xs text-slate-500">Allow users to see auction results live</p>
            </div>
            <Toggle active={false} />
          </div>
        </div>
      </Section>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Users, Search, Save, X, AlertTriangle, ShieldCheck, Trophy, AlertCircle, Edit3, ArrowUpRight, UploadCloud, FileSpreadsheet, Trash2, Undo2 } from "lucide-react";
import * as XLSX from 'xlsx';
import { useAuction } from "../layout";
import { useSession } from "next-auth/react";
// import { io } from "socket.io-client"; // Removed redundant import
import ImageEditModal from "../../../components/ImageEditModal";
import { API_URL, getMediaUrl, getProxiedImageUrl } from "../../../lib/apiConfig";

// Socket instance shared from layout

export default function TeamsRegistry() {
  const { data: session } = useSession();
  const { selectedAuction, socket } = useAuction();
  const [teams, setTeams] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  // Modal State
  const [isManageModalOpen, setIsManageModalOpen] = useState(false);
  const [isConfirmModalOpen, setIsConfirmModalOpen] = useState(false);
  const [editingTeam, setEditingTeam] = useState(null);
  const [formData, setFormData] = useState({});
  const [confirmText, setConfirmText] = useState("");
  const [editImageTarget, setEditImageTarget] = useState(null); // { id, url, name }
  const [uploading, setUploading] = useState(false);
  const [lastImportedIds, setLastImportedIds] = useState([]);
  const [isDeleteRangeModalOpen, setIsDeleteRangeModalOpen] = useState(false);
  const [deleteRange, setDeleteRange] = useState({ from: "", to: "" });

  useEffect(() => {
    if (selectedAuction?._id) {
      fetchTeams();
    } else {
      setLoading(false);
    }
  }, [selectedAuction]);

  const fetchTeams = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_URL}/api/teams?tournamentId=${selectedAuction._id}`);
      const data = await res.json();
      setTeams(data);
    } catch (err) {
      console.error("Fetch teams error:", err);
    } finally {
      setLoading(false);
    }
  };

  const openManageModal = (team) => {
    setEditingTeam(team);
    setFormData({
      name: team.name,
      shortName: team.shortName,
      remainingBudget: team.remainingBudget || 0,
      color: team.color || "#7c3aed"
    });
    setIsManageModalOpen(true);
  };

  const handleSaveClick = () => {
    setIsManageModalOpen(false);
    setIsConfirmModalOpen(true);
  };

  const handleFinalConfirm = async () => {
    if (confirmText !== "CONFIRM") return;

    try {
      const res = await fetch(`${API_URL}/api/teams/${editingTeam._id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${session?.accessToken}`
        },
        body: JSON.stringify(formData)
      });

      if (res.ok) {
        // Broadcast via socket
        socket.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
        setIsConfirmModalOpen(false);
        setConfirmText("");
        fetchTeams();
      }
    } catch (err) {
      alert("Error updating team");
    }
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploading(true);
    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const bstr = evt.target.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) {
          alert("Sheet is empty");
          setUploading(false);
          return;
        }

        // Map common column names
        const teamsToUpload = data.map((row) => {
          // Look for keys that contain 'name', 'team', 'logo', 'url', 'short', 'code'
          const keys = Object.keys(row);
          const nameKey = keys.find((k) => k.toLowerCase().includes('name') || k.toLowerCase().includes('team'));
          const logoKey = keys.find((k) => k.toLowerCase().includes('logo') || k.toLowerCase().includes('url') || k.toLowerCase().includes('image') || k.toLowerCase().includes('photo'));
          const shortNameKey = keys.find((k) => k.toLowerCase().includes('short') || k.toLowerCase().includes('code'));

          const name = row[nameKey];
          if (!name) return null;

          return {
            name: name.toString().trim(),
            logoUrl: row[logoKey] ? row[logoKey].toString().trim() : "",
            shortName: row[shortNameKey] ? row[shortNameKey].toString().trim().toUpperCase() : name.toString().trim().substring(0, 3).toUpperCase(),
            tournamentId: selectedAuction._id,
            remainingBudget: selectedAuction.startingBudget || 1000000
          };
        }).filter((t) => t !== null);

        if (teamsToUpload.length > 0) {
          const res = await fetch(`${API_URL}/api/teams/bulk`, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${session?.accessToken}`
            },
            body: JSON.stringify({ teams: teamsToUpload })
          });

          if (res.ok) {
            const result = await res.json();
            setLastImportedIds(result.map((t) => t._id));
            alert(`Successfully imported ${teamsToUpload.length} teams!`);
            fetchTeams();
          } else {
            const errData = await res.json();
            alert("Failed to import teams: " + (errData.message || "Unknown error"));
          }
        } else {
          alert("No valid team data found in sheet. Ensure columns have headers like 'Team Name' and 'Logo URL'.");
        }
      } catch (err) {
        console.error("CSV Parse Error:", err);
        alert("Error parsing file. Ensure it is a valid CSV or Excel file.");
      } finally {
        setUploading(false);
        // Reset file input
        if (e.target) e.target.value = null;
      }
    };
    reader.onerror = () => {
      alert("Error reading file");
      setUploading(false);
    };
    reader.readAsBinaryString(file);
  };

  const handleUndoLastImport = async () => {
    if (lastImportedIds.length === 0) return;
    if (!confirm(`Undo will delete the ${lastImportedIds.length} teams you just imported. Continue?`)) return;

    try {
      const res = await fetch(`${API_URL}/api/teams/bulk-delete`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${session?.accessToken}`
        },
        body: JSON.stringify({ teamIds: lastImportedIds })
      });

      if (res.ok) {
        alert("Import undone successfully");
        setLastImportedIds([]);
        fetchTeams();
      }
    } catch (err) {
      alert("Error undoing import");
    }
  };

  const handleDeleteTeam = async (id, name) => {
    if (!confirm(`Are you sure you want to delete ${name}? This will also unassign all players from this team.`)) return;

    try {
      const res = await fetch(`${API_URL}/api/teams/${id}`, {
        method: "DELETE",
        headers: {
          "Authorization": `Bearer ${session?.accessToken}`
        }
      });

      if (res.ok) {
        // Broadcast via socket
        socket.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
        fetchTeams();
      }
    } catch (err) {
      alert("Error deleting team");
    }
  };

  const handleDeleteRange = async () => {
    if (!deleteRange.from || !deleteRange.to) {
      alert("Please enter both 'From' and 'To' indices");
      return;
    }

    const start = parseInt(deleteRange.from) - 1; // 0-indexed
    const end = parseInt(deleteRange.to) - 1;

    const teamsToDelete = filteredTeams.slice(start, end + 1);
    if (teamsToDelete.length === 0) {
      alert("No teams found in this range");
      return;
    }

    if (!confirm(`Are you sure you want to delete ${teamsToDelete.length} teams (from Row ${deleteRange.from} to Row ${deleteRange.to})? This cannot be undone.`)) return;

    try {
      const res = await fetch(`${API_URL}/api/teams/bulk-delete`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${session?.accessToken}`
        },
        body: JSON.stringify({ teamIds: teamsToDelete.map((t) => t._id) })
      });

      if (res.ok) {
        alert("Teams deleted successfully");
        setIsDeleteRangeModalOpen(false);
        setDeleteRange({ from: "", to: "" });
        fetchTeams();
        socket.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
      }
    } catch (err) {
      alert("Error deleting range");
    }
  };

  const filteredTeams = teams.filter((t) =>
  t.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
  t.shortName?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (!selectedAuction) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center bg-white/5 rounded-[3rem] border border-white/5">
        <AlertCircle className="w-12 h-12 text-yellow-400 mb-4 opacity-50" />
        <h3 className="text-xl font-black text-white">No Auction Selected</h3>
        <p className="text-slate-500 mt-2 max-w-xs mx-auto text-sm font-semibold italic">Select an auction from the top monitor to manage teams.</p>
      </div>);

  }

  return (
    <div className="space-y-8 max-w-7xl mx-auto pb-20">
      
      {/* ── Table Header ── */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-white tracking-tight">Team <span className="text-violet-500 text-2xl">Management</span></h1>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.3em] mt-1 opacity-60">Database: {selectedAuction.name}</p>
        </div>
        
        <div className="flex items-center gap-3">
          {/* Undo Button */}
          {lastImportedIds.length > 0 &&
          <button
            onClick={handleUndoLastImport}
            className="flex items-center gap-2 px-4 py-3 bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/30 rounded-2xl transition-all group animate-in slide-in-from-right-4">
            
              <Undo2 className="w-4 h-4 text-amber-500 group-hover:-rotate-45 transition-transform" />
              <span className="text-[10px] font-black uppercase tracking-widest text-amber-400">Undo Last Import</span>
            </button>
          }

          {/* Delete Range Button */}
          <button
            onClick={() => setIsDeleteRangeModalOpen(true)}
            className="p-3 bg-red-500/10 text-red-500 border border-red-500/20 rounded-2xl hover:bg-red-500/20 transition-all active:scale-95 shadow-xl"
            title="Delete Range">
            
            <Trash2 className="w-4 h-4" />
          </button>

          {/* CSV Upload Button */}
          <label className={`flex items-center gap-2 px-4 py-3 bg-emerald-600/10 hover:bg-emerald-600/20 border border-emerald-500/30 rounded-2xl cursor-pointer transition-all group ${uploading ? 'opacity-50 pointer-events-none' : ''}`}>
            <FileSpreadsheet className="w-4 h-4 text-emerald-500 group-hover:scale-110 transition-transform" />
            <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">
              {uploading ? "Importing..." : "Upload Teams Sheet"}
            </span>
            <input
              type="file"
              accept=".csv, .xlsx, .xls"
              className="hidden"
              onChange={handleFileUpload}
              disabled={uploading} />
            
          </label>

          <div className="relative group min-w-[300px]">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-violet-400" />
            <input
              type="text"
              placeholder="Search teams..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-[#111827]/60 backdrop-blur-xl border border-white/10 rounded-2xl pl-11 pr-4 py-3 font-bold text-white focus:border-violet-500 outline-none transition-all placeholder:text-slate-700" />
            
          </div>
        </div>
      </div>

      {/* ── Table Container ── */}
      <div className="bg-[#111827]/40 backdrop-blur-2xl rounded-[2.5rem] border border-white/5 overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse border-separate border-spacing-0">
            <thead>
              <tr className="bg-white/5 border-b border-white/5">
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Team Name</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Short Code</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Team Roster</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Purse Balance</th>
                <th className="px-6 py-5 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Status</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {filteredTeams.map((t) =>
              <tr key={t._id} className="group hover:bg-white/[0.03] transition-colors">
                  <td className="px-8 py-4">
                    <div className="flex items-center gap-4">
                      <div
                      onClick={() => setEditImageTarget({ id: t._id, url: t.logoUrl, name: t.name })}
                      className="relative w-10 h-10 rounded-2xl overflow-hidden border border-white/10 shrink-0 shadow-lg bg-slate-800 flex items-center justify-center font-black text-white cursor-pointer hover:border-violet-500/50 transition-all group/img"
                      style={{ background: t.color + "33", color: t.color }}>
                        {t.logoUrl ?
                      <img
                        src={getProxiedImageUrl(t.logoUrl)}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          // If proxy fails, try direct media URL as fallback
                          if (e.target.src !== getMediaUrl(t.logoUrl)) {
                            e.target.src = getMediaUrl(t.logoUrl);
                          } else {
                            e.target.style.display = 'none';
                            if (e.target.parentElement) {
                              e.target.parentElement.innerHTML = t.name?.[0] || '?';
                            }
                          }
                        }} alt="" /> :

                      t.name?.[0]}
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity">
                           <Edit3 className="w-4 h-4 text-white" />
                        </div>
                      </div>
                      <div>
                        <p className="text-sm font-black text-white leading-tight">{t.name}</p>
                        <p className="text-[10px] text-slate-500 font-bold tracking-widest uppercase">ID: {t._id.slice(-6).toUpperCase()}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-[10px] font-black uppercase tracking-widest text-[#7c3aed] bg-[#7c3aed]/10 px-2 py-1 rounded-lg border border-[#7c3aed]/20">{t.shortName}</span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                       <Users className="w-3 h-3 text-slate-600" />
                       <span className="text-sm font-black text-white">{t.players?.length || 0}</span>
                       <span className="text-[10px] text-slate-700 font-bold">/ {selectedAuction.squadSize || 15}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <p className="text-sm font-black text-emerald-400">₹{(t.remainingBudget / 1000).toFixed(1)}k</p>
                  </td>
                  <td className="px-6 py-4">
                     <span className="w-2 h-2 rounded-full bg-emerald-500 inline-block mr-2" />
                     <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest opacity-60 italic leading-none">Healthy</span>
                  </td>
                  <td className="px-8 py-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button
                      onClick={() => openManageModal(t)}
                      className="px-4 py-2 bg-[#7c3aed] hover:bg-[#8b5cf6] text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-lg hover:shadow-[#7c3aed]/20">
                      
                        Configure
                      </button>
                      <button
                      onClick={() => handleDeleteTeam(t._id, t.name)}
                      className="p-2 bg-red-500/10 hover:bg-red-500/20 text-red-500 rounded-xl transition-all border border-red-500/20"
                      title="Delete Team">
                      
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>

          {/* ── DELETE RANGE MODAL ── */}
          {isDeleteRangeModalOpen &&
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => setIsDeleteRangeModalOpen(false)} />
              <div className="relative w-full max-w-md bg-slate-900 border border-white/10 rounded-3xl p-8 shadow-2xl">
                <h3 className="text-xl font-black text-white mb-6 uppercase tracking-wider flex items-center gap-3">
                  <AlertTriangle className="w-6 h-6 text-red-500" />
                  Delete <span className="text-red-500">Team Range</span>
                </h3>

                <div className="space-y-4 mb-8">
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2 block">From Row Number</label>
                    <input
                    type="number"
                    placeholder="e.g. 1"
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white font-bold outline-none focus:border-red-500 transition-all"
                    value={deleteRange.from}
                    onChange={(e) => setDeleteRange({ ...deleteRange, from: e.target.value })} />
                  
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2 block">To Row Number</label>
                    <input
                    type="number"
                    placeholder="e.g. 5"
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white font-bold outline-none focus:border-red-500 transition-all"
                    value={deleteRange.to}
                    onChange={(e) => setDeleteRange({ ...deleteRange, to: e.target.value })} />
                  
                  </div>
                  <p className="text-[10px] text-slate-500 italic leading-relaxed">
                    Note: This will delete teams based on their current order in the table (from row X to row Y).
                  </p>
                </div>

                <div className="flex gap-3">
                  <button
                  onClick={() => setIsDeleteRangeModalOpen(false)}
                  className="flex-1 py-4 bg-white/5 hover:bg-white/10 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-400 transition-all">
                  
                    Cancel
                  </button>
                  <button
                  onClick={handleDeleteRange}
                  className="flex-1 py-4 bg-red-600 hover:bg-red-700 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white shadow-xl shadow-red-500/20 transition-all">
                  
                    Delete Range
                  </button>
                </div>
              </div>
            </div>
          }

          {filteredTeams.length === 0 &&
          <div className="py-20 text-center opacity-30 italic font-black uppercase tracking-[0.5em]">Zero Data Matched</div>
          }
        </div>
      </div>

      {/* ── MANAGE MODAL ── */}
      {isManageModalOpen &&
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in">
          <div className="bg-[#0f172a] border border-white/10 rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl">
            <div className="px-8 py-6 border-b border-white/5 flex items-center justify-between bg-white/[0.02]">
               <h2 className="text-xl font-black text-white">Team <span className="text-violet-500">Details</span></h2>
               <button onClick={() => setIsManageModalOpen(false)} className="p-2 hover:bg-white/5 rounded-full transition-colors"><X className="w-5 h-5 text-slate-500" /></button>
            </div>
            
            <div className="p-8 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Team Name</label>
                  <input
                  className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })} />
                
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Drafted Team</label>
                  <input
                  className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white outline-none focus:border-violet-500 uppercase"
                  value={formData.shortName}
                  onChange={(e) => setFormData({ ...formData, shortName: e.target.value.toUpperCase() })} />
                
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Remaining Purse (₹)</label>
                <div className="relative">
                   <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 font-black text-sm">₹</div>
                   <input
                  type="number"
                  className="w-full bg-slate-900 border border-white/10 rounded-xl pl-8 pr-4 py-3 text-sm font-bold text-emerald-400 outline-none focus:border-violet-500"
                  value={formData.remainingBudget}
                  onChange={(e) => setFormData({ ...formData, remainingBudget: Number(e.target.value) })} />
                
                </div>
              </div>
            </div>

            <div className="px-8 py-6 bg-white/[0.02] border-t border-white/5 flex gap-3">
               <button onClick={() => setIsManageModalOpen(false)} className="flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-white/5 transition-all text-center">Abort</button>
               <button
              onClick={handleSaveClick}
              className="flex-1 py-3 rounded-2xl bg-gradient-to-r from-violet-600 to-cyan-500 text-[10px] font-black uppercase tracking-widest text-white shadow-xl shadow-violet-500/20 hover:scale-105 transition-all">
              
                 Stage Updates
               </button>
            </div>
          </div>
        </div>
      }

      {/* ── CONFIRMATION DIALOG ── */}
      {isConfirmModalOpen &&
      <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/95 backdrop-blur-md animate-in zoom-in-95">
          <div className="bg-[#0f172a] border border-red-500/20 rounded-[2.5rem] w-full max-w-sm overflow-hidden shadow-[0_0_50px_rgba(239,68,68,0.2)]">
            <div className="p-8 text-center space-y-4">
               <div className="w-16 h-16 bg-red-500/10 rounded-3xl flex items-center justify-center mx-auto border border-red-500/20">
                  <AlertTriangle className="w-8 h-8 text-red-500 animate-pulse" />
               </div>
               <div>
                  <h3 className="text-xl font-black text-white">Manual Override?</h3>
                  <p className="text-xs text-slate-500 mt-2 leading-relaxed">
                    You are manually adjusting the financial ledger for <span className="text-white font-black">{editingTeam?.name}</span>. This will affect bidding capability.
                  </p>
               </div>
               
               <div className="pt-4 space-y-3">
                  <div className="space-y-1.5 text-left">
                     <label className="text-[9px] font-black uppercase tracking-widest text-slate-600">Type &quot;CONFIRM&quot; to authorize</label>
                     <input
                  className="w-full bg-slate-900 border border-red-500/20 rounded-xl px-4 py-3 text-center text-sm font-black text-red-400 outline-none focus:border-red-500 transition-all placeholder:text-slate-800"
                  placeholder="CONFIRM"
                  value={confirmText}
                  onChange={(e) => setConfirmText(e.target.value.toUpperCase())} />
                
                  </div>
                  
                  <div className="flex gap-2">
                     <button onClick={() => setIsConfirmModalOpen(false)} className="flex-1 py-3 text-[10px] font-black uppercase text-slate-600 hover:text-white transition-all">Cancel</button>
                     <button
                  disabled={confirmText !== 'CONFIRM'}
                  onClick={handleFinalConfirm}
                  className="flex-1 py-3 bg-red-600 disabled:opacity-20 disabled:grayscale text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-red-500/20 hover:bg-red-500 transition-all">
                  
                       <ShieldCheck className="w-3 h-3 inline mr-1" /> Commit
                     </button>
                  </div>
               </div>
            </div>
          </div>
        </div>
      }

      {/* ── IMAGE EDIT MODAL ── */}
      {editImageTarget &&
      <ImageEditModal
        title={`Edit Logo: ${editImageTarget.name}`}
        initialImage={editImageTarget.url}
        onClose={() => setEditImageTarget(null)}
        onSave={async (file) => {
          try {
            const fileType = file.type;
            const { uploadUrl, fileUrl } = await fetch(`${API_URL}/api/upload/get-upload-url?fileType=${fileType}&folder=teams`).then((r) => r.json());
            await fetch(uploadUrl, { method: "PUT", body: file, headers: { "Content-Type": fileType } });

            const res = await fetch(`${API_URL}/api/teams/${editImageTarget.id}`, {
              method: "PATCH",
              headers: {
                "Content-Type": "application/json",
                "Authorization": `Bearer ${session?.accessToken}`
              },
              body: JSON.stringify({ logoUrl: fileUrl })
            });

            if (res.ok) {
              socket.emit("auctionUpdate", { type: "system_refresh", auctionId: selectedAuction._id });
              fetchTeams();
            }
          } catch (err) {
            console.error("Logo update failed", err);
            alert("Logo update failed");
          }
        }} />

      }
    </div>);

}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import {
  Trophy, Play, Eye, Edit, Trash2, Users,
  Calendar, RotateCcw, PlusCircle, Clock,
  CheckCircle, Zap, ExternalLink, RefreshCw, Settings, X
} from "lucide-react";

import * as XLSX from "xlsx";
import { API_URL, getMediaUrl } from "@/lib/apiConfig";
import { getCanonicalApplyRoute } from "@/lib/applicationRoutes";

export default function TournamentsPage() {
  const [tournaments, setTournaments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [resetting, setResetting] = useState(null);
  const [appending, setAppending] = useState(null);
  const [activating, setActivating] = useState(null);
  const [deleting, setDeleting] = useState(null);
  const [editingTournament, setEditingTournament] = useState(null);
  const [isUpdating, setIsUpdating] = useState(false);

  useEffect(() => {
    fetchTournaments();
    const interval = setInterval(() => {
      // Poll if any tournament is processing images
      const isProcessing = tournaments.some(t => t.imageProcessing?.status === 'processing');
      if (isProcessing) fetchTournaments();
    }, 5000);
    return () => clearInterval(interval);
  }, [tournaments]);

  const fetchTournaments = async () => {
    try {
      const res = await fetch(`${API_URL}/api/tournaments`);
      const data = await res.json();
      if (Array.isArray(data)) {
        setTournaments(data);
      } else {
        setTournaments([]);
      }
    } catch (err) {
      console.error("Failed to fetch tournaments:", err);
    } finally {
      setLoading(false);
    }
  };

  const resetAuction = async (tournamentId) => {
    if (!confirm("Are you sure you want to reset the auction?\n\nThis will:\n- Keep icon players in their teams\n- Reset all sold players back to auction pool\n- Reset all team budgets\n\nThis action cannot be undone!")) {
      return;
    }

    setResetting(tournamentId);
    try {
      const res = await fetch(`${API_URL}/api/tournaments/${tournamentId}/reset`, {
        method: "POST",
        headers: { "Content-Type": "application/json" }
      });

      if (res.ok) {
        const data = await res.json();
        alert(`Auction reset successfully!\n\n- ${data.iconPlayersRetained} icon players retained\n- ${data.auctionPlayersReset} auction players reset\n- ${data.teamsReset} teams reset`);
        fetchTournaments();
      } else {
        alert("Failed to reset auction");
      }
    } catch (err) {
      console.error("Error resetting auction:", err);
      alert("Error resetting auction");
    } finally {
      setResetting(null);
    }
  };

  const goLive = async (tournamentId) => {
    if (!confirm("Make this tournament LIVE? This will archive any other currently live auctions.")) {
      return;
    }
    setActivating(tournamentId);
    try {
      const res = await fetch(`${API_URL}/api/tournaments/${tournamentId}/go-live`, {
        method: "POST",
        headers: { "Content-Type": "application/json" }
      });
      if (res.ok) {
        fetchTournaments();
      } else {
        alert("Failed to set live");
      }
    } catch (err) {
      console.error("Go live error:", err);
    } finally {
      setActivating(null);
    }
  };

  const archiveAuction = async (tournamentId) => {
    if (!confirm("Are you sure you want to mark this auction as COMPLETED? It will no longer show up as a live option.")) {
      return;
    }
    try {
      const res = await fetch(`${API_URL}/api/tournaments/${tournamentId}/archive`, {
        method: "POST",
        headers: { "Content-Type": "application/json" }
      });
      if (res.ok) {
        fetchTournaments();
      }
    } catch (err) {
      console.error("Archive error:", err);
    }
  };

  const deleteAuction = async (tournamentId) => {
    const password = prompt("🚨 PERMANENT DELETION 🚨\n\nThis will completely erase the auction, all players, teams, and permanently delete all uploaded images/logos from the cloud server.\n\nEnter Admin Password to confirm deletion:");
    if (!password) return;

    setDeleting(tournamentId);
    try {
      const res = await fetch(`${API_URL}/api/tournaments/${tournamentId}`, {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password })
      });

      if (res.ok) {
        alert("Auction completely deleted from database and cloud.");
        fetchTournaments();
      } else {
        const data = await res.json();
        alert(`Failed to delete: ${data.message || 'Unknown error'}`);
      }
    } catch (err) {
      console.error("Delete error:", err);
      alert("Server error while trying to delete auction.");
    } finally {
      setDeleting(null);
    }
  };

  const handleAppendPlayers = async (tournamentId, e) => {
    const file = e.target.files[0];
    if (!file) return;

    setAppending(tournamentId);
    try {
      const reader = new FileReader();
      reader.onload = async (ev) => {
        const wb = XLSX.read(ev.target.result, { type: "binary", cellDates: true });
        const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);

        // Map keys helper (similar to create-tournament)
        const findValue = (row, keys) => {
          const rk = Object.keys(row);
          for (const k of keys) {
            const f = rk.find(key => key.toLowerCase().trim() === k.toLowerCase().trim());
            if (f) return row[f];
          }
          return null;
        };

        const players = rows.map(row => ({
          name: findValue(row, ["player name", "playerName", "name", "player", "ಆಟಗಾರನ ಹೆಸರು"]) || "PLAYER NAME",
          role: findValue(row, ["playing role", "role", "skill", "player role", "category", "type", "position", "ಪಾತ್ರ"]) || "All-Rounder",
          mobile: findValue(row, ["mobile", "phone", "contact", "ಮೊಬೈಲ್", "ದೂರವಾಣಿ"]) || "-",
          battingStyle: findValue(row, ["batting", "battingStyle", "style", "ಬ್ಯಾಟಿಂಗ್"]) || "Right Hand",
          bowlingStyle: findValue(row, ["bowling", "bowlingStyle", "ಬೌಲಿಂಗ್"]) || "-",
          village: findValue(row, ["village", "town", "city", "ಗ್ರಾಮ", "ಸ್ಥಳ"]) || "-",
          basePrice: Number(findValue(row, ["basePrice", "price", "base price", "amount", "ಮೂಲ ಬೆಲೆ"])) || 100,
          imageUrl: findValue(row, ["imageUrl", "photo", "image", "link", "url", "ಭಾವಚಿತ್ರ"]) || "",
          isIcon: findValue(row, ["icon", "isIcon", "star"]) === "yes" || findValue(row, ["isIcon"]) === true
        }));

        const res = await fetch(`${API_URL}/api/tournaments/${tournamentId}/append-players`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ players })
        });

        if (res.ok) {
          const data = await res.json();
          alert(`Successfully added ${data.added} new players! (Skipped ${data.skipped} duplicates)`);
          fetchTournaments();
        } else {
          alert("Failed to append players");
        }
        setAppending(null);
      };
      reader.readAsBinaryString(file);
    } catch (err) {
      console.error("Append error:", err);
      alert("File error");
      setAppending(null);
    }
  };

  const handleUpdateSettings = async (e) => {
    e.preventDefault();
    if (!editingTournament) return;

    setIsUpdating(true);
    try {
      const res = await fetch(`${API_URL}/api/tournaments/${editingTournament._id || editingTournament.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          auctionMode: editingTournament.auctionMode,
          currencyUnit: editingTournament.currencyUnit
        })
      });

      if (res.ok) {
        alert("Tournament settings updated successfully!");
        setEditingTournament(null);
        fetchTournaments();
      } else {
        alert("Failed to update tournament settings");
      }
    } catch (err) {
      console.error("Update error:", err);
      alert("Error updating settings");
    } finally {
      setIsUpdating(false);
    }
  };

  const getStatusMeta = (status) => {
    switch (status) {
      case "active":
      case "live":
        return {
          color: "text-red-400",
          bg: "bg-red-500/10",
          border: "border-red-500/20",
          icon: <Zap className="w-3 h-3 animate-pulse" />,
          label: "Live"
        };
      case "upcoming":
        return {
          color: "text-blue-400",
          bg: "bg-blue-500/10",
          border: "border-blue-500/20",
          icon: <Clock className="w-3 h-3" />,
          label: "Upcoming"
        };
      case "completed":
        return {
          color: "text-emerald-400",
          bg: "bg-emerald-500/10",
          border: "border-emerald-500/20",
          icon: <CheckCircle className="w-3 h-3" />,
          label: "Completed"
        };
      default:
        return {
          color: "text-slate-400",
          bg: "bg-slate-500/10",
          border: "border-slate-500/20",
          icon: <Calendar className="w-3 h-3" />,
          label: status
        };
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-4">
        <div className="w-10 h-10 border-4 border-violet-500/20 border-t-violet-500 rounded-full animate-spin" />
        <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Loading Tournaments</p>
      </div>
    );
  }

  const liveTournaments = tournaments.filter(t => t.status === "active" || t.status === "live");
  const concludedTournaments = tournaments.filter(t => t.status === "completed");
  const otherTournaments = tournaments.filter(t => t.status !== "active" && t.status !== "live" && t.status !== "completed");

  const renderTournamentCard = (t) => {
    const meta = getStatusMeta(t.status);
    const tournamentId = t._id || t.id;
    return (
      <div key={tournamentId} className="group relative overflow-hidden rounded-[2.5rem] border border-white/10 bg-[#111827]/60 backdrop-blur-xl hover:border-violet-500/30 transition-all duration-500 hover:shadow-[0_20px_50px_rgba(124,58,237,0.1)]">
        {/* Banner Area */}
        <div className="relative h-32 w-full overflow-hidden">
          <img
            src={getMediaUrl(t.assets?.splashUrl, "https://images.unsplash.com/photo-1540747913346-19e32dc3e97e?q=80&w=600&auto=format&fit=crop")}
            className="w-full h-full object-cover opacity-40 group-hover:scale-110 group-hover:opacity-60 transition-all duration-700"
            alt="Banner"
          />
          <div className="absolute inset-0 bg-linear-to-t from-[#111827] to-transparent"></div>

          {/* Status Badge */}
          <div className="absolute top-4 right-4 z-10">
            <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full border text-[9px] font-black uppercase tracking-widest backdrop-blur-md ${meta.bg} ${meta.color} ${meta.border}`}>
              {meta.icon}
              {meta.label}
            </div>
          </div>
        </div>

        <div className="px-6 -mt-10 relative z-10">
          <div className="flex items-end gap-4 mb-6">
            {/* Tournament Logo */}
            <div className="w-20 h-20 shrink-0 rounded-2xl bg-slate-950 border-2 border-white/10 flex items-center justify-center overflow-hidden shadow-2xl group-hover:border-violet-500/50 transition-colors">
              {t.organizerLogo ? (
                <img src={t.organizerLogo} alt="Logo" className="w-full h-full object-contain p-2" />
              ) : (
                <Trophy className="w-8 h-8 text-slate-700" />
              )}
            </div>

            <div className="flex-1 pb-1">
              <h3 className="text-lg font-black text-white group-hover:text-violet-400 transition-colors truncate tracking-normal italic">
                {t.name}
              </h3>
              <div className="flex items-center gap-2 mt-0.5 text-slate-500 text-[10px] font-black uppercase tracking-widest">
                <Calendar className="w-3 h-3 text-violet-500" />
                {new Date(t.createdAt).toLocaleDateString("en-IN", { day: 'numeric', month: 'short', year: 'numeric' })}
              </div>
            </div>
          </div>
        </div>

        <div className="px-6 pb-6">

          {/* Stats Row */}
          <div className="grid grid-cols-3 gap-3 mb-6">
            <div className="bg-white/5 rounded-xl p-2.5 text-center border border-white/5">
              <Users className="w-3.5 h-3.5 text-blue-400 mx-auto mb-1.5" />
              <p className="text-base font-black text-white">{t.numTeams || t.teams || 0}</p>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-normal">Teams</p>
            </div>
            <div className="bg-white/5 rounded-xl p-2.5 text-center border border-white/5">
              <Trophy className="w-3.5 h-3.5 text-violet-400 mx-auto mb-1.5" />
              <p className="text-base font-black text-white">{t.playerCount || t.players?.length || 0}</p>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-normal">Players</p>
            </div>
            <div className="bg-white/5 rounded-xl p-2.5 text-center border border-white/5">
              <RotateCcw className="w-3.5 h-3.5 text-amber-400 mx-auto mb-1.5" />
              <p className="text-base font-black text-white">
                {t.currencyUnit === "₹" ? `₹${((t.baseBudget || 10000) / 1000).toFixed(0)}k` : `${(t.baseBudget || 10000).toLocaleString()} ${t.currencyUnit || 'CR'}`}
              </p>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-normal">Budget</p>
            </div>
          </div>

          {/* IMAGE PROCESSING PROGRESS */}
          {t.imageProcessing?.status === "processing" && (
            <div className="mb-6 space-y-2">
              <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-tighter text-slate-400">
                <span>Image Conversion</span>
                <span>{t.imageProcessing.completed} / {t.imageProcessing.total}</span>
              </div>
              <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                <div
                  className="h-full bg-linear-to-r from-violet-500 to-cyan-400 transition-all duration-500"
                  style={{ width: `${(t.imageProcessing.completed / (t.imageProcessing.total || 1)) * 100}%` }}
                />
              </div>
            </div>
          )}

          {/* Live Banner / Activation */}
          {t.status === "active" ? (
            <div className="mb-4 p-3 rounded-xl bg-linear-to-r from-red-500/10 to-transparent border-l-4 border-red-500">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-[10px] font-black text-red-400 uppercase tracking-widest">Active Auction</p>
                  <button
                    onClick={() => archiveAuction(tournamentId)}
                    className="text-[8px] text-slate-500 font-bold hover:text-red-400 transition-colors uppercase tracking-tighter underline underline-offset-2"
                  >
                    Mark as Concluded
                  </button>
                </div>
                <Zap className="w-3.5 h-3.5 text-red-500 animate-pulse" />
              </div>
            </div>
          ) : (
            <div className="mb-4">
              <button
                onClick={() => goLive(tournamentId)}
                disabled={activating === tournamentId}
                className={`w-full flex items-center justify-center gap-2 py-2 rounded-xl font-bold text-[9px] uppercase tracking-wider border transition-all ${t.status === "completed"
                  ? "bg-violet-500/10 hover:bg-violet-500/20 text-violet-400 border-violet-500/20"
                  : "bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-500 border-emerald-500/20"
                  }`}
              >
                {activating === tournamentId ? <Clock className="w-3 h-3 animate-spin" /> : <Play className="w-3 h-3" />}
                {t.status === "completed" ? "Retry to Live" : "Set As Live Auction"}
              </button>
            </div>
          )}

          {/* Actions Footer */}
          <div className="flex items-center gap-3">
            {t.status === "active" ? (
              <>
                <Link
                  href={`/live-auction?id=${tournamentId}&role=admin`}
                  className="flex-1 flex items-center justify-center gap-2 py-2 bg-red-600 hover:bg-red-500 text-white rounded-lg font-black text-[10px] uppercase tracking-wider shadow-lg shadow-red-600/20 transition-all active:scale-95"
                >
                  <Zap className="w-3.5 h-3.5" /> Start Engine
                </Link>
                <button
                  onClick={() => {
                    const url = `${window.location.origin}${t.applyToken ? getCanonicalApplyRoute(t.applyToken) : `/register/${tournamentId}`}`;
                    navigator.clipboard.writeText(url);
                    alert("Registration Link Copied!");
                  }}
                  className="w-10 h-10 flex items-center justify-center bg-violet-600/20 hover:bg-violet-600 text-violet-400 hover:text-white rounded-lg transition-all border border-violet-500/20"
                  title="Copy Registration Link"
                >
                  <Users className="w-3.5 h-3.5" />
                </button>
                <Link
                  href={`${t.applyToken ? getCanonicalApplyRoute(t.applyToken) : `/register/${tournamentId}`}?edit=true`}
                  className="w-10 h-10 flex items-center justify-center bg-slate-800 hover:bg-slate-700 text-white rounded-lg transition-all active:scale-95 border border-white/5"
                  title="Configure Portal"
                >
                  <Edit className="w-3.5 h-3.5" />
                </Link>
              </>
            ) : (
              <>
                <Link
                  href={`/live-auction?id=${tournamentId}&role=admin`}
                  className="flex-1 flex items-center justify-center gap-2 py-2 bg-violet-600 hover:bg-violet-500 text-white rounded-lg font-black text-[10px] uppercase tracking-wider transition-all active:scale-95"
                >
                  <ExternalLink className="w-3.5 h-3.5" /> Review Results
                </Link>
                <button
                  onClick={() => {
                    const url = `${window.location.origin}${t.applyToken ? getCanonicalApplyRoute(t.applyToken) : `/register/${tournamentId}`}`;
                    navigator.clipboard.writeText(url);
                    alert("Registration Link Copied!");
                  }}
                  className="w-10 h-10 flex items-center justify-center bg-violet-600/20 hover:bg-violet-600 text-violet-400 hover:text-white rounded-lg transition-all border border-violet-500/20"
                  title="Copy Registration Link"
                >
                  <Users className="w-3.5 h-3.5" />
                </button>
                <Link
                  href={`${t.applyToken ? getCanonicalApplyRoute(t.applyToken) : `/register/${tournamentId}`}?edit=true`}
                  className="flex-1 flex items-center justify-center gap-2 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg font-black text-[10px] uppercase tracking-wider transition-all active:scale-95 border border-white/5"
                >
                  <Edit className="w-3.5 h-3.5" /> Portal Settings
                </Link>
              </>
            )}

            <div className="flex shrink-0 gap-2">
              <button
                onClick={() => setEditingTournament(t)}
                className="p-3 bg-violet-500/10 text-violet-400 border border-violet-500/20 rounded-xl hover:bg-violet-500/20 transition-all active:scale-95"
                title="Tournament Settings"
              >
                <Settings className="w-4 h-4" />
              </button>
              <label className="p-3 bg-violet-500/10 text-violet-400 border border-violet-500/20 rounded-xl hover:bg-violet-500/20 transition-all active:scale-95 cursor-pointer" title="Add More Players (Excel)">
                {appending === tournamentId ? <RefreshCw className={`w-4 h-4 animate-spin`} /> : <PlusCircle className="w-4 h-4" />}
                <input type="file" className="hidden" accept=".xlsx,.xls,.csv" onChange={(e) => handleAppendPlayers(tournamentId, e)} />
              </label>
              <button
                onClick={() => resetAuction(tournamentId)}
                disabled={resetting === tournamentId}
                className="p-3 bg-amber-500/10 text-amber-500 border border-amber-500/20 rounded-xl hover:bg-amber-500/20 transition-all active:scale-95 disabled:opacity-50"
                title="Reset Auction Pool"
              >
                <RotateCcw className={`w-4 h-4 ${resetting === tournamentId ? 'animate-spin' : ''}`} />
              </button>
              <button
                onClick={() => deleteAuction(tournamentId)}
                disabled={deleting === tournamentId}
                className="p-3 bg-red-500/10 text-red-500 border border-red-500/20 rounded-xl hover:bg-red-500/20 transition-all active:scale-95 disabled:opacity-50"
                title="Permanently Delete Auction"
              >
                <Trash2 className={`w-4 h-4 ${deleting === tournamentId ? 'animate-spin' : ''}`} />
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-12 max-w-7xl mx-auto pb-20">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-white tracking-tight">
            Tournaments <span className="text-violet-500">History</span>
          </h1>
          <p className="text-slate-500 text-sm mt-1">Manage and monitor all your auction events</p>
        </div>
        <Link
          href="/admin/create-tournament"
          className="px-6 py-2.5 bg-linear-to-r from-violet-600 to-cyan-500 text-white rounded-xl font-bold flex items-center justify-center gap-2 shadow-lg shadow-violet-600/20 hover:scale-105 transition-all"
        >
          <PlusCircle className="w-4 h-4" />
          Create New
        </Link>
      </div>

      {/* ── LIVE AUCTIONS SECTION ── */}
      {liveTournaments.length > 0 && (
        <section className="space-y-6">
          <div className="flex items-center gap-4">
            <h2 className="text-xl font-black text-white uppercase tracking-widest flex items-center gap-2">
              <Zap className="w-5 h-5 text-red-500 animate-pulse" />
              Live Auctions
            </h2>
            <div className="h-px flex-1 bg-linear-to-r from-red-500/20 to-transparent" />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {liveTournaments.map(renderTournamentCard)}
          </div>
        </section>
      )}

      {/* ── CONCLUDED AUCTIONS SECTION ── */}
      <section className="space-y-6">
        <div className="flex items-center gap-4">
          <h2 className="text-xl font-black text-white uppercase tracking-widest flex items-center gap-2">
            <CheckCircle className="w-5 h-5 text-emerald-500" />
            Concluded Auctions
          </h2>
          <div className="h-px flex-1 bg-linear-to-r from-emerald-500/20 to-transparent" />
        </div>

        {concludedTournaments.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {concludedTournaments.map(renderTournamentCard)}
          </div>
        ) : (
          <div className="py-20 rounded-[3rem] border-2 border-dashed border-white/5 flex flex-col items-center justify-center opacity-40">
            <Trophy className="w-12 h-12 text-slate-500 mb-4" />
            <p className="font-bold text-slate-500 uppercase tracking-widest text-xs">No concluded auctions yet</p>
          </div>
        )}
      </section>

      {/* ── OTHER/DRAFT SECTION (Optional) ── */}
      {otherTournaments.length > 0 && (
        <section className="space-y-6">
          <div className="flex items-center gap-4">
            <h2 className="text-xl font-black text-white uppercase tracking-widest flex items-center gap-2">
              <Clock className="w-5 h-5 text-slate-500" />
              Draft / Upcoming
            </h2>
            <div className="h-px flex-1 bg-linear-to-r from-slate-500/20 to-transparent" />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {otherTournaments.map(renderTournamentCard)}
          </div>
        </section>
      )}

      {/* Settings Modal */}
      {editingTournament && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="w-full max-w-md bg-[#111827] border border-white/10 rounded-[2.5rem] overflow-hidden shadow-2xl">
            <div className="px-8 py-6 border-b border-white/5 flex items-center justify-between">
              <div>
                <h2 className="text-xl font-black text-white">Auction Settings</h2>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">{editingTournament.name}</p>
              </div>
              <button onClick={() => setEditingTournament(null)} className="p-2 hover:bg-white/5 rounded-full text-slate-400">
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleUpdateSettings} className="p-8 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 block">Auction Engine</label>
                  <select
                    className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white font-bold outline-none focus:border-violet-500 transition-all"
                    value={editingTournament.auctionMode || "money"}
                    onChange={(e) => setEditingTournament({ ...editingTournament, auctionMode: e.target.value })}
                  >
                    <option value="money">Money-Based Auction</option>
                    <option value="points">Points-Based Auction</option>
                  </select>
                </div>

                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 block">Currency Unit</label>
                  <select
                    className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-white font-bold outline-none focus:border-violet-500 transition-all"
                    value={editingTournament.currencyUnit || (editingTournament.auctionMode === "points" ? "CR" : "₹")}
                    onChange={(e) => setEditingTournament({ ...editingTournament, currencyUnit: e.target.value })}
                  >
                    <option value="CR">CR (Credits)</option>
                    <option value="PTS">PTS (Points)</option>
                    <option value="RS">RS (Rupees Text)</option>
                    <option value="₹">₹ (Rupee Symbol)</option>
                  </select>
                </div>
              </div>

              <div className="pt-4 flex gap-3">
                <button
                  type="button"
                  onClick={() => setEditingTournament(null)}
                  className="flex-1 py-3 border border-white/10 rounded-xl text-slate-400 font-bold hover:bg-white/5 transition-all"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isUpdating}
                  className="flex-1 py-3 bg-linear-to-r from-violet-600 to-cyan-500 text-white rounded-xl font-bold shadow-lg shadow-violet-600/20 hover:scale-105 transition-all disabled:opacity-50"
                >
                  {isUpdating ? "Saving..." : "Save Changes"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";

// Hide number input spinners
if (typeof window !== 'undefined') {
  const style = document.createElement('style');
  style.textContent = `
    input[type=number]::-webkit-inner-spin-button,
    input[type=number]::-webkit-outer-spin-button {
      -webkit-appearance: none;
      margin: 0;
    }
    input[type=number] {
      -moz-appearance: textfield;
    }
  `;
  document.head.appendChild(style);
}
import Link from "next/link"
import * as XLSX from "xlsx"
import { uploadToS3 } from "../../lib/uploadToS3"
import { API_URL } from "../../lib/apiConfig"

export default function AuctionDashboard() {
  const router = useRouter()
  const { data: session, status } = useSession()
  
  // Dashboard & Navigation State - Move all hooks to top
  const [pastTournaments, setPastTournaments] = useState([])
  const [backendError, setBackendError] = useState(false)
  const [loading, setLoading] = useState(false)
  const [errors, setErrors] = useState({})
  const [isSessionReady, setIsSessionReady] = useState(false)
  
  // New Tournament Logic State with localStorage persistence
  const [config, setConfig] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('tournamentConfig');
      return saved ? JSON.parse(saved) : {
        name: "", 
        numTeams: 10,
        iconsPerTeam: 3,
        baseBudget: 10000,
        defaultBasePrice: 100,
        squadSize: 15,
        auctionSlots: 120
      };
    }
    return {
      name: "", 
      numTeams: 10,
      iconsPerTeam: 3,
      baseBudget: 10000,
      defaultBasePrice: 100,
      squadSize: 15,
      auctionSlots: 120
    };
  })
  
  const [teams, setTeams] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('tournamentTeams');
      return saved ? JSON.parse(saved) : [];
    }
    return [];
  })
  
  const [players, setPlayers] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('tournamentPlayers');
      return saved ? JSON.parse(saved) : [];
    }
    return [];
  })
  
  const [iconPlayers, setIconPlayers] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('tournamentIconPlayers');
      return saved ? JSON.parse(saved) : [];
    }
    return [];
  })

  const [step, setStep] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('tournamentStep');
      return saved ? parseInt(saved) : 1;
    }
    return 1;
  })

  const [showCreateForm, setShowCreateForm] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('tournamentShowCreateForm');
      return saved ? JSON.parse(saved) : false;
    }
    return false;
  })

  // Redirect non-admin users (but only after session is loaded)
  useEffect(() => {
    if (status === "loading") return; // Wait for session to load
    
    setIsSessionReady(true); // Mark session as ready
    
    if (!session || session.user?.role !== "admin") {
      router.push("/auctions")
      return
    }
  }, [session, status, router])

  // Restore state from localStorage after session is confirmed
  useEffect(() => {
    if (!isSessionReady || !session) return; // Wait for session to be ready
    
    // Only restore if user is admin
    if (session.user?.role === "admin") {
      const savedStep = localStorage.getItem('tournamentStep');
      const savedShowCreateForm = localStorage.getItem('tournamentShowCreateForm');
      
      if (savedStep) {
        setStep(parseInt(savedStep));
      }
      if (savedShowCreateForm) {
        setShowCreateForm(JSON.parse(savedShowCreateForm));
      }
    }
  }, [isSessionReady, session])

  // Save state to localStorage whenever it changes
  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('tournamentConfig', JSON.stringify(config));
    }
  }, [config])

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('tournamentTeams', JSON.stringify(teams));
    }
  }, [teams])

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('tournamentPlayers', JSON.stringify(players));
    }
  }, [players])

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('tournamentIconPlayers', JSON.stringify(iconPlayers));
    }
  }, [iconPlayers])

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('tournamentStep', step.toString());
    }
  }, [step])

  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('tournamentShowCreateForm', JSON.stringify(showCreateForm));
    }
  }, [showCreateForm])

  // Reset functions for individual steps
  const resetTeams = () => {
    const resetTeamsData = teams.map((team, index) => ({
      ...team,
      name: "",
      logoUrl: ""
    }));
    setTeams(resetTeamsData);
    setErrors(prev => ({ ...prev, teams: [] }));
  };

  const resetIcons = () => {
    const resetIconsData = iconPlayers.map((icon) => ({
      ...icon,
      name: "",
      role: "All-Rounder",
      village: "",
      age: "",
      imageUrl: ""
    }));
    setIconPlayers(resetIconsData);
    setErrors(prev => ({ ...prev, icons: [] }));
  };

  // Full reset function
  const resetTournament = () => {
    setConfig({ 
      name: "", 
      numTeams: 10,
      iconsPerTeam: 3,
      baseBudget: 10000,
      defaultBasePrice: 100,
      squadSize: 15,
      auctionSlots: 120
    });
    setTeams([]);
    setPlayers([]);
    setIconPlayers([]);
    setStep(1);
    setErrors({});
    
    // Clear localStorage
    if (typeof window !== 'undefined') {
      localStorage.removeItem('tournamentConfig');
      localStorage.removeItem('tournamentTeams');
      localStorage.removeItem('tournamentPlayers');
      localStorage.removeItem('tournamentIconPlayers');
      localStorage.removeItem('tournamentStep');
      localStorage.removeItem('tournamentShowCreateForm');
    }
  };

  // Fetch tournaments data
  useEffect(() => {
    fetchTournaments()
  }, [])

  const fetchTournaments = () => {
    fetch(`${API_URL}/api/tournaments`)
      .then(res => res.ok ? res.json() : Promise.reject("Offline"))
      .then(data => {
        setPastTournaments(data)
        setBackendError(false)
      })
      .catch(err => {
        console.error("Dashboard fetch error:", err)
        setBackendError(true)
      })
  }

  if (status === "loading" || !isSessionReady) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
        <div className="text-center">
          <div className="text-white text-xl mb-2">Loading Auction Dashboard...</div>
          <div className="text-slate-400 text-sm">Restoring your tournament data</div>
        </div>
      </div>
    )
  }

  if (!session || session.user?.role !== "admin") {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
        <div className="text-center">
          <h1 className="text-2xl font-bold text-white mb-4">Access Denied</h1>
          <p className="text-slate-400 mb-6">This area is restricted to administrators only.</p>
          <Link 
            href="/auctions" 
            className="px-6 py-3 bg-violet-600 text-white rounded-lg hover:bg-violet-500 transition-colors"
          >
            View Live Auctions
          </Link>
        </div>
      </div>
    )
  }

  const STEP_TOTAL = 5;

  // Robust Excel Mapping Helper
  const fixUrl = (url) => {
  if (!url) return "";
  if (url.includes("drive.google.com")) {
    const match = url.match(/\/d\/(.+?)\//);
    if (match?.[1]) return `https://drive.google.com/uc?export=view&id=${match[1]}`;
    const idParam = new URLSearchParams(url.split("?")[1]).get("id");
    if (idParam) return `https://drive.google.com/uc?export=view&id=${idParam}`;
  }
  return url;
};

const hasNonEng = (s) => /[^\x00-\x7F]/.test(s);

function findValue(row, keys) {
  const rowKeys = Object.keys(row);
  for (const k of keys) {
    const found = rowKeys.find(rk => rk.toLowerCase().trim() === k.toLowerCase().trim());
    if (found) return row[found];
  }
  for (const k of keys) {
    const found = rowKeys.find(rk => rk.toLowerCase().includes(k.toLowerCase()) && !rk.toLowerCase().includes("team"));
    if (found) return row[found];
  }
  return null;
}

  const handleTeamsUpload = (e) => {
    const file = e.target.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = (evt) => {
      const bstr = evt.target.result
      try {
        const wb = XLSX.read(bstr, { type: 'binary' })
        const ws = wb.Sheets[wb.SheetNames[0]]
        const rows = XLSX.utils.sheet_to_json(ws)
        const imported = rows.map((row, index) => ({
          name: findValue(row, ["teamName", "team name", "name", "team"]) || `Team ${index + 1}`,
          shortName: findValue(row, ["shortName", "short name", "code", "id"]) || "TBD",
          logoUrl: findValue(row, ["logoUrl", "logo", "image", "logo link", "link"]) || "/teams/default-logo.png",
          color: ["bg-blue-600", "bg-purple-600", "bg-orange-600", "bg-red-600", "bg-violet-600", "bg-yellow-600"][index % 6]
        }))
        setTeams(imported)
        if (imported.length > 0) {
          setConfig(prev => ({ ...prev, numTeams: imported.length }))
          setErrors(prev => ({ ...prev, numTeams: "" }))
        }
      } catch (err) {
        alert("Invalid file format. Please check your Excel or CSV structure.")
      }
    }
    reader.readAsBinaryString(file)
    
    // Reset the file input to allow uploading the same file again
    e.target.value = ''
  }

  const handleIconsUpload = (e) => {
    const file = e.target.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = (evt) => {
      const bstr = evt.target.result
      try {
        const wb = XLSX.read(bstr, { type: 'binary' })
        const ws = wb.Sheets[wb.SheetNames[0]]
        const rows = XLSX.utils.sheet_to_json(ws)
        const imported = rows.map((row, index) => ({
          name: findValue(row, ["player name", "playerName", "icon", "name"]) || "",
          role: findValue(row, ["role", "type", "position"]) || "All-Rounder",
          age: Number(findValue(row, ["age", "years"])) || 0,
          village: findValue(row, ["village", "town"]) || "-",
          imageUrl: findValue(row, ["imageUrl", "photo", "image", "link", "url"]) || "",
          teamMatch: findValue(row, ["team", "teamName", "team name"]),
          teamLogo: findValue(row, ["logo", "team logo", "logo link"])
        })).filter(p => p.name && p.teamMatch);

        const newIcons = [...iconPlayers];
        const newTeams = [...teams];

        imported.forEach(imp => {
          const tIdx = newTeams.findIndex(t => t.name.toLowerCase().includes(imp.teamMatch.toLowerCase()));
          if (tIdx !== -1) {
            // Update team logo if provided
            if (imp.teamLogo) {
              newTeams[tIdx].logoUrl = imp.teamLogo;
            }
            
            // Assign icon player to slot
            const firstEmpty = newIcons.findIndex(p => p.teamIdx === tIdx && !p.name);
            if (firstEmpty !== -1) {
              newIcons[firstEmpty] = { ...newIcons[firstEmpty], ...imp, team: newTeams[tIdx].name };
            }
          }
        });
        setTeams(newTeams);
        setIconPlayers(newIcons);
      } catch (err) {
        alert("Invalid icon player file format. Supports .xlsx, .xls, and .csv")
      }
    }
    reader.readAsBinaryString(file)
    
    // Reset the file input to allow uploading the same file again
    e.target.value = ''
  }

  const handlePlayersUpload = (e) => {
    const file = e.target.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = (evt) => {
      const bstr = evt.target.result
      try {
        const wb = XLSX.read(bstr, { type: 'binary' })
        const ws = wb.Sheets[wb.SheetNames[0]]
        const rows = XLSX.utils.sheet_to_json(ws)
        const imported = rows.map((row, i) => ({
          id: i + 1,
          name:         findValue(row, ["player name", "playerName", "name", "player", "ಆಟಗಾರನ ಹೆಸರು"]) || "PLAYER NAME",
          role:         findValue(row, ["role", "type", "position", "ಪಾತ್ರ"]) || "All-Rounder",
          age:          Number(findValue(row, ["age", "years", "ವಯಸ್ಸು"])) || 0,
          dob:          findValue(row, ["dob", "date of birth", "birth", "ಹುಟ್ಟಿದ ದಿನಾಂಕ"]) || "",
          battingStyle: findValue(row, ["batting", "battingStyle", "style", "ಬ್ಯಾಟಿಂಗ್"]) || "Right Hand",
          bowlingStyle: findValue(row, ["bowling", "bowlingStyle", "ಬೌಲಿಂಗ್"]) || "-",
          village:      findValue(row, ["village", "town", "city", "ಗ್ರಾಮ", "ಸ್ಥಳ"]) || "-",
          basePrice:    Number(findValue(row, ["basePrice", "price", "base price", "amount", "ಮೂಲ ಬೆಲೆ"])) || config.defaultBasePrice,
          imageUrl:     fixUrl(findValue(row, ["imageUrl", "photo", "image", "link", "url", "ಭಾವಚಿತ್ರ"])) || "",
          status:       "available",
        }));
        setPlayers(imported);

        // Process Drive URLs via Proxy to S3
        const API = API_URL;
        imported.forEach((p, idx) => {
          if (p.imageUrl && p.imageUrl.includes("drive.google.com")) {
            fetch(`${API}/api/upload/proxy-url`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ url: p.imageUrl, folder: "players" })
            })
            .then(r => r.json())
            .then(data => {
              if (data.s3Url) {
                setPlayers(prev => {
                  const next = [...prev];
                  if (next[idx]) next[idx].imageUrl = data.s3Url;
                  return next;
                });
              }
            });
          }
        });
      } catch (err) {
        alert("Invalid player file format. Supports .xlsx, .xls, and .csv")
      }
    }
    reader.readAsBinaryString(file)
  }

  const handleImageUpload = async (e, callback, folder = "teams") => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      setLoading(true);
      const url = await uploadToS3(file, folder);
      callback(url);
    } catch (err) {
      console.error("Upload error:", err);
      alert("Upload failed: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  const startAuction = async () => {
    if (players.length === 0) return alert("Please upload players first")

    setLoading(true)
    try {
      const res = await fetch(`${API_URL}/api/tournaments`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...config,
          teams: teams,
          players: [
            ...iconPlayers.map(p => ({ ...p, isIcon: true, status: "sold", soldPrice: 0 })),
            ...players
          ]
        })
      })
      const data = await res.json()
      if (data.tournamentId) {
        router.push(`/live-auction?id=${data.tournamentId}`)
      }
    } catch (err) {
      alert("Error starting auction. Ensure the backend server is running on port 5000.")
    } finally {
      setLoading(false)
    }
  }

  const validateStep1 = () => {
    const newErrors = {};
    if (!config.name.trim()) newErrors.name = "Required";
    if (!config.numTeams || config.numTeams < 2) newErrors.numTeams = "Min 2 teams";
    if (!config.iconsPerTeam || config.iconsPerTeam < 0) newErrors.iconsPerTeam = "Required";
    if (config.baseBudget === "" || config.baseBudget < 0) newErrors.baseBudget = "Required";
    if (config.defaultBasePrice === "" || config.defaultBasePrice < 0) newErrors.defaultBasePrice = "Required";
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  const validateStep2 = () => {
    const teamErrors = teams.map(t => ({
      name: !t.name.trim(),
      shortName: !t.shortName.trim()
    }));
    
    setErrors({ teams: teamErrors });
    return !teamErrors.some(e => e.name || e.shortName);
  }

  const validateStep3 = () => {
    const iconErrors = iconPlayers.map(p => ({
      name: !p.name.trim()
    }));
    
    setErrors({ icons: iconErrors });
    return !iconErrors.some(e => e.name);
  }

  const nextStep = () => {
    if (step === 1) {
      if (validateStep1()) {
        if (teams.length !== Number(config.numTeams)) {
          const newTeams = Array.from({ length: Number(config.numTeams) }, (_, i) => ({
            name: teams[i]?.name || `Team ${i + 1}`,
            shortName: teams[i]?.shortName || `T${i + 1}`,
            logoUrl: teams[i]?.logoUrl || "",
            color: ["bg-blue-600", "bg-purple-600", "bg-orange-600", "bg-red-600", "bg-violet-600", "bg-yellow-600"][i % 6]
          }));
          setTeams(newTeams);
        }
        setStep(2);
      } else {
        alert("Please fill all required tournament details (marked in red).");
      }
    } else if (step === 2) {
      if (validateStep2()) {
        const totalIcons = config.numTeams * config.iconsPerTeam;
        if (iconPlayers.length !== totalIcons) {
          const newIcons = [];
          teams.forEach((team, teamIdx) => {
            for (let i = 0; i < config.iconsPerTeam; i++) {
              newIcons.push({
                name: "", role: "All-Rounder", village: "", age: "", team: team.name, teamIdx: teamIdx, imageUrl: ""
              });
            }
          });
          setIconPlayers(newIcons);
        } else {
          const syncedIcons = iconPlayers.map(icon => ({
            ...icon,
            team: teams[icon.teamIdx]?.name || icon.team
          }));
          setIconPlayers(syncedIcons);
        }
        setStep(3);
      } else {
        alert("Please provide names and codes for all teams.");
      }
    } else if (step === 3) {
      if (validateStep3()) {
        setStep(4);
      } else {
        alert("Please provide names for all assigned Icon Players.");
      }
    } else if (step === 4) {
    } else if (step === 5) {
      if (players.length === 0) return alert("Please upload the auction players Excel file first.");
      setStep(6);
    }
  }
  const prevStep = () => setStep(s => Math.max(s - 1, 1))

  return (
    <div className="min-h-screen bg-[#0f172a] text-white font-sans selection:bg-violet-500/30">
      {/* Back Button */}
      <div className="sticky top-4 z-50 flex justify-start">
        <Link href="/" className="bg-violet-600 hover:bg-violet-500 px-4 py-2 rounded-xl text-sm font-bold transition-all border border-violet-500 whitespace-nowrap backdrop-blur-md min-h-[40px] flex items-center shadow-lg m-4">
          ← Back to Home
        </Link>
      </div>
      
      {/* Background Decor */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-[10%] -left-[10%] w-[40%] h-[40%] bg-violet-500/10 blur-[120px] rounded-full" />
        <div className="absolute -bottom-[10%] -right-[10%] w-[40%] h-[40%] bg-blue-500/10 blur-[120px] rounded-full" />
      </div>

      <div className="relative z-10 max-w-6xl mx-auto px-4 py-12">
        {/* Header */}
        <header className="flex justify-between items-center mb-12">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-gradient-to-tr from-violet-500 to-teal-400 rounded-2xl flex items-center justify-center shadow-lg shadow-violet-500/20">
              <span className="text-2xl">🏆</span>
            </div>
            <div>
              <h1 className="text-2xl font-black tracking-tight uppercase">Auctions</h1>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Management Dashboard</p>
            </div>
          </div>
          
          {!showCreateForm && (
            <button 
              onClick={() => {
                setShowCreateForm(true)
                setStep(1)
                setErrors({})
                setConfig({ 
                  name: "", 
                  numTeams: 10,
                  iconsPerTeam: 3,
                  baseBudget: 10000,
                  defaultBasePrice: 100,
                  squadSize: 11
                })
                setTeams([])
                setPlayers([])
                setIconPlayers([])
              }}
              className="bg-violet-600 hover:bg-violet-500 text-white px-6 py-3 rounded-xl font-bold transition-all shadow-lg shadow-violet-600/20 active:scale-95 flex items-center gap-2"
            >
              <span>+</span> NEW TOURNAMENT
            </button>
          )}
        </header>

        {backendError && (
          <div className="mb-8 bg-red-500/10 border border-red-500/20 p-4 rounded-xl flex items-center gap-4 animate-pulse">
            <span className="text-xl">⚠️</span>
            <p className="text-red-400 text-sm font-semibold">Backend Offline. Check your server connection.</p>
          </div>
        )}

        {!showCreateForm ? (
          <main>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {pastTournaments.length > 0 ? (
                pastTournaments.map(t => (
                  <div key={t._id} className="group relative bg-slate-800/40 border border-slate-700/50 p-6 rounded-3xl hover:border-violet-500/50 hover:bg-slate-800/60 transition-all duration-300 shadow-xl overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-100 transition-opacity">
                      <span className="text-4xl opacity-20">🏆</span>
                    </div>
                    <div className="relative z-10">
                      <div className="flex items-center gap-3 mb-4">
                        <span className={`w-2 h-2 rounded-full ${t.status === 'active' ? 'bg-violet-500' : 'bg-slate-500'}`} />
                        <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">{t.status}</span>
                      </div>
                      <h3 className="text-xl font-black mb-1 truncate uppercase group-hover:text-violet-400 transition-colors">{t.name}</h3>
                      <p className="text-slate-500 text-xs font-bold mb-6">CREATED: {new Date(t.createdAt).toLocaleDateString()}</p>
                      
                      <div className="flex items-center justify-between mt-auto">
                        <div className="flex flex-col">
                          <span className="text-slate-400 text-[10px] font-bold uppercase">Teams</span>
                          <span className="text-lg font-black text-white">{t.numTeams}</span>
                        </div>
                        <Link 
                          href={`/live-auction?id=${t._id}`}
                          className="bg-slate-700 hover:bg-violet-600 text-white px-5 py-2.5 rounded-xl font-bold text-xs transition-all shadow-lg active:scale-95"
                        >
                          ENTER ARENA →
                        </Link>
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="col-span-full py-20 bg-slate-800/20 border-2 border-dashed border-slate-700 rounded-[3rem] text-center">
                  <div className="text-6xl mb-4 opacity-20">🏟️</div>
                  <h3 className="text-xl font-bold text-slate-400">No Tournaments Found</h3>
                  <p className="text-slate-500 text-sm mt-2">Start by creating your first auction league.</p>
                </div>
              )}
            </div>
          </main>
        ) : (
          <main className="max-w-4xl mx-auto">
            {/* Progress Indicator */}
            <div className="flex items-center justify-between mb-12 relative px-4">
              <div className="absolute top-1/2 left-0 w-full h-0.5 bg-slate-800 -translate-y-1/2 z-0" />
              <div 
                className="absolute top-1/2 left-0 h-0.5 bg-gradient-to-r from-violet-500 to-blue-500 -translate-y-1/2 z-0 transition-all duration-500 ease-out" 
                style={{ width: `${((step - 1) / (STEP_TOTAL - 1)) * 100}%` }}
              />
              {[1, 2, 3, 4, 5, 6].map((s) => (
                <div key={s} className="relative z-10 flex flex-col items-center gap-3">
                  <div className={`
                    w-10 h-10 rounded-xl flex items-center justify-center font-black transition-all duration-300 text-xs
                    ${step > s ? 'bg-violet-500 shadow-lg shadow-violet-500/20' : 
                      step === s ? 'bg-white text-slate-900 shadow-xl shadow-white/10 scale-110' : 
                      'bg-slate-800 text-slate-500 border border-slate-700'}
                  `}>
                    {step > s ? <span className="text-base">✓</span> : s}
                  </div>
                </div>
              ))}
            </div>

            {/* Step Content */}
            <div className="bg-slate-800/40 border border-white/5 rounded-[2.5rem] p-8 md:p-12 shadow-2xl backdrop-blur-xl">
              
              {/* Step 1: Tournament Setup */}
              {step === 1 && (
                <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="text-center flex justify-between items-center">
                    <div>
                      <h2 className="text-3xl font-black mb-2 uppercase tracking-tight">1. Tournament Information</h2>
                      <p className="text-slate-400 text-sm">Define the core parameters of your tournament.</p>
                    </div>
                    <button
                      onClick={resetTournament}
                      className="bg-red-600/10 hover:bg-red-600/20 text-red-400 border border-red-600/20 px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center gap-2"
                    >
                      🔄 Reset All
                    </button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="md:col-span-2">
                       <div className="flex justify-between px-1">
                          <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Tournament Name</label>
                          {errors.name && <span className="text-[10px] text-red-500 font-bold uppercase animate-pulse">Required!</span>}
                       </div>
                       <input 
                         type="text" 
                         value={config.name} 
                         onChange={e => { setConfig({...config, name: e.target.value}); setErrors({...errors, name: ""}); }}
                         placeholder="IPL 2024 / Village League..."
                         className={`w-full bg-slate-900 border ${errors.name ? 'border-red-500' : 'border-slate-700'} rounded-2xl px-6 py-4 font-bold text-lg text-violet-400 outline-none focus:border-violet-500 transition-all`}
                       />
                    </div>
                    <div>
                       <div className="flex justify-between px-1">
                          <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Number of Teams</label>
                          {errors.numTeams && <span className="text-[10px] text-red-500 font-bold uppercase animate-pulse">{errors.numTeams}</span>}
                       </div>
                       <input 
                         type="number" 
                         value={config.numTeams} 
                         onChange={e => { setConfig({...config, numTeams: Number(e.target.value) || 0}); setErrors({...errors, numTeams: ""}); }}
                         className={`w-full bg-slate-900 border ${errors.numTeams ? 'border-red-500' : 'border-slate-700'} rounded-2xl px-6 py-4 font-bold outline-none focus:border-violet-500 transition-all`}
                       />
                    </div>
                    <div>
                        <div className="flex justify-between px-1">
                           <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Icons per Team</label>
                           {errors.iconsPerTeam && <span className="text-[10px] text-red-500 font-bold uppercase animate-pulse">Required!</span>}
                        </div>
                        <input 
                          type="number" 
                          value={config.iconsPerTeam} 
                          onChange={e => { setConfig({...config, iconsPerTeam: Number(e.target.value) || 0}); setErrors({...errors, iconsPerTeam: ""}); }}
                          className={`w-full bg-slate-900 border ${errors.iconsPerTeam ? 'border-red-500' : 'border-slate-700'} rounded-2xl px-6 py-4 font-bold outline-none focus:border-violet-500 transition-all`}
                        />
                     </div>
                    <div>
                       <div className="flex justify-between px-1">
                          <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Team Budget (₹)</label>
                          {errors.baseBudget && <span className="text-[10px] text-red-500 font-bold uppercase animate-pulse">Required!</span>}
                       </div>
                       <input 
                         type="number" 
                         value={config.baseBudget} 
                         onChange={e => { setConfig({...config, baseBudget: Number(e.target.value) || 0}); setErrors({...errors, baseBudget: ""}); }}
                         className={`w-full bg-slate-900 border ${errors.baseBudget ? 'border-red-500' : 'border-slate-700'} rounded-2xl px-6 py-4 font-bold text-yellow-500 outline-none focus:border-violet-500 transition-all`}
                       />
                    </div>
                    <div>
                       <div className="flex justify-between px-1">
                          <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Default Base Price (₹)</label>
                          {errors.defaultBasePrice && <span className="text-[10px] text-red-500 font-bold uppercase animate-pulse">Required!</span>}
                       </div>
                       <input 
                         type="number" 
                         value={config.defaultBasePrice} 
                         onChange={e => { setConfig({...config, defaultBasePrice: Number(e.target.value) || 0}); setErrors({...errors, defaultBasePrice: ""}); }}
                         className={`w-full bg-slate-900 border ${errors.defaultBasePrice ? 'border-red-500' : 'border-slate-700'} rounded-2xl px-6 py-4 font-bold text-white outline-none focus:border-violet-500 transition-all`}
                       />
                    </div>
                  </div>
                </div>
              )}

              {/* Step 2: Add Teams */}
              {step === 2 && (
                <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="text-center flex justify-between items-center">
                    <div>
                      <h2 className="text-3xl font-black mb-2 uppercase tracking-tight">2. Teams Setup</h2>
                      <div className="flex justify-center gap-4 mb-6">
                        <p className="text-slate-400 text-sm">Configure your {config.numTeams} teams.</p>
                        <label className="cursor-pointer bg-violet-600/10 hover:bg-violet-600/20 border border-violet-500/20 px-3 py-1 rounded-xl text-[10px] font-black uppercase tracking-widest text-violet-400 transition-all flex items-center gap-2">
                          <span>Bulk Upload Teams</span>
                          <input type="file" className="hidden" accept=".xlsx,.xls,.csv" onChange={handleTeamsUpload} />
                          <span>📥</span>
                        </label>
                      </div>
                    </div>
                    <button
                      onClick={resetTeams}
                      className="bg-red-600/10 hover:bg-red-600/20 text-red-400 border border-red-600/20 px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center gap-2"
                    >
                      🔄 Reset Teams
                    </button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto px-2 custom-scrollbar pr-4">
                    {teams.map((team, idx) => (
                      <div key={idx} className={`bg-slate-900/60 border ${errors.teams?.[idx]?.name || errors.teams?.[idx]?.shortName ? 'border-red-500/50 shadow-lg shadow-red-500/5' : 'border-slate-700'} rounded-3xl p-6 flex items-center gap-6 group hover:border-violet-500/30 transition-all`}>
                        <div className="w-20 h-20 rounded-2xl bg-slate-800 border border-slate-700 flex items-center justify-center overflow-hidden shrink-0 group-hover:scale-105 transition-transform">
                          <img src={team.logoUrl || `https://ui-avatars.com/api/?name=${team.name || (idx + 1)}&background=random`} alt="logo" className="w-full h-full object-cover" />
                        </div>
                        <div className="flex-1 space-y-3">
                          <input 
                            placeholder="Team Name"
                            value={team.name}
                            onChange={(e) => {
                              const nt = [...teams];
                              nt[idx].name = e.target.value;
                              setTeams(nt);
                              setErrors(prev => ({ 
                                ...prev, 
                                teams: prev.teams?.map((te, i) => i === idx ? { ...te, name: false } : te) 
                              }));
                            }}
                            className={`w-full bg-transparent border-b ${errors.teams?.[idx]?.name ? 'border-red-500' : 'border-slate-700'} py-1 font-black text-white focus:border-violet-500 outline-none placeholder:text-slate-600`}
                          />
                          <div className="flex items-center gap-2">
                             <label className="w-full h-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-1 text-[10px] font-bold cursor-pointer hover:border-violet-500 flex items-center justify-between transition-all">
                               <input 
                                 type="file" 
                                 className="hidden" 
                                 accept="image/*" 
                                 onChange={(e) => handleImageUpload(e, (url) => {
                                   const nt = [...teams];
                                   nt[idx].logoUrl = url;
                                   setTeams(nt);
                                 })} 
                               />
                               <span className="text-slate-500">{team.logoUrl ? "Uploaded" : "Upload Logo"}</span>
                               <span className="text-violet-500">{team.logoUrl ? "🔄" : "📸"}</span>
                             </label>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Step 3: Icon Players */}
              {step === 3 && (
                <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="text-center flex justify-between items-center">
                    <div>
                      <h2 className="text-3xl font-black mb-2 uppercase tracking-tight">3. Icon Players</h2>
                      <div className="flex justify-center gap-4 mb-6">
                        <p className="text-slate-400 text-sm">Assign icons to each team.</p>
                        <label className="cursor-pointer bg-blue-600/10 hover:bg-blue-600/20 border border-blue-500/20 px-3 py-1 rounded-xl text-[10px] font-black uppercase tracking-widest text-blue-400 transition-all flex items-center gap-2">
                          <span>Bulk Upload Icons</span>
                          <input type="file" className="hidden" accept=".xlsx,.xls,.csv" onChange={handleIconsUpload} />
                          <span>📥</span>
                        </label>
                      </div>
                    </div>
                    <button
                      onClick={resetIcons}
                      className="bg-red-600/10 hover:bg-red-600/20 text-red-400 border border-red-600/20 px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center gap-2"
                    >
                      🔄 Reset Icons
                    </button>
                  </div>

                  <div className="space-y-12 max-h-[500px] overflow-y-auto px-4 custom-scrollbar pr-6">
                    {teams.map((team, tIdx) => (
                      <div key={tIdx} className="space-y-4">
                        <div className="flex items-center gap-3 border-l-4 border-violet-500 pl-4 py-1">
                          <h3 className="font-black uppercase tracking-widest text-violet-400">{team.name} Icons</h3>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {iconPlayers.map((icon, fullIdx) => {
                            if (icon.teamIdx !== tIdx) return null;
                            const iconInTeamIdx = iconPlayers.filter((p, i) => p.teamIdx === tIdx && i < fullIdx).length;
                            const hasError = errors.icons?.[fullIdx]?.name;
                            
                            return (
                              <div key={fullIdx} className={`bg-slate-900 border ${hasError ? 'border-red-500' : 'border-slate-800'} rounded-3xl p-6 space-y-4`}>
                                <div className="flex justify-between items-center px-1">
                                   <p className="text-[10px] font-black text-slate-600 uppercase">ICON {iconInTeamIdx + 1}</p>
                                   {hasError && <span className="text-[8px] text-red-500 font-bold uppercase animate-pulse">Required!</span>}
                                </div>
                                
                                {/* Player Image Preview */}
                                <div className="flex justify-center">
                                  <div className="w-24 h-24 rounded-2xl bg-slate-800 border border-slate-700 flex items-center justify-center overflow-hidden">
                                    {icon.imageUrl ? (
                                      <img src={icon.imageUrl} alt="Player" className="w-full h-full object-cover" />
                                    ) : (
                                      <span className="text-slate-600 text-4xl">👤</span>
                                    )}
                                  </div>
                                </div>
                                
                                <div className="grid grid-cols-2 gap-4">
                                  <div className="col-span-2">
                                     <input 
                                       placeholder="Player Name" 
                                       value={icon.name}
                                       onChange={(e) => {
                                         const ni = [...iconPlayers];
                                         ni[fullIdx].name = e.target.value;
                                         setIconPlayers(ni);
                                         setErrors(prev => ({ 
                                           ...prev, 
                                           icons: prev.icons?.map((er, i) => i === fullIdx ? { name: false } : er) 
                                         }));
                                       }}
                                       className={`w-full bg-slate-800 border ${hasError ? 'border-red-500' : 'border-slate-700'} rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-violet-500`}
                                     />
                                  </div>
                                  <div className="col-span-2">
                                    <label className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-xs font-bold cursor-pointer hover:border-violet-500 flex items-center justify-between transition-all">
                                       <span className="text-slate-500">{icon.imageUrl ? 'REPLACE PHOTO' : 'UPLOAD PHOTO'}</span>
                                       <input 
                                         type="file" 
                                         className="hidden" 
                                         accept="image/*" 
                                         onChange={(e) => handleImageUpload(e, (url) => {
                                           const ni = [...iconPlayers];
                                           ni[fullIdx].imageUrl = url;
                                           setIconPlayers(ni);
                                         }, "players")} 
                                       />
                                       <span className="text-violet-500">📸</span>
                                    </label>
                                  </div>
                                  <input 
                                    placeholder="Role" 
                                    value={icon.role}
                                    onChange={(e) => {
                                      const ni = [...iconPlayers];
                                      ni[fullIdx].role = e.target.value;
                                      setIconPlayers(ni);
                                    }}
                                    className="bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-xs font-bold outline-none focus:border-violet-500"
                                  />
                                  <input 
                                    placeholder="Village" 
                                    value={icon.village}
                                    onChange={(e) => {
                                      const ni = [...iconPlayers];
                                      ni[fullIdx].village = e.target.value;
                                      setIconPlayers(ni);
                                    }}
                                    className="bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-xs font-bold outline-none focus:border-violet-500"
                                  />
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Step 4: Upload Players */}
              {step === 4 && (
                <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="text-center">
                    <h2 className="text-3xl font-black mb-2 uppercase tracking-tight">4. Auction Players Upload</h2>
                    <p className="text-slate-400 text-sm">Upload the pool of players available for bidding.</p>
                  </div>

                  <div className="flex flex-col items-center">
                    <label className="w-full max-w-xl group relative border-2 border-dashed border-slate-700 hover:border-violet-500/50 rounded-[2rem] p-12 transition-all cursor-pointer bg-slate-900/20 hover:bg-violet-500/5 flex flex-col items-center gap-4">
                      <input type="file" className="hidden" accept=".xlsx,.xls,.csv" onChange={handlePlayersUpload} />
                      <div className="w-16 h-16 bg-slate-800 group-hover:bg-violet-500/20 rounded-2xl flex items-center justify-center text-3xl group-hover:scale-110 transition-transform duration-300">
                        📋
                      </div>
                      <div className="text-center">
                        <p className="font-bold text-lg text-slate-200">Upload players (Excel or CSV)</p>
                        <p className="text-slate-500 text-xs mt-1 font-semibold uppercase tracking-wider">contains name, role, base price, village etc.</p>
                      </div>
                    </label>
                  </div>

                  {players.length > 0 && (
                    <div className="bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl">
                      <div className="grid grid-cols-[80px_1fr_1fr_80px_1fr_120px] px-6 py-4 bg-slate-800/50 text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 border-b border-slate-700">
                        <span>Photo</span><span>Name</span><span>Role</span><span className="text-center">Age</span><span>Village</span><span className="text-right">Price</span>
                      </div>
                      <div className="max-h-[500px] overflow-y-auto divide-y divide-slate-800 custom-scrollbar">
                        {players.map((p, idx) => (
