  useEffect(() => {
    async function fetchSquads() {
      try {
        const res = await fetch(`${API_URL}/api/tournaments/${tournament._id}`);
        if (res.ok) {
          const json = await res.json();
          setData(json);
          if (json.teams?.length > 0) setSelectedTeam(json.teams[0]);
