import CurrencySymbol from "../../components/CurrencySymbol";

// Module-level socket instance to persist across React re-renders in development
let globalSocket = null;

function LiveAuctionContent({ initialTournament: tournament }) {
  const searchParams = useSearchParams();
  const router = useRouter();
  const { data: session, status } = useSession();
  const tournamentId = searchParams.get("id");
  const playerParam = searchParams.get("player");
  const initialPlayerIndex = playerParam ? parseInt(playerParam) - 1 : 0; // Convert 1-based to 0-based

  // ALL HOOKS MUST BE CALLED BEFORE ANY CONDITIONAL RETURNS
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [auctionBg, setAuctionBg] = useState('https://auction-platform-kp.s3.ap-south-1.amazonaws.com/banners/1777801051801.png');

  const [currentTournamentId, setCurrentTournamentId] = useState(tournamentId);
  const [activeAssets, setActiveAssets] = useState({
    splashUrl: "",
    backgroundUrl: "https://auction-platform-kp.s3.ap-south-1.amazonaws.com/banners/1777801051801.png",
    badges: { leftBadge: "", rightBadge: "" }
  });

  const [config, setConfig] = useState({ name: "", baseBudget: 0, totalTeams: 0, auctionMode: "money", iconsPerTeam: 2 });
  const [rules, setRules] = useState({});
  const [teams, setTeams] = useState([]);
  const [players, setPlayers] = useState([]);
  const [currentPlayerIndex, setCurrentPlayerIndex] = useState(0);
  const [currentBid, setCurrentBid] = useState(0);
  const [highestBidder, setHighestBidder] = useState(null);
  const [bidPulse, setBidPulse] = useState(false);
  const [roundHistory, setRoundHistory] = useState([]);
  const [results, setResults] = useState([]);
  const [lastBidTime, setLastBidTime] = useState(0);
  const [poolA, setPoolA] = useState([]);
  const [poolB, setPoolB] = useState([]);
  const [lastAssignment, setLastAssignment] = useState(null);
  const [showPoolView, setShowPoolView] = useState(false);
  const [selectedAuction, setSelectedAuction] = useState(null);

  const [activeSidebar, setActiveSidebar] = useState(null); // 'teams' or 'stats'
  const [editingPlayerField, setEditingPlayerField] = useState(null); // field name like 'name', 'role', etc.
  const [editingTeamId, setEditingTeamId] = useState(null);
  const [editingShortId, setEditingShortId] = useState(null);
  const [tempValue, setTempValue] = useState("");
  const [tempShort, setTempShort] = useState("");
  const [bidIncrement, setBidIncrement] = useState(100); // Default to 100, updated on player change
  const [socket, setSocket] = useState(null);
  const [showBreakModal, setShowBreakModal] = useState(false);
  const [showImageEditor, setShowImageEditor] = useState(false);
  const [showRoundTransition, setShowRoundTransition] = useState(null); // { label, subtitle }
  const [result, setResult] = useState(null); // Result Overlay State
  const [searchAppId, setSearchAppId] = useState("");
  const [isCapturing, setIsCapturing] = useState(false);

  // Smart bid increment logic based on current tournament rules
  const getBidIncrement = (currentBid) => {
    // If we have custom increments from the database, use them
    if (rules.increments && rules.increments.length > 0) {
      const band = rules.increments.find((b) =>
      currentBid >= b.min && (b.max === null || currentBid < b.max)
      );
      if (band) return band.step;
    }

    // Fallback defaults if no rules defined
    if (isPointsSystem()) {
      if (currentBid < 10) return 1;
      if (currentBid < 20) return 2;
      if (currentBid < 50) return 5;
      return 10;
    }
    return 100; // Standard money increment
  };

  // Base price logic based on current tournament rules
  const getBasePrice = (role) => {
    // If we have role-based base prices in rules, use them
    if (rules.basePrice) {
      const r = role?.toLowerCase() || "";
      if (r.includes('batsman')) return rules.basePrice.batsman || 2;
      if (r.includes('bowler')) return rules.basePrice.bowler || 2;
      if (r.includes('all')) return rules.basePrice.allRounder || 4;
    }

    // Fallback defaults
    if (isPointsSystem()) {
      if (role?.toLowerCase().includes('all')) return 4;
      return 2;
    }
    return 100; // Standard money base price
  };

  // Squad size rules from tournament config
  const getSquadLimits = () => {
    return {
      minPlayers: selectedAuction?.squad?.minPlayers || 1,
      maxPlayers: selectedAuction?.squad?.maxPlayers || selectedAuction?.squadSize || 15
    };
  };

  // Check if team can bid (budget + squad size + year distribution)
  const canTeamBid = (team) => {
    const limits = getSquadLimits();
    const currentSquadSize = team.players?.length || 0;

    // Protection logic for mandatory minimum
    const mandatoryMin = limits.maxPlayers; // Treat setting as mandatory target
    const remainingMandatory = Math.max(0, mandatoryMin - currentSquadSize);

    const minPlayerPrice = isPointsSystem() ? rules.minBid || 1 : 100;
    const reserveNeeded = Math.max(0, (remainingMandatory - 1) * minPlayerPrice);
    const maxAllowedBid = team.remainingBudget - reserveNeeded;

    // Next bid must be at most maxAllowedBid
    const nextBid = currentBid === 0 ? player?.basePrice || minPlayerPrice : currentBid + getBidIncrement(currentBid);

    return maxAllowedBid >= nextBid;
  };

  // Get bid restriction reason
  const getBidRestrictionReason = (team) => {
    const limits = getSquadLimits();
    const currentSquadSize = team.players?.length || 0;
    const mandatoryMin = limits.maxPlayers;
    const remainingMandatory = Math.max(0, mandatoryMin - currentSquadSize);

    const minPlayerPrice = isPointsSystem() ? rules.minBid || 1 : 100;
    const reserveNeeded = Math.max(0, (remainingMandatory - 1) * minPlayerPrice);
    const maxAllowedBid = team.remainingBudget - reserveNeeded;

    const nextBid = currentBid === 0 ? player?.basePrice || minPlayerPrice : currentBid + getBidIncrement(currentBid);

    if (maxAllowedBid < nextBid) {
      if (team.remainingBudget < nextBid) {
        return `Insufficient Purse (${formatCurrencyText(team.remainingBudget)})`;
      }
      return `Purse Reserve Needed for ${remainingMandatory - 1} more mandatory slots`;
    }

    return null;
  };

  // Categorize team players by role
  const categorizeTeamPlayers = (team) => {
    const players = team.players || [];
    return {
      captain: players.find((p) => p.iconRole === 'captain'),
      viceCaptain: players.find((p) => p.iconRole === 'viceCaptain'),
      retained: players.filter((p) => p.iconRole === 'retained'),
      auctioned: players.filter((p) => !p.iconRole || p.iconRole === 'auction')
    };
  };

  // Get player role display with badge
  const getPlayerRoleBadge = (player) => {
    if (player.iconRole === 'captain') {
      return <span className="px-2 py-0.5 bg-amber-500 text-black text-[8px] font-black rounded-full">C</span>;
    }
    if (player.iconRole === 'viceCaptain') {
      return <span className="px-2 py-0.5 bg-slate-400 text-black text-[8px] font-black rounded-full">VC</span>;
    }
    if (player.iconRole === 'retained') {
      return <span className="px-2 py-0.5 bg-emerald-500 text-white text-[8px] font-black rounded-full">R</span>;
    }
    return null;
  };

  const formatDOB = (dob) => {
    if (!dob || dob === "-" || dob === "undefined") return "-";
    try {
      // If it's already in DD/MM/YYYY or similar, try to return it or fix it
      if (typeof dob === 'string' && dob.includes('/') && dob.length <= 10) return dob;

      const date = new Date(dob);
      if (isNaN(date.getTime())) return dob;

      const day = String(date.getDate()).padStart(2, '0');
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const year = date.getFullYear();
      return `${day}/${month}/${year}`;
    } catch {
      return dob;
    }
  };

  // Detect auction type based on tournament mode (Reliable vs baseline heuristic)
  const isPointsSystem = () => {
    return selectedAuction?.auctionMode === "points" || config.auctionMode === "points";
  };

  const getCurrencyUnit = () => {
    return selectedAuction?.currencyUnit || config.currencyUnit || "₹";
  };

  // For text-only context (alerts, confirms, console)
  const formatCurrencyText = (amount, options = {}) => {
    if (amount === undefined || amount === null) amount = 0;
    const { showSymbol = true, abbreviate = false } = options;
    const unit = getCurrencyUnit();
    const formattedAmount = abbreviate && amount >= 1000 ?
    `${(amount / 1000).toFixed(1)}K` :
    Number(amount).toLocaleString('en-IN');

    if (!showSymbol) return formattedAmount;
    if (unit === "₹") return `₹${formattedAmount}`;
    return `${formattedAmount} ${unit}`;
  };

  // For UI context (returns JSX with stylized symbols)
  const formatCurrency = (amount, options = {}) => {
    if (amount === undefined || amount === null) amount = 0;
    const { showSymbol = true, abbreviate = false, className = "" } = options;
    const unit = getCurrencyUnit();
    const formattedAmount = abbreviate && amount >= 1000 ?
    `${(amount / 1000).toFixed(1)}K` :
    Number(amount).toLocaleString('en-IN');

    if (!showSymbol) return formattedAmount;

    return (
      <span className={`inline-flex items-center gap-1 whitespace-nowrap ${className}`}>
        {unit === "₹" && <CurrencySymbol unit={unit} />}
        <span>{formattedAmount}</span>
        {unit !== "₹" && <CurrencySymbol unit={unit} />}
      </span>);

  };

  const normalizeYearCategory = (player) => {
    if (!player) return "N/A";
    return player.year || player.category || "N/A";
  };

  const getYearDistribution = (team) => {
    if (!team) return {};

    if (team.yearDistribution && typeof team.yearDistribution === "object") {
      return team.yearDistribution;
    }

    const distribution = {};
    (team.players || []).forEach((teamPlayer) => {
      const year = normalizeYearCategory(teamPlayer);
      distribution[year] = (distribution[year] || 0) + 1;
    });

    return distribution;
  };

  const getImgUrl = (p) => {
    if (!p) return DEFAULT_ASSETS.DEFAULT_PLAYER;
    const url = p.photo?.s3 || p.photo?.drive || p.imageUrl || p.image;
    if (!url) return getMediaUrl(`https://ui-avatars.com/api/?name=${encodeURIComponent(p.name)}&background=random&color=fff`);
    return getMediaUrl(url, DEFAULT_ASSETS.DEFAULT_PLAYER);
  };

  // Get base price based on auction type
  const getBasePriceByAuctionType = (role) => {
    if (isPointsSystem()) {
      // Points System: Role-based pricing (2/4 CR)
      return getBasePrice(role);
    } else {
      // Regular Auction: Use existing basePrice or default 100
      return 100; // Default for regular auctions
    }
  };

  // Edge Case 1: Debounce / Cooldown
  const BID_COOLDOWN = 600;

  // ALL useEffect HOOKS MUST ALSO BE CALLED BEFORE CONDITIONAL RETURNS
  // Redirect non-admin users (only once session is resolved)
  useEffect(() => {
    if (status === "loading") return;
    if (!session || session.user?.role !== "admin") {
      router.push("/auctions");
    }
  }, [session, status, router]);

  // Safety timeout — if data never loads, stop spinning after 12s
  useEffect(() => {
    const t = setTimeout(() => setLoading(false), 12000);
    return () => clearTimeout(t);
  }, []);

  const handleSendToPool = async (team, pool) => {
    const teamId = team.id || team._id;
    const isPoolA = pool === 'poolA';

    // Check if already in THIS pool (Toggle off)
    const isInThisPool = (isPoolA ? poolA : poolB).includes(teamId);

    let updatedPoolA = [...poolA];
    let updatedPoolB = [...poolB];

    const maxTeams = config.totalTeams > 0 ? Math.ceil(config.totalTeams / 2) : 10;

    if (isInThisPool) {
      // REMOVE from pool
      if (isPoolA) updatedPoolA = poolA.filter((id) => id !== teamId);else
      updatedPoolB = poolB.filter((id) => id !== teamId);
    } else {
      // ADD to pool (and remove from other pool if present)
      updatedPoolA = poolA.filter((id) => id !== teamId);
      updatedPoolB = poolB.filter((id) => id !== teamId);

      const targetPoolList = isPoolA ? updatedPoolA : updatedPoolB;
      if (targetPoolList.length >= maxTeams) {
        alert(`Pool ${isPoolA ? 'A' : 'B'} is full! (Limit: ${maxTeams} teams)`);
        return;
      }

      if (isPoolA) updatedPoolA.push(teamId);else
      updatedPoolB.push(teamId);
    }

    // OPTIMISTIC UPDATE
    const previousPoolA = [...poolA];
    const previousPoolB = [...poolB];

    // 1. Update local state immediately
    setPoolA(updatedPoolA);
    setPoolB(updatedPoolB);

    if (!isInThisPool) {
      setLastAssignment({ teamId: teamId, pool: isPoolA ? 'poolA' : 'poolB' });
    }

    // 2. Broadcast immediately so overlay starts animating without waiting for DB
    if (socket) {
      socket.emit('teamDrawEvent', {
        team: { id: teamId, name: team.name, logoUrl: team.logoUrl },
        pool: isPoolA ? 'poolA' : 'poolB'
      });
    }

    // 3. Perform background DB update
    try {
      const tournamentIdToUpdate = selectedAuction?._id || currentTournamentId;
      if (!tournamentIdToUpdate) throw new Error("No active tournament ID found");

      const res = await fetch(`${API_URL}/api/tournaments/${tournamentIdToUpdate}/pools`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ poolA: updatedPoolA, poolB: updatedPoolB })
      });

      if (!res.ok) throw new Error("Update failed");
    } catch (err) {
      // Rollback on failure
      console.error("Pool assignment error:", err);
      setPoolA(previousPoolA);
      setPoolB(previousPoolB);
      setLastAssignment(null);
      alert(`Pool assignment failed: ${err.message}. Please retry.`);
    }
  };

  const handleUndoPoolAssignment = async () => {
    if (!lastAssignment) return;
    if (!confirm("Undo last pool assignment?")) return;
    try {
      const { teamId, pool } = lastAssignment;
      const updatedPoolA = pool === 'poolA' ? poolA.filter((id) => id !== teamId) : poolA;
      const updatedPoolB = pool === 'poolB' ? poolB.filter((id) => id !== teamId) : poolB;
      const res = await fetch(`${API_URL}/api/tournaments/${selectedAuction?._id || currentTournamentId}/pools`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ poolA: updatedPoolA, poolB: updatedPoolB })
      });
      if (res.ok) {
        setPoolA(updatedPoolA);
        setPoolB(updatedPoolB);
        setLastAssignment(null);
        if (socket) socket.emit('auctionUpdate', { type: 'system_refresh', auctionId: selectedAuction?._id || currentTournamentId });
      }
    } catch (err) {alert("Undo failed");}
  };

  const handleResetPools = async () => {
    if (!confirm("Reset ALL pool assignments? This cannot be undone.")) return;
    try {
      const res = await fetch(`${API_URL}/api/tournaments/${selectedAuction?._id || currentTournamentId}/pools`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ poolA: [], poolB: [] })
      });
      if (res.ok) {
        setPoolA([]);
        setPoolB([]);
        setLastAssignment(null);
        if (socket) socket.emit('resetPoolsDraw', {});
      }
    } catch (err) {alert("Reset failed");}
  };

  const downloadPoolsPoster = async () => {
    setIsCapturing(true);
    // Give a moment for the DOM to render the poster template if it was hidden
    setTimeout(async () => {
      const element = document.getElementById("pools-poster-template");
      if (!element) {
        setIsCapturing(false);
        return;
      }
      try {
        const canvas = await html2canvas(element, {
          useCORS: true,
          scale: 2,
          backgroundColor: '#0a0f18'
        });
        const link = document.createElement('a');
        link.download = `${config.name.replace(/\s+/g, '_')}_Pools_Draw.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
      } catch (err) {
        console.error("Poster generation failed:", err);
      } finally {
        setIsCapturing(false);
      }
    }, 500);
  };

  const togglePoolView = () => {
    const newState = !showPoolView;
    setShowPoolView(newState);
    if (socket) socket.emit('togglePoolView', { show: newState });
  };


  // Socket connection setup - uses global socket to survive React dev re-renders
  useEffect(() => {
    // Determine the correct socket URL
    const socketUrl = API_URL || (typeof window !== 'undefined' ? window.location.origin : "");

    if (!socketUrl && typeof window === 'undefined') return;

    // Use existing global socket if available to prevent multiple connections in dev
    if (globalSocket && globalSocket.connected) {
      console.log('🔌 Using existing global socket connection');
      setSocket(globalSocket);
      return;
    }

    console.log('🔌 Initializing new socket connection to:', socketUrl);

    const s = io(socketUrl, {
      transports: ['websocket', 'polling'],
      timeout: 20000,
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionAttempts: 10,
      forceNew: false // Allow reusing connection if possible
    });

    globalSocket = s;
    setSocket(s);

    s.on('connect', () => {
      console.log('✅ Socket connected successfully. ID:', s.id);
    });

    s.on('disconnect', (reason) => {
      console.log('⚠️ Socket disconnected. Reason:', reason);
      if (reason === 'io server disconnect') {
        s.connect();
      }
    });

    s.on('connect_error', (error) => {
      console.error('❌ Socket connection error:', error.message);
      // If direct connection fails and we were using a full URL, maybe try relative as fallback?
      // But for now, we just log it clearly.
    });

    s.on('playerUpdate', (data) => {
      console.log('📡 Player update received:', data.id);
      setPlayers((prev) => prev.map((p) => p._id === data.id || p.id === data.id ? { ...p, ...data } : p));
    });

    // Cleanup: We keep the globalSocket alive in development
    return () => {
      // In production, we might want to disconnect, but in dev it causes issues with HMR
      if (process.env.NODE_ENV === 'production') {
        s.disconnect();
        globalSocket = null;
      }
    };
  }, []);

  // Tournament validation
  useEffect(() => {
    const fetchTournament = async () => {
      try {
        let targetTournamentId = tournamentId;

        const controller = new AbortController();
        const abortTimer = setTimeout(() => controller.abort(), 30000);

        let data = null;

        // If a tournament ID is in the URL, try it first
        if (targetTournamentId) {
          const res = await fetch(`${API_URL}/api/tournaments/${targetTournamentId}`, { signal: controller.signal });
          if (res.ok) {
            const json = await res.json();
            if (json && json.tournament) {
              data = json;
              setCurrentTournamentId(targetTournamentId);
            }
          } else {
            console.warn(`Tournament ID "${targetTournamentId}" not found (${res.status}), falling back to active tournament...`);
          }
        }

        // Fallback: fetch active tournament if URL id was missing or invalid
        if (!data) {
          const activeRes = await fetch(`${API_URL}/api/tournaments/status/active`, { signal: controller.signal });
          if (activeRes.ok) {
            const activeData = await activeRes.json();
            if (activeData && activeData.tournament) {
              data = activeData;
              targetTournamentId = activeData.tournament._id;
              setCurrentTournamentId(targetTournamentId);
              console.log('Loaded active tournament:', targetTournamentId);
            }
          }
        }

        clearTimeout(abortTimer);

        if (!data || !data.tournament) throw new Error("No active tournament found");

        const tournament = data.tournament;
        setConfig({
          name: tournament.name,
          baseBudget: tournament.baseBudget,
          totalTeams: tournament.numTeams,
          auctionMode: tournament.auctionMode || "money",
          iconsPerTeam: tournament.iconsPerTeam || 2
        });

        // Load custom rules
        if (data.rules) {
          setRules(data.rules);
        }

        // Apply Dynamic Assets if they exist
        if (tournament.assets) {
          setActiveAssets((prev) => ({
            ...prev,
            splashUrl: tournament.assets.splashUrl || "",
            logoUrl: tournament.assets.logoUrl || "",
            backgroundUrl: tournament.assets.backgroundUrl || "https://auction-platform-kp.s3.ap-south-1.amazonaws.com/banners/1777801051801.png",
            badges: tournament.assets.badges || { leftBadge: "", rightBadge: "" }
          }));
          if (tournament.assets.backgroundUrl) setAuctionBg(tournament.assets.backgroundUrl);
        }

        // Logic for auto-assigning unique shortcuts based on team names
        const usedShortcuts = new Set();
        const sortedDataTeams = [...data.teams].sort((a, b) => (a.name || '').localeCompare(b.name || ''));
        const mappedTeams = sortedDataTeams.map((t, i) => {
          let shortcut = t.shortcut;

          // If no shortcut from DB, try to find a unique letter from the name
          if (!shortcut) {
            const cleanName = t.name.toLowerCase().replace(/[^a-z0-9]/g, '');
            for (let j = 0; j < cleanName.length; j++) {
              const char = cleanName[j];
              if (!usedShortcuts.has(char)) {
                shortcut = char;
                break;
              }
            }
          }

          // If still no unique shortcut, fallback to number (i+1) if not taken
          if (!shortcut) {
            const fallback = (i + 1).toString();
            shortcut = usedShortcuts.has(fallback) ? null : fallback;
          }

          if (shortcut) usedShortcuts.add(shortcut.toLowerCase());

          return {
            id: t._id,
            name: t.name,
            shortName: t.shortName || t.name,
            logoUrl: t.logoUrl || getMediaUrl(`https://ui-avatars.com/api/?name=${encodeURIComponent(t.name)}&background=random`),
            totalBudget: data.tournament.baseBudget,
            remainingBudget: t.remainingBudget,
            players: (() => {
              const teamPlayers = data.players.filter((p) => String(p.team) === String(t._id) || p.team === t.name);
              const unique = [];
              const seen = new Set();
              teamPlayers.forEach((p) => {
                const id = p._id || p.id;
                const nameKey = p.name?.toLowerCase().trim();
                if (!seen.has(id) && !seen.has(nameKey)) {
                  if (id) seen.add(id);
                  if (nameKey) seen.add(nameKey);
                  unique.push(p);
                }
              });
              return unique;
            })(),
            color: t.color || "bg-blue-600",
            shortcut: shortcut || (i + 1).toString()
          };
        });

        setTeams(mappedTeams);

        // DEBUG: Log player data
        console.log('🔍 DEBUG - Total players from API:', data.players.length);
        console.log('🔍 DEBUG - Players with isIcon=true:', data.players.filter((p) => p.isIcon).length);
        console.log('🔍 DEBUG - Players with isIcon=false:', data.players.filter((p) => !p.isIcon).length);
        console.log('🔍 DEBUG - Sample player data:', data.players.slice(0, 3));

        // Filter: Keep non-icon players (auction players only) - FIXED for points system
        let auctionPlayers = data.players.filter((p) => !p.isIcon);

        // If no players after filtering, try including all players (points system fix)
        if (auctionPlayers.length === 0) {
          auctionPlayers = data.players;
        }

        console.log('🎯 FINAL - Auction players count:', auctionPlayers.length);

        // Create auction-only Application IDs
        const baseEnriched = auctionPlayers.map((p) => {
          // DEBUG: Log each player's base price and category
          const creditsBasePrice = getBasePrice(p.role);

          return {
            id: p._id,
            name: p.name,
            role: p.role || "All-Rounder",
            village: p.village || "-",
            dob: p.dob || "-",
            category: p.category, // CRITICAL: Include category field!
            year: p.year, // Include year field if available
            age: p.age || 20,
            town: p.town,
            image: p.imageUrl || p.image || getMediaUrl(`https://ui-avatars.com/api/?name=${encodeURIComponent(p.name)}&background=random`),
            placeholder: getMediaUrl(`https://ui-avatars.com/api/?name=${encodeURIComponent(p.name)}&background=random`),
            basePrice: p.basePrice || creditsBasePrice,
            soldPrice: p.soldPrice,
            team: p.team || null,
            status: p.status || "available",
            battingStyle: p.battingStyle || "Right Hand",
            bowlingStyle: p.bowlingStyle || "-",
            isIcon: p.isIcon || false,
            photo: p.photo || { s3: p.imageUrl || p.image || getMediaUrl(`https://ui-avatars.com/api/?name=${encodeURIComponent(p.name)}&background=random`) },
            applicationId: p.applicationId ? p.applicationId.toString().padStart(2, '0') : "-",
            _rawAppId: p.applicationId || 0
          };
        });

        // Round 02: Append UNSOLD players to the end of the list after a marker
        // Their Application IDs STAY THE SAME.
