                </p>
                
                <button onClick={() => setShowAddModal(true)} className="bg-[#008060] hover:bg-[#006e52] text-white font-bold text-sm tracking-wide py-3.5 px-8 rounded-xl w-full max-w-[280px] shadow-sm transition-colors uppercase">
