// ─────────────────────────────────────────────────────────────
// TEAM DETAILS MODAL COMPONENT
// ─────────────────────────────────────────────────────────────
function TeamDetailsModal({ team, players, tournament, onClose }) {
  const [isExporting, setIsExporting] = useState(false);

  const handleDownloadSquad = async () => {
    try {
      setIsExporting(true);

      const loadImage = (url) => {
        return new Promise((resolve) => {
          const proxyUrl = `${API_URL}/api/proxy-image?url=${encodeURIComponent(url)}`;
          const img = new (window.Image || Image)();
          img.crossOrigin = "anonymous";
          img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0);
            try {
              const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
              resolve(dataUrl);
            } catch (e) {
              resolve(null);
            }
          };
          img.onerror = () => resolve(null);
          img.src = proxyUrl;
        });
      };

      const doc = new jsPDF();

      // 1. STYLISH HEADER
      doc.setFillColor(15, 23, 42);
      doc.rect(0, 0, 210, 40, 'F');

      doc.setFontSize(28);
      doc.setTextColor(255, 255, 255);
      doc.setFont("helvetica", "bold");
      doc.text(`${team.name.toUpperCase()}`, 14, 25);

      doc.setFontSize(10);
      doc.setTextColor(148, 163, 184);
      doc.text(`OFFICIAL SQUAD ROSTER | ${tournament?.name || 'Tournament'}`, 14, 33);

      // 2. LOAD IMAGES ASYNC (Using Proxy)
      const squadToExport = players.slice(0, 35);
      const imageDataUrls = await Promise.all(squadToExport.map((p) => {
        const url = p.photo?.s3 || p.imageUrl || p.photo?.drive || `https://api.dicebear.com/7.x/avataaars/svg?seed=${encodeURIComponent(p.name)}`;
        return loadImage(url);
      }));

      // 3. GENERATE TABLE
      const tableData = squadToExport.map((p, index) => [
      index + 1,
      '',
      p.name.toUpperCase(),
      p.role.toUpperCase(),
      p.isIcon ? 'ICON' : `INR ${p.soldPrice?.toLocaleString('en-IN')}`]
      );

      autoTable(doc, {
        startY: 50,
        head: [['#', 'PLAYER', 'PLAYER NAME', 'ROLE', 'PRICE']],
        body: tableData,
        theme: 'grid',
        headStyles: {
          fillColor: [124, 58, 237],
          textColor: [255, 255, 255],
          fontStyle: 'bold',
          halign: 'center',
          fontSize: 10
        },
        columnStyles: {
          0: { halign: 'center', cellWidth: 12 },
          1: { halign: 'center', cellWidth: 25 }, // Expanded for "PLAYER" heading
          2: { halign: 'center' }, // Centered name
          3: { halign: 'center' }, // Centered role
          4: { halign: 'center', fontStyle: 'bold' } // Centered price
        },
        styles: {
          fontSize: 9,
          cellPadding: 4,
          valign: 'middle',
          overflow: 'linebreak'
        },
        alternateRowStyles: {
          fillColor: [248, 250, 252]
        },
        didDrawCell: (data) => {
          if (data.column.index === 1 && data.section === 'body') {
            const dataUrl = imageDataUrls[data.row.index];
            if (dataUrl) {
              const size = 26; // Much larger size
              const x = data.cell.x + (data.cell.width - size) / 2;
              const y = data.cell.y + (data.cell.height - size) / 2;
              doc.addImage(dataUrl, 'JPEG', x, y, size, size);
            } else {
              doc.setDrawColor(226, 232, 240);
              doc.circle(data.cell.x + data.cell.width / 2, data.cell.y + data.cell.height / 2, 8, 'S');
            }
          }
        },
        didParseCell: (data) => {
          if (data.section === 'body') {
            data.row.height = 30; // Increased row height to fit large photos
          }
        }
      });

      doc.save(`${team.name.replace(/\s+/g, '_')}_Official_Squad.pdf`);
    } catch (err) {
      console.error("PDF Export Error:", err);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-[#0a0f18]/95 backdrop-blur-3xl animate-in fade-in transition-all">
       <div className="bg-[#111827] border border-white/10 rounded-[3rem] w-full max-w-5xl h-[90vh] overflow-hidden shadow-2xl flex flex-col relative">

          <div className="absolute top-8 right-8 z-50 flex items-center gap-3">
             <button
            onClick={handleDownloadSquad}
            disabled={isExporting}
            className={`p-3 rounded-full transition-all border border-white/10 shadow-xl shadow-black/50 group flex items-center justify-center
                 ${isExporting ?
            'bg-emerald-500/20 text-emerald-400 cursor-not-allowed' :
            'bg-white/5 text-slate-400 hover:bg-emerald-500/20 hover:text-emerald-400'}`}
            title="Download Squad PDF">

               {isExporting ?
            <div className="w-5 h-5 border-2 border-emerald-400 border-t-transparent rounded-full animate-spin"></div> :

            <FileDown size={22} className="group-hover:scale-110 transition-transform" />
            }
             </button>
             <button
            onClick={onClose}
            className="p-3 bg-white/5 hover:bg-red-500/20 rounded-full text-slate-400 hover:text-red-400 transition-all border border-white/10 shadow-xl shadow-black/50">

               <X size={24} />
             </button>
          </div>

          <div className="p-10 border-b border-white/5 relative overflow-hidden bg-white/[0.01]">
             <div className="absolute top-0 right-10 opacity-5 pointer-events-none">
                <Users size={200} />
             </div>

             <div className="flex items-center gap-8 relative z-10">
                <div className="w-24 h-24 rounded-[2rem] bg-slate-900 border border-white/10 p-1.5 shadow-2xl">
                   <div className="w-full h-full rounded-[1.7rem] overflow-hidden bg-slate-800">
                      <img src={getMediaUrl(team.logoUrl, DEFAULT_ASSETS.DEFAULT_TEAM)} className="w-full h-full object-cover" alt="" />
                   </div>
                </div>
                <div>
                  <p className="text-[10px] font-black text-violet-500 uppercase tracking-[0.5em] mb-2 leading-none">Roster Intelligence</p>
                  <h2 className="text-5xl font-black text-white tracking-tighter uppercase italic">{team.name}</h2>
                  <div className="flex items-center gap-6 mt-4">
                     <div className="flex items-center gap-2 font-black text-xs uppercase tracking-wider text-slate-400">
                        Spent: <span className="text-emerald-400">₹{players.reduce((s, p) => s + (p.soldPrice || 0), 0).toLocaleString('en-IN')}</span>
                     </div>
                     <div className="flex items-center gap-2 font-black text-xs uppercase tracking-wider text-slate-400">
                        Purse: <span className="text-white">₹{((team.budget || tournament.baseBudget || 50000) - players.reduce((s, p) => s + (p.soldPrice || 0), 0)).toLocaleString('en-IN')}</span>
                     </div>
                  </div>
                </div>
             </div>
          </div>

          <div className="flex-1 flex flex-col md:flex-row overflow-hidden">

             <div className="w-full md:w-80 border-r border-white/5 bg-black/20 p-8 flex-shrink-0">
                <div className="space-y-8">
                   <div>
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Purse Usage</p>
                      <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden mb-2">
                         <div className="h-full bg-violet-600 rounded-full" style={{ width: `${players.reduce((s, p) => s + (p.soldPrice || 0), 0) / (team.budget || tournament.baseBudget || 50000) * 100}%` }}></div>
                      </div>
                      <p className="text-[10px] font-bold text-slate-600">{Math.round(players.reduce((s, p) => s + (p.soldPrice || 0), 0) / (team.budget || tournament.baseBudget || 50000) * 100)}% of budget utilized</p>
                   </div>

                   <div>
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Squad Balance</p>
                      <div className="space-y-2">
                         {['Batsman', 'Bowler', 'All-Rounder'].map((role) =>
                  <div key={role} className="flex items-center justify-between text-[11px] font-bold text-slate-400 bg-white/5 p-3 px-5 rounded-2xl border border-white/5">
                               <span>{role}</span>
                               <span className="text-white">{players.filter((p) => p.role?.toLowerCase() === role.toLowerCase()).length}</span>
                            </div>
                  )}
                      </div>
                   </div>
                </div>
             </div>

             <div className="flex-1 overflow-y-auto p-10 custom-scrollbar bg-slate-900/40">
                <div className="grid grid-cols-1 gap-3">
                   {players.length === 0 ?
              <div className="py-20 text-center opacity-30 italic font-medium">No players in squad.</div> :

              players.map((p, i) =>
              <div key={i} className="flex items-center gap-6 p-4 px-6 bg-slate-950/50 border border-white/5 rounded-[2rem] hover:border-violet-500/30 transition-all group">
                          <div className="w-14 h-14 rounded-2xl overflow-hidden border border-white/10 shrink-0 bg-slate-900 shadow-inner group-hover:scale-105 transition-transform">
                             <img src={getMediaUrl(p.imageUrl || p.photo?.s3 || p.photo?.drive, DEFAULT_ASSETS.DEFAULT_PLAYER)} className="w-full h-full object-cover" alt="" />
                          </div>

                          <div className="flex-1 min-w-0">
                             <p className="text-[9px] font-black text-violet-500 uppercase tracking-widest mb-0.5">{p.role}</p>
                             <h4 className="text-lg font-black text-white hover:text-violet-400 transition-colors uppercase italic truncate tracking-tight">{p.name}</h4>
                          </div>

                          <div className="flex flex-col items-end justify-center px-6">
                             <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-0.5">
                                {p.isIcon ? 'Designation' : 'Price'}
                             </p>
                             <p className={`text-lg font-black leading-none italic ${p.isIcon ? 'text-amber-400' : 'text-emerald-400'}`}>
                                {p.isIcon ? 'ICON' : `₹${p.soldPrice?.toLocaleString('en-IN')}`}
                             </p>
                          </div>

                          <button className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/5 transition-all">
                             <ChevronRight size={18} className="text-slate-600" />
                          </button>
                       </div>
              )
              }
                </div>
             </div>
          </div>
       </div>
    </div>);

}

"use client";
import { useEffect, useState } from "react";
import Link from "next/link";
import { useSession } from "next-auth/react";
import { API_URL, getMediaUrl } from "@/lib/apiConfig";
import { getCanonicalApplyRoute } from "@/lib/applicationRoutes";
import { Trophy, ArrowRight, Calendar, MapPin, Zap, Loader2 } from "lucide-react";

export default function ActiveTournaments() {
  const { data: session } = useSession();
  const [tournaments, setTournaments] = useState([]);
  const [loading, setLoading] = useState(true);
  const isAdmin = session?.user?.role === "admin";

  useEffect(() => {
    async function fetchTournaments() {
      try {
        const res = await fetch(`${API_URL}/api/tournaments`);
        const data = await res.json();

        // Safety check: Ensure data is an array
        if (!Array.isArray(data)) {
          console.error("Invalid data format for tournaments:", data);
          setTournaments([]);
          return;
        }

        // Filter for active or upcoming tournaments
        const active = data.filter(t => t.status === 'active' || t.status === 'upcoming' || t.status === 'live');
        // Sort by newest first
        active.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
        setTournaments(active.slice(0, 3)); // Show top 3
      } catch (err) {
        console.error("Failed to fetch tournaments:", err);
      } finally {
        setLoading(false);
      }
    }
    fetchTournaments();
  }, []);

  if (loading) return (
    <div className="py-20 bg-slate-950 flex flex-col items-center justify-center gap-4">
      <Loader2 className="w-8 h-8 text-violet-500 animate-spin" />
      <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Loading Arena...</p>
    </div>
  );

  if (tournaments.length === 0) return null;

  const isUrgent = (endDate, endTime) => {
    if (!endDate) return false;
    const end = new Date(`${endDate.split('T')[0]}T${endTime || '23:59'}`);
    const now = new Date();
    const diff = end - now;
    return diff > 0 && diff < 24 * 60 * 60 * 1000;
  };

  const isRegistrationClosed = (endDate, endTime) => {
    if (!endDate) return false;
    const end = new Date(`${endDate.split('T')[0]}T${endTime || '23:59'}`);
    return new Date() > end;
  };

  return (
    <section id="tournament-arena" className="py-24 bg-[#020617] relative overflow-hidden border-y border-white/5">
      {/* Background Glow */}
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-full bg-[radial-gradient(circle_at_center,rgba(124,58,237,0.05),transparent_70%)]"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <div className="text-center mb-16">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-violet-500/10 border border-violet-500/20 text-violet-400 text-[10px] font-black uppercase tracking-[0.2em] mb-4">
            <Trophy className="w-3 h-3" />
            Live & Upcoming Events
          </div>
          <h2 className="text-4xl md:text-6xl font-black text-white italic tracking-tighter">
            TOURNAMENT <span className="text-transparent bg-clip-text bg-linear-to-r from-violet-500 to-cyan-400">ARENA</span>
          </h2>
          <p className="mt-4 text-slate-500 font-bold uppercase tracking-[0.4em] text-[10px]">Join the most prestigious local cricket battles</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {tournaments.map((t) => {
            const urgent = isUrgent(t.registrationEndDate, t.registrationEndTime);
            const registrationClosed = isRegistrationClosed(t.registrationEndDate, t.registrationEndTime);
            return (
              <div key={t._id} className="group relative bg-slate-900/20 border border-white/5 rounded-[2.5rem] overflow-hidden hover:border-violet-500/30 transition-all duration-500 shadow-2xl hover:shadow-violet-600/10 flex flex-col">
                {/* Image Header */}
                <div className="h-56 relative overflow-hidden">
                  <img
                    src={getMediaUrl(t.assets?.splashUrl, "/tournaments/t1_v2.jpg")}
                    alt={t.name}
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                  />
                  <div className="absolute inset-0 bg-linear-to-t from-[#020617] via-[#020617]/20 to-transparent"></div>

                  {/* Status Badge */}
                  <div className="absolute top-6 left-6 flex gap-2">
                    <span className={`px-3 py-1.5 ${t.status === 'active' ? 'bg-emerald-600' : 'bg-violet-600'} text-white text-[9px] font-[1000] uppercase tracking-widest rounded-lg shadow-lg`}>
                      {t.status}
                    </span>
                    {t.registrationEndDate && (
                      <span className={`px-3 py-1.5 ${urgent ? 'bg-red-600 animate-pulse' : 'bg-black/60'} backdrop-blur-md text-white text-[9px] font-[1000] uppercase tracking-widest rounded-lg border border-white/10`}>
                        {registrationClosed ? 'Registration Closed' : urgent ? 'Closing Soon' : 'Registration Open'}
                      </span>
                    )}
                  </div>
                </div>

                {/* Content */}
                <div className="p-8 space-y-6 flex-1 flex flex-col">
                  <div className="flex-1">
                    <h3 className="text-2xl font-black text-white uppercase italic tracking-tight group-hover:text-violet-400 transition-colors leading-tight">{t.name}</h3>
                    <div className="flex items-center gap-3 mt-3 text-slate-400 font-bold text-[11px] uppercase tracking-wider">
                      <div className="w-8 h-8 rounded-lg bg-violet-600/20 flex items-center justify-center">
                        <MapPin className="w-4 h-4 text-violet-500" />
                      </div>
                      {t.organizerName || "Local Arena"}
                    </div>
                  </div>

                  <div className="space-y-4 pt-6 border-t border-white/5">
                    <div className="flex items-center justify-between">
                      <div className="flex flex-col">
                        <span className={`text-[9px] font-black uppercase tracking-widest ${urgent ? 'text-red-500' : 'text-slate-500'}`}>Registration Ends</span>
                        <span className={`text-xs font-black uppercase tracking-wider mt-1 ${urgent ? 'text-red-400' : 'text-white'}`}>
                          {(() => {
                            if (!t.registrationEndDate) return 'TBD';
                            const endDay = new Date(t.registrationEndDate);
                            const today = new Date();
                            today.setHours(0, 0, 0, 0);
                            endDay.setHours(0, 0, 0, 0);
                            const diffDays = Math.round((endDay - today) / (1000 * 60 * 60 * 24));
                            if (diffDays === 0) return <span className="text-red-500 animate-pulse font-black">Today</span>;
                            if (diffDays === 1) return <span className="text-yellow-500 font-black">Tomorrow</span>;
                            return endDay.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
                          })()}
                        </span>
                      </div>
                      <div className={`w-10 h-10 rounded-full border flex items-center justify-center ${urgent ? 'border-red-500/50 bg-red-500/10' : 'border-white/10'}`}>
                        <Calendar className={`w-4 h-4 ${urgent ? 'text-red-500' : 'text-slate-500'}`} />
                      </div>
                    </div>
                  </div>

                  <div className="flex flex-col gap-3 pt-2">
                    <Link
                      href={registrationClosed 
                        ? (isAdmin ? `/live-auction?id=${t.shortId || t._id}&role=admin` : "/overlay") 
                        : (t.applyToken ? getCanonicalApplyRoute(t.applyToken) : `/register/${t._id}`)}
                      className="w-full py-4.5 bg-linear-to-r from-violet-600 to-cyan-500 text-white rounded-2xl text-[10px] font-[1000] uppercase tracking-widest flex items-center justify-center gap-3 hover:brightness-110 hover:scale-[1.02] transition-all shadow-xl shadow-violet-600/20"
                    >
                      <Zap className="w-4 h-4" /> {registrationClosed ? (isAdmin ? "Start Auction" : "Watch Auction") : "Apply Now"}
                    </Link>
                    <Link
                      href="/auctions"
                      className="w-full py-4.5 bg-white/5 border border-white/10 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-white/10 hover:text-white transition-all"
                    >
                      Browse Auction <ArrowRight className="w-4 h-4" />
                    </Link>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Users, ClipboardList, Crosshair, X, ChevronRight, TrendingUp, Award, IndianRupee, User } from "lucide-react";
import { API_URL, getMediaUrl, DEFAULT_ASSETS, calculateAge } from "../lib/apiConfig";
import CurrencySymbol from "./CurrencySymbol";

// Design tokens
const C = {
  bgMain:   '#071821',
  bgCard:   '#0c2432',
  bgNav:    '#081c26',
  accent:   '#00d4a3',
  accentSoft: 'rgba(0, 212, 163, 0.15)',
  accentBorder: 'rgba(0, 212, 163, 0.25)',
  textPrimary: '#ffffff',
  textSecondary: '#9fb3c8',
  border: 'rgba(255,255,255,0.08)',
};

const getImgUrl = (p) => {
  if (!p) return DEFAULT_ASSETS.DEFAULT_PLAYER;
  const url = p.imageUrl || p.image || p.photo?.s3 || p.photo?.drive;
  if (!url) return getMediaUrl(`https://ui-avatars.com/api/?name=${encodeURIComponent(p.name)}&background=random&color=fff`);
  return getMediaUrl(url, DEFAULT_ASSETS.DEFAULT_PLAYER);
};

const formatCurrency = (val, unit = '₹') => {
  if (val === undefined || val === null) val = 0;
  const formattedAmount = Number(val).toLocaleString('en-IN');

  return (
    <span className="inline-flex items-center gap-1.5 whitespace-nowrap">
      {unit === '₹' && <IndianRupee className="w-[0.8em] h-[0.8em] stroke-[3px]" />}
      <span>{formattedAmount}</span>
      {unit !== '₹' && <CurrencySymbol unit={unit} className="scale-90 origin-left" />}
    </span>
  );
};

export default function AuctionOverlayNew({ 
  player, 
  nextPlayer,
  teams, 
  currentBid, 
  highestBidder, 
  highestBidderLogo, 
  tournamentName, 
  tournamentLogo,
  roundHistory,
  auctionResult,
  currencyUnit = '₹',
  iconsPerTeam = 2,
  maxSlots = 15
}) {
  const [focusMode, setFocusMode] = useState(false);
  const [windowWidth, setWindowWidth] = useState(typeof window !== 'undefined' ? window.innerWidth : 1200);
  const [squadModal, setSquadModal] = useState(null);
  const [activeBottomTab, setActiveBottomTab] = useState(null);
  const [lastShownPlayerId, setLastShownPlayerId] = useState(null);
  const [hasShownStatus, setHasShownStatus] = useState(false);
  const [isLoadingSquad, setIsLoadingSquad] = useState(false);
  const [showNextPill, setShowNextPill] = useState(false);
  const [allPlayers, setAllPlayers] = useState([]);
  const [isLoadingAllPlayers, setIsLoadingAllPlayers] = useState(false);
  const [playerFilter, setPlayerFilter] = useState('all');
  const [animatingPlayerCard, setAnimatingPlayerCard] = useState(null);

  const [lastShownNextName, setLastShownNextName] = useState(null);

  // Auto-pop Up Next Pill when nextPlayer changes
  useEffect(() => {
    if (nextPlayer?.name && nextPlayer.name !== lastShownNextName) {
      setShowNextPill(true);
      setLastShownNextName(nextPlayer.name);
      const timer = setTimeout(() => setShowNextPill(false), 7000); 
      return () => clearTimeout(timer);
    }

    if (!nextPlayer?.name && lastShownNextName) {
      setLastShownNextName(null);
    }
  }, [nextPlayer?.name, lastShownNextName]);

  useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (activeBottomTab === 'players' && allPlayers.length === 0) {
      const fetchAllPlayers = async () => {
        setIsLoadingAllPlayers(true);
        try {
          const response = await fetch(`${API_URL}/api/tournaments/status/active`);
          if (response.ok) {
            const data = await response.json();
            if (data.players) {
              setAllPlayers(data.players);
            }
          }
        } catch (error) {
          console.error('Failed to fetch all players:', error);
        } finally {
          setIsLoadingAllPlayers(false);
        }
      };
      fetchAllPlayers();
    }
  }, [activeBottomTab, allPlayers.length]);

  useEffect(() => {
    const teamId = squadModal?._id || squadModal?.id;
    if (!squadModal || !teamId) return;

    const fetchTeamPlayers = async () => {
      setIsLoadingSquad(true);
      try {
        const response = await fetch(`${API_URL}/api/teams/${teamId}`);
        if (response.ok) {
          const data = await response.json();
          const rawPlayers = data.squad || data.players || data.team?.players || [];
          const uniquePlayers = [];
          const seenIds = new Set();

          rawPlayers.forEach(p => {
            const id = p._id || p.id;
            const nameKey = p.name?.toLowerCase().trim();
            if (!seenIds.has(id) && !seenIds.has(nameKey)) {
              if (id) seenIds.add(id);
              if (nameKey) seenIds.add(nameKey);
              uniquePlayers.push(p);
            }
          });

          setSquadModal(prev => ({
            ...prev,
            players: uniquePlayers
          }));
        }
      } catch (error) {
        console.error('Failed to fetch team players:', error);
      } finally {
        setIsLoadingSquad(false);
      }
    };

    if (!squadModal.players || squadModal.players.length === 0) {
      fetchTeamPlayers();
    }
  }, [squadModal]);

  const isMobile = windowWidth < 768;

  const normalizedStatus = (player?.status || "").toString().trim().toLowerCase();
  const isSold = normalizedStatus === "sold";
  const isUnsold = normalizedStatus === "unsold";
  const bidAmount = Number(currentBid || 0);
  const baseAmount = Number(player?.basePrice || 0);
  const soldAmount = Number((player?.soldPrice ?? currentBid) || 0);
  const displayBid = isSold ? soldAmount : bidAmount > 0 ? bidAmount : baseAmount;

  useEffect(() => {
    if (!player) return;
    const playerId = player._id || player.name;
    if (playerId !== lastShownPlayerId) {
      setLastShownPlayerId(playerId);
      setHasShownStatus(false);
    }
    if (auctionResult && !hasShownStatus) {
      setHasShownStatus(true);
      const timer = setTimeout(() => {
        setHasShownStatus(false);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [player, auctionResult, lastShownPlayerId, hasShownStatus]);

  const highestBidderTeam = teams?.find(t => t._id === highestBidder || t.id === highestBidder);
  const highestBidderName = highestBidderTeam?.name || highestBidderTeam?.shortName || highestBidder;

  const handleBottomTab = (tab) => setActiveBottomTab(prev => prev === tab ? null : tab);

  const PlayerGridItem = ({ player, isIcon, idx }) => {
    const playerPrice = player.soldPrice || player.basePrice || 0;
    const isCaptain = player.iconRole === 'captain';
    const isViceCaptain = player.iconRole === 'viceCaptain';
    const isRetained = player.iconRole === 'retained';
    const hasRoleBadge = isCaptain || isViceCaptain || isRetained;

    let roleBadgeText = '';
    let roleBadgeColor = '';
    if (isCaptain) { roleBadgeText = 'C'; roleBadgeColor = '#f59e0b'; } 
    else if (isViceCaptain) { roleBadgeText = 'VC'; roleBadgeColor = '#3b82f6'; } 
    else if (isRetained) { roleBadgeText = 'R'; roleBadgeColor = '#10b981'; }

    const isClicked = squadModal.clickedPlayer?._id === (player._id || player.id);

    return (
      <div
        onClick={() => {
          setSquadModal(prev => ({ 
            ...prev, 
            clickedPlayer: prev.clickedPlayer?._id === (player._id || player.id) ? null : player 
          }));
          const modalBody = document.getElementById('squad-modal-body');
          if (modalBody) modalBody.scrollTo({ top: 0, behavior: 'smooth' });
        }}
        className="rounded-xl p-3 text-center relative overflow-hidden group transition-all hover:scale-[1.02] cursor-pointer"
        style={{ 
          background: isClicked ? C.accentSoft : C.bgMain, 
          border: `1px solid ${isClicked ? C.accent : C.border}`,
          boxShadow: isClicked ? `0 0 15px ${C.accentSoft}` : '0 4px 6px rgba(0,0,0,0.3)'
        }}
      >
        {hasRoleBadge && (
          <div className="absolute top-2 left-2 px-2 py-0.5 rounded-full text-[9px] font-black z-20 shadow-lg"
            style={{ background: roleBadgeColor, color: '#fff', boxShadow: `0 0 10px ${roleBadgeColor}80`, minWidth: '24px', textAlign: 'center' }}>
            {roleBadgeText}
          </div>
        )}
        <div className="w-16 h-16 rounded-full overflow-hidden mx-auto mb-2 border-2 mt-4" style={{ borderColor: C.accent }}>
          <img src={getImgUrl(player)} alt={player.name} className="w-full h-full object-cover" />
        </div>
        <p className="text-xs font-bold truncate mb-1" style={{ color: C.textPrimary }}>{player.name}</p>
        <p className="text-[10px] font-medium mb-1" style={{ color: C.textSecondary }}>{player.role}</p>
        <p className="text-sm font-black" style={{ color: C.accent }}>{formatCurrency(playerPrice, currencyUnit)}</p>
      </div>
    );
  };

  const SquadModal = () => !squadModal ? null : (
    <div className="fixed inset-0 z-50 flex items-end md:items-center justify-center" style={{ background: 'rgba(0,0,0,0.85)', backdropFilter: 'blur(12px)' }}
      onClick={() => { if (squadModal.__fromPlayers) setActiveBottomTab('players'); setSquadModal(null); }}>
      <div className="relative w-full md:max-w-2xl rounded-t-3xl md:rounded-3xl overflow-hidden shadow-2xl"
        style={{ background: C.bgCard, border: `2px solid ${C.accentBorder}`, maxHeight: '90vh', animation: 'modalSlideUp 0.3s ease-out' }}
        onClick={e => e.stopPropagation()}>
        <div className="px-6 py-5" style={{ borderBottom: `1px solid ${C.border}` }}>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4 flex-1">
              <div className="w-16 h-16 rounded-xl overflow-hidden bg-slate-800 flex-shrink-0 shadow-lg">
                {squadModal.logoUrl
                  ? <img src={getMediaUrl(squadModal.logoUrl, DEFAULT_ASSETS.DEFAULT_TEAM)} className="w-full h-full object-cover" alt="" />
                  : <div className="w-full h-full flex items-center justify-center"><Users size={24} color={C.textSecondary} /></div>
                }
              </div>
              <div className="flex-1 min-w-0">
                <h2 className="text-2xl font-black truncate" style={{ color: C.textPrimary }}>{squadModal.name || squadModal.shortName}</h2>
                <p className="text-sm mt-0.5" style={{ color: C.accent }}>Budget: {formatCurrency(squadModal.remainingBudget ?? squadModal.budget ?? 10000, currencyUnit)}</p>
                <p className="text-xs mt-0.5" style={{ color: C.textSecondary }}>{(squadModal.players || []).length} Players</p>
              </div>
            </div>
            <button onClick={() => { if (squadModal.__fromPlayers) setActiveBottomTab('players'); setSquadModal(null); }}
              className="p-2 rounded-lg transition-all hover:bg-black/60" style={{ background: 'rgba(0,0,0,0.4)', color: C.textSecondary }}>
              <X size={20} />
            </button>
          </div>
        </div>

        <div id="squad-modal-body" className="overflow-y-auto p-6 scroll-smooth" style={{ maxHeight: 'calc(90vh - 140px)' }}>
          {squadModal.clickedPlayer && squadModal.clickedPlayer.bidHistory && squadModal.clickedPlayer.bidHistory.length > 0 && (
            <div className="mb-6 p-4 rounded-2xl" style={{ background: C.bgMain, border: `1px solid ${C.accentBorder}` }}>
              <div className="flex items-center gap-3 mb-3 pb-3" style={{ borderBottom: `1px solid ${C.border}` }}>
                 <div className="w-12 h-12 rounded-full overflow-hidden border-2 bg-slate-800" style={{ borderColor: C.accent }}>
                    <img src={getImgUrl(squadModal.clickedPlayer)} className="w-full h-full object-cover" alt="" />
                 </div>
                 <div>
                   <p className="text-base font-black uppercase tracking-tight text-white">{squadModal.clickedPlayer.name}</p>
                   <p className="text-[10px] text-amber-400 uppercase font-bold tracking-[0.2em]">Full Bid History</p>
                 </div>
              </div>
              <div className="space-y-1.5 max-h-[180px] overflow-y-auto no-scrollbar pr-1">
                {[...squadModal.clickedPlayer.bidHistory].reverse().map((bid, idx) => (
                  <div key={idx} className="flex items-center justify-between p-2.5 rounded-lg transition-all" style={{ background: idx === 0 ? C.accentSoft : 'rgba(255,255,255,0.03)', border: `1px solid ${idx === 0 ? C.accentBorder : 'rgba(255,255,255,0.05)'}` }}>
                    <div className="flex items-center gap-2">
                       <span className="text-xs font-bold" style={{ color: idx === 0 ? C.accent : C.textSecondary }}>#{squadModal.clickedPlayer.bidHistory.length - idx}</span>
                       <span className="text-xs font-bold text-white uppercase tracking-tight">{bid.teamName || 'Unknown Team'}</span>
                    </div>
                    <span className="text-sm font-black" style={{ color: idx === 0 ? C.accent : C.textPrimary }}>{formatCurrency(bid.bidAmount || bid.bid || 0, currencyUnit)}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {squadModal.squadImageUrl && (
            <div className="mb-6">
              <div className="relative rounded-2xl overflow-hidden shadow-xl" style={{ aspectRatio: '3/4', maxWidth: '400px', margin: '0 auto' }}>
                <img src={getMediaUrl(squadModal.squadImageUrl)} alt={`${squadModal.name} Squad`} className="w-full h-full object-cover" loading="lazy" />
              </div>
            </div>
          )}

          {!squadModal.squadImageUrl && (
            <div>
              {isLoadingSquad ? (
                <div className="py-12 text-center">
                  <div className="inline-block w-8 h-8 border-4 border-t-transparent rounded-full animate-spin" style={{ borderColor: C.accent, borderTopColor: 'transparent' }}></div>
                  <p className="text-sm mt-4" style={{ color: C.textSecondary }}>Loading squad...</p>
                </div>
              ) : squadModal.players && squadModal.players.length > 0 ? (
                (() => {
                  const unique = squadModal.players;
                  const displayIconsPerTeam = iconsPerTeam > 0 ? iconsPerTeam : 2;
                  const teamIcons = unique.filter(p => p.isIcon);
                  const soldPlayers = unique.filter(p => !p.isIcon);
                  const effectiveMaxSlots = Math.max(displayIconsPerTeam, teamIcons.length);

                  return (
                    <div className="space-y-8">
                      <div>
                        <div className="flex items-center justify-between mb-4 px-2">
                          <div className="flex flex-col">
                            <h3 className="text-[10px] font-black uppercase tracking-[0.2em]" style={{ color: C.accent }}>Icons / Retained</h3>
                            <p className="text-[8px] text-slate-500 font-bold uppercase mt-0.5">Assigned Elite Players</p>
                          </div>
                          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{teamIcons.length} / {effectiveMaxSlots} Slots</span>
                        </div>
                        {teamIcons.length > 0 ? (
                          <div className="grid grid-cols-2 gap-3">
                            {teamIcons.map((player, idx) => (
                              <PlayerGridItem key={player._id || idx} player={player} isIcon={true} idx={idx} />
                            ))}
                          </div>
                        ) : (
                          <div className="py-8 text-center border border-dashed border-white/5 rounded-2xl">
                            <p className="text-[10px] font-bold text-slate-600 uppercase tracking-widest">No icons assigned</p>
                          </div>
                        )}
                      </div>
                      <div>
