import { useState, useRef, useEffect } from "react"
import ReactCrop, { centerCrop, makeAspectCrop } from 'react-image-crop'
import 'react-image-crop/dist/ReactCrop.css'
import { X, Check, RotateCcw, ZoomIn, ZoomOut, Maximize2, Move } from "lucide-react"
import { uploadToS3 } from "../lib/uploadToS3"
import { API_URL } from "../lib/apiConfig"

export default function ImageCropperModal({ imageUrl, onSave, onClose, folder = "players", initialAspect = 3 / 4 }) {
  const [crop, setCrop] = useState()
  const [completedCrop, setCompletedCrop] = useState()
  const [scale, setScale] = useState(1)
  const [rotate, setRotate] = useState(0)
  const [aspect, setAspect] = useState(initialAspect)
  const [loading, setLoading] = useState(false)

  const imgRef = useRef(null)

  // Helper to create a centered crop box
  const centerAspectCrop = (mediaWidth, mediaHeight, aspect) => {
    return centerCrop(
      makeAspectCrop(
        {
          unit: '%',
          width: 100,
        },
        aspect,
        mediaWidth,
        mediaHeight
      ),
      mediaWidth,
      mediaHeight
    )
  }

  // Handle aspect ratio change
  useEffect(() => {
    if (imgRef.current && aspect) {
      const { width, height } = imgRef.current
      const newCrop = centerAspectCrop(width, height, aspect)
      setCrop(newCrop)
    } else if (imgRef.current && !aspect) {
      // Free crop: default to a large centered box
      const { width, height } = imgRef.current
      setCrop({
        unit: '%',
        width: 80,
        height: 80,
        x: 10,
        y: 10
      })
    }
  }, [aspect])

  // Determine the best source URL for CORS-safe loading
  const getSecureUrl = (rawUrl) => {
    if (!rawUrl) return ""
    if (rawUrl.startsWith("/") || rawUrl.startsWith("blob:")) return rawUrl

    let API = API_URL || ""
    if (API.endsWith("/")) API = API.slice(0, -1)

    return `${API}/api/proxy-image?url=${encodeURIComponent(rawUrl)}`
  }

  const safeUrl = getSecureUrl(imageUrl)

  function onImageLoad(e) {
    const { width, height } = e.currentTarget
    const initialCrop = centerAspectCrop(width, height, aspect)
    setCrop(initialCrop)
  }

  const handleSave = async () => {
    if (!completedCrop || !imgRef.current) return

    setLoading(true)
    try {
      const image = imgRef.current
      const canvas = document.createElement('canvas')
      const ctx = canvas.getContext('2d')

      const scaleX = image.naturalWidth / image.width
      const scaleY = image.naturalHeight / image.height

      const pixelRatio = window.devicePixelRatio || 1
      canvas.width = Math.floor(completedCrop.width * scaleX * pixelRatio)
      canvas.height = Math.floor(completedCrop.height * scaleY * pixelRatio)

      ctx.scale(pixelRatio, pixelRatio)
      ctx.imageSmoothingQuality = 'high'

      ctx.save()

      // Move to center of canvas for rotation/scale
      ctx.translate(canvas.width / (2 * pixelRatio), canvas.height / (2 * pixelRatio))
      ctx.rotate((rotate * Math.PI) / 180)
      ctx.scale(scale, scale)
      ctx.translate(-canvas.width / (2 * pixelRatio), -canvas.height / (2 * pixelRatio))

      ctx.drawImage(
        image,
        0,
        0,
        image.naturalWidth,
        image.naturalHeight,
        -completedCrop.x * scaleX,
        -completedCrop.y * scaleY,
        image.naturalWidth,
        image.naturalHeight
      )

      ctx.restore()

      const blob = await new Promise((resolve) => {
        canvas.toBlob(resolve, 'image/jpeg', 0.95)
      })

      const file = new File([blob], `cropped_${Date.now()}.jpg`, { type: 'image/jpeg' })
      const newUrl = await uploadToS3(file, folder)

      await onSave(newUrl)
      onClose()
    } catch (err) {
      console.error("Save failed:", err)
      alert("Failed to save cropped image: " + err.message)
    } finally {
      setLoading(false)
    }
  }

  const handleReset = () => {
    setScale(1)
    setRotate(0)
    if (imgRef.current) {
        const { width, height } = imgRef.current
        setCrop(centerAspectCrop(width, height, aspect))
    }
  }

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-2xl animate-in fade-in duration-500">
      <div className="relative w-full max-w-5xl bg-[#0a0f1d] border border-white/10 rounded-[2.5rem] shadow-[0_50px_100px_rgba(0,0,0,0.9)] flex flex-col overflow-hidden max-h-[95vh] animate-in zoom-in-95 duration-300">

        {/* Header - Compact Layout */}
        <div className="px-10 py-5 border-b border-white/5 flex items-center justify-between bg-white/[0.02] shrink-0">
          <div className="flex items-center gap-5">
             <div className="w-14 h-14 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-[1.25rem] flex items-center justify-center text-white shadow-xl shadow-violet-500/20">
                <Move className="w-7 h-7" />
             </div>
             <div>
               <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Image Editor</h2>
               <div className="flex items-center gap-2 mt-0.5">
                 <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                 <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Precision Crop & Align</p>
               </div>
             </div>
          </div>
          <button 
             onClick={onClose} 
             className="w-12 h-12 flex items-center justify-center bg-white/5 hover:bg-red-500/20 hover:text-red-500 rounded-2xl transition-all border border-white/5"
          >
             <X size={24} />
          </button>
        </div>

        {/* Main Editor Section - Centered and Spacious */}
        <div className="flex-1 min-h-0 p-8 flex flex-col items-center justify-center bg-[#050810] relative group">
          <div className="relative max-w-full max-h-full flex items-center justify-center transition-all duration-500 ease-out">
             <div className="absolute inset-0 bg-violet-500/5 blur-[100px] rounded-full"></div>

             <div className="relative rounded-3xl overflow-hidden border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.5)] bg-slate-900/40 p-2">
                <ReactCrop
                    crop={crop}
                    onChange={(c) => setCrop(c)}
                    onComplete={(c) => setCompletedCrop(c)}
                    aspect={aspect}
                    className="max-w-full max-h-full shadow-2xl"
                    ruleOfThirds
                  >
                    <img
                      ref={imgRef}
                      alt="Crop me"
                      src={safeUrl}
                      onLoad={onImageLoad}
                      style={{ 
                        transform: `scale(${scale}) rotate(${rotate}deg)`, 
                        maxWidth: '100%', 
                        maxHeight: 'calc(95vh - 350px)', 
                        width: 'auto', 
                        height: 'auto', 
                        display: 'block',
                        transition: 'transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)' 
                      }}
                      className="cursor-move"
                      crossOrigin="anonymous"
                    />
                  </ReactCrop>
             </div>
          </div>

          <div className="mt-8 flex items-center gap-3 px-6 py-2 bg-white/5 border border-white/5 rounded-full backdrop-blur-md opacity-60 group-hover:opacity-100 transition-opacity">
            <Move size={12} className="text-violet-400" />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Drag to Adjust Selection • Use Controls to Scale</p>
          </div>
        </div>

        {/* Improved Controls Footer */}
        <div className="px-10 py-6 border-t border-white/5 bg-[#0a0f1d] flex flex-wrap items-center justify-between gap-6 shrink-0">
          <div className="flex items-center gap-8">
             {/* Zoom Controls */}
             <div className="space-y-3">
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1 block">Magnification</span>
                <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 shadow-inner">
                    <button onClick={() => setScale(s => Math.max(0.1, s - 0.1))} className="p-3 hover:bg-white/5 rounded-xl text-slate-400 hover:text-violet-400 transition-all"><ZoomOut size={20} /></button>
                    <div className="w-16 flex items-center justify-center border-x border-white/5 mx-1">
                        <span className="text-xs font-black tabular-nums text-white">{(scale * 100).toFixed(0)}%</span>
                    </div>
                    <button onClick={() => setScale(s => Math.min(5, s + 0.1))} className="p-3 hover:bg-white/5 rounded-xl text-slate-400 hover:text-indigo-400 transition-all"><ZoomIn size={20} /></button>
                </div>
             </div>

             {/* Aspect Ratio Controls */}
             <div className="space-y-3">
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1 block">Crop Aspect Ratio</span>
                <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 shadow-inner gap-1">
                    {[
                        { label: '16:9', val: 16/9 },
                        { label: '4:3', val: 4/3 },
                        { label: '3:4', val: 3/4 },
                        { label: '1:1', val: 1 },
                        { label: 'Free', val: undefined }
                    ].map((r) => (
                        <button 
                            key={r.label}
                            onClick={() => setAspect(r.val)} 
                            className={`px-4 py-2.5 rounded-xl text-[10px] font-black transition-all ${aspect === r.val ? 'bg-violet-600 text-white shadow-lg shadow-violet-600/20' : 'text-slate-500 hover:text-slate-200 hover:bg-white/5'}`}
                        >
                            {r.label}
                        </button>
                    ))}
                </div>
             </div>

             {/* Utility Buttons */}
             <div className="space-y-3">
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest pl-1 block">Tools</span>
                <div className="flex gap-2">
                    <button onClick={() => setRotate(r => r + 90)} className="p-3 bg-white/5 hover:bg-white/10 text-slate-400 rounded-2xl border border-white/5 transition-all"><RotateCcw size={20} className="transform scale-x-[-1]" /></button>
                    <button onClick={handleReset} className="p-3 bg-white/5 hover:bg-white/10 text-slate-400 rounded-2xl border border-white/5 transition-all"><Maximize2 size={20} /></button>
                </div>
             </div>
          </div>

          <div className="flex items-center gap-4">
             <button 
                onClick={onClose} 
                className="px-8 py-4 bg-transparent hover:bg-white/5 text-slate-500 hover:text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all"
             >
                Discard
             </button>
             <button 
                onClick={handleSave} 
                disabled={loading || !completedCrop}
                className="px-10 py-4 bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 disabled:opacity-30 disabled:cursor-not-allowed text-white rounded-2xl font-black text-xs uppercase tracking-[0.25em] transition-all flex items-center gap-3 shadow-[0_20px_40px_rgba(124,58,237,0.3)] min-w-[200px] justify-center"
             >
                {loading ? <div className="w-5 h-5 border-3 border-white/20 border-t-white rounded-full animate-spin"></div> : <Check size={20} />}
                {loading ? "PROCESSING..." : "SAVE CHANGES"}
             </button>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client";

import React, { useState, useRef, useEffect, useCallback } from "react";
import ReactCrop, { centerCrop, makeAspectCrop } from "react-image-crop";
import "react-image-crop/dist/ReactCrop.css";
// face-api.js is lazy-loaded inside handleAutoCrop to reduce bundle size
import { X, Check, Upload, Square, Crop, RefreshCw, Camera, AlertCircle, Info, Image as ImageIcon, Sparkles, UserCircle, ZoomIn, ZoomOut, ShieldCheck, ShieldAlert, Scan, ExternalLink } from "lucide-react";
import { API_URL } from "../lib/apiConfig";

/**
 * ImageEditModal - Professionally Tuned UI with AI Proxy v2
 */
export default function ImageEditModal({ initialImage, onSave, onClose, title = "Edit Image" }) {
  const [image, setImage] = useState(null);
  const [readyForAI, setReadyForAI] = useState(false);
  const [isRestricted, setIsRestricted] = useState(false);
  const [crop, setCrop] = useState();
  const [completedCrop, setCompletedCrop] = useState(null);
  const [aspect, setAspect] = useState(3 / 4);
  const [loading, setLoading] = useState(false);
  const [imgLoaded, setImgLoaded] = useState(false);
  const [detecting, setDetecting] = useState(false);
  const [error, setError] = useState(false);
  const [zoomPercent, setZoomPercent] = useState(100);
  const [proxyStatus, setProxyStatus] = useState("idle"); // idle, pending, success, failed

  // Cinematic Animation States
  const [isScanning, setIsScanning] = useState(false);
  const [scanStatus, setScanStatus] = useState("");
  const [imageScale, setImageScale] = useState(1);
  const [showCropBox, setShowCropBox] = useState(true);

  const imgRef = useRef(null);

  // ── Advanced Security Cleansing Layer ──
  useEffect(() => {
    if (!initialImage) return;

    if (initialImage.startsWith('data:') || initialImage.startsWith('blob:')) {
      setImage(initialImage);
      setReadyForAI(true);
      setProxyStatus("success");
      return;
    }

    setReadyForAI(false);
    setIsRestricted(false);
    setProxyStatus("pending");

    const prepareImage = async () => {
      try {
        const proxyUrl = `${API_URL}/api/proxy-image?url=${encodeURIComponent(initialImage)}`;

        // Fetch with security clearing headers
        const response = await fetch(proxyUrl, {
          method: 'GET',
          cache: 'no-cache'
        });

        if (!response.ok) throw new Error(`Proxy Gate Error: ${response.status}`);

        const blob = await response.blob();
        if (blob.size < 100) throw new Error("Invalid image blob received");

        const localUrl = URL.createObjectURL(blob);
        setImage(localUrl);
        setReadyForAI(true);
        setIsRestricted(false);
        setProxyStatus("success");
      } catch (err) {
        console.error("Security Engine Detail:", err);
        // Fallback: direct load (Restrictive Mode)
        setImage(initialImage);
        setReadyForAI(false);
        setIsRestricted(true);
        setProxyStatus("failed");
      }
    };

    prepareImage();
  }, [initialImage]);

  const onImageLoad = useCallback((e) => {
    const { width, height } = e.currentTarget;
    setImgLoaded(true);
    setError(false);

    // Default 80% Passport Frame
    const initialCrop = centerCrop(
      makeAspectCrop({ unit: "%", height: 80 }, 3 / 4, width, height),
      width,
      height
    );
    initialCrop.y = 5;
    setCrop(initialCrop);

    if (readyForAI) handleAutoCrop(e.currentTarget);
  }, [readyForAI]);

  const handleAutoCrop = async (targetImg) => {
    if (!targetImg || !readyForAI) return;

    // 🎭 START CINEMATIC SEQUENCE 🎭
    setDetecting(true);
    setIsScanning(true);
    setScanStatus("Analyzing topology...");
    setImageScale(0.96); // Step 1: Prep zoom out
    setShowCropBox(false); // Hide crop temporarily for focus move

    try {
      const faceapi = await import("face-api.js");
      const MODEL_URL = "https://justadudewhohacks.github.io/face-api.js/models";
      if (!faceapi.nets.tinyFaceDetector.params) await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);

      const detections = await faceapi.detectAllFaces(targetImg, new faceapi.TinyFaceDetectorOptions());

      // Artificial delay for "Thinking" feel (0.8s)
      await new Promise(r => setTimeout(r, 800));

      if (detections.length > 0) {
        setScanStatus("FACE DETECTED ✅");

        const face = detections.sort((a, b) => b.box.width - a.box.width)[0].box;
        const { width: imgW, height: imgH } = targetImg;
        const targetAspect = 3 / 4;

        let cropHeight = face.height * 2.8;
        let cropWidth = cropHeight * targetAspect;
        if (cropWidth > imgW) {
          cropWidth = imgW * 0.95;
          cropHeight = cropWidth / targetAspect;
        }

        let centerX = face.x + face.width / 2;
        let centerY = face.y + face.height / 2;
        let cropX = Math.max(0, Math.min(imgW - cropWidth, centerX - cropWidth / 2));
        let cropY = Math.max(0, Math.min(imgH - cropHeight, centerY - cropHeight / 2 - (face.height * 0.45)));

        // Step 2: Smooth transition to face
        setImageScale(1.04); // Zoom into face
        setCrop({
          unit: '%',
          x: (cropX / imgW) * 100,
          y: (cropY / imgH) * 100,
          width: (cropWidth / imgW) * 100,
          height: (cropHeight / imgH) * 100
        });

        // Step 3: Soft crop box entry after zoom
        setTimeout(() => {
          setIsScanning(false);
          setShowCropBox(true);
        }, 600);
      } else {
        setScanStatus("No Face Found");
        setTimeout(() => {
          setIsScanning(false);
          setShowCropBox(true);
          setImageScale(1);
        }, 1000);
      }
    } catch (e) {
      console.warn("AI System Busy", e);
      setIsScanning(false);
      setShowCropBox(true);
      setImageScale(1);
    } finally {
      setDetecting(false);
    }
  };

  const handleSave = async () => {
    if (completedCrop && completedCrop.width > 3 && completedCrop.height > 3) {
      setLoading(true);
      try {
        const blob = await getCroppedImg(imgRef.current, completedCrop);
        const file = new File([blob], `edit_${Date.now()}.jpg`, { type: "image/jpeg" });
        await onSave(file);
        onClose();
      } catch (e) {
        console.error("Finalization error:", e);
        if (isRestricted) {
          alert("Security Lock: This external photo source is strictly protected. \n\nPlease click 'Load Local File' and upload the photo from your device to use the AI Fit or save features.");
        } else {
          alert("Process Error. Please try again.");
        }
      } finally {
        setLoading(false);
      }
    } else {
      onClose();
    }
  };

  const getCroppedImg = async (image, crop) => {
    const canvas = document.createElement("canvas");
    const scaleX = image.naturalWidth / image.width;
    const scaleY = image.naturalHeight / image.height;
    canvas.width = crop.width * scaleX;
    canvas.height = crop.height * scaleY;
    const ctx = canvas.getContext("2d");
    if (!ctx) return null;
    ctx.drawImage(image, crop.x * scaleX, crop.y * scaleY, crop.width * scaleX, crop.height * scaleY, 0, 0, canvas.width, canvas.height);
    return new Promise((resolve, reject) => {
      try { canvas.toBlob(b => b ? resolve(b) : reject('Blob error'), "image/jpeg", 0.95); }
      catch (e) { reject(e); }
    });
  };

  return (
    <>
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-[#020617]/98 backdrop-blur-3xl" onClick={onClose} />

        <div className="relative w-full max-w-5xl bg-[#0B0F2A] border border-white/10 rounded-[2.5rem] overflow-hidden shadow-[0_0_100px_rgba(0,0,0,0.8)] flex flex-col max-h-[92vh] animate-in fade-in zoom-in-95 duration-500">

          {/* Header */}
          <div className="relative z-10 px-8 py-5 flex items-center justify-between border-b border-white/5 bg-white/[0.01]">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-violet-600 to-indigo-600 flex items-center justify-center text-white shadow-lg">
                <Camera className="w-6 h-6" />
              </div>
              <div>
                <h3 className="text-xl font-black text-white tracking-tight">{title}</h3>
                <div className="flex items-center gap-3 mt-1">
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] opacity-60">AI Smart Studio v2</p>
                  {proxyStatus === "pending" && <span className="text-[8px] bg-sky-500/20 text-sky-400 px-2 py-0.5 rounded font-black uppercase tracking-widest animate-pulse">Syncing...</span>}
                  {proxyStatus === "success" && <span className="flex items-center gap-1.5 text-[8px] bg-emerald-500/20 text-emerald-400 px-2 py-0.5 rounded font-black uppercase tracking-widest"><ShieldCheck className="w-3 h-3" /> AI Secure</span>}
                  {proxyStatus === "failed" && <span className="flex items-center gap-1.5 text-[8px] bg-red-500/20 text-red-400 px-2 py-0.5 rounded font-black uppercase tracking-widest"><ShieldAlert className="w-3 h-3" /> System Restricted</span>}
                </div>
              </div>
            </div>
            <button onClick={onClose} className="w-10 h-10 rounded-xl bg-white/5 hover:bg-white/10 flex items-center justify-center text-slate-400 hover:text-white transition-all border border-white/10">
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Workspace */}
          <div className="relative flex-1 overflow-auto bg-[#040612] flex items-start justify-center p-12 custom-scrollbar">
            {image ? (
              <div className="relative">
                {!error ? (
                  <div
                    className={`relative shadow-2xl ring-1 ring-white/10 rounded-xl overflow-hidden bg-black/40 transition-all duration-1000 ease-[cubic-bezier(0.22,1,0.36,1)] ${isScanning ? 'blur-[2px] brightness-50' : 'blur-0 brightness-100'}`}
                    style={{ transform: `scale(${imageScale})` }}
                  >
                    <ReactCrop
                      crop={crop}
                      onChange={(c) => setCrop(c)}
                      onComplete={(c) => setCompletedCrop(c)}
                      aspect={aspect}
                      className={`max-w-none transition-opacity duration-500 ${showCropBox ? 'opacity-100' : 'opacity-0'}`}
                    >
                      <img
                        ref={imgRef}
                        src={image}
                        alt="Edit"
                        onLoad={onImageLoad}
                        onError={() => setError(true)}
                        style={{ width: `${zoomPercent}%`, maxWidth: 'none', display: 'block', transition: 'transform 0.5s ease-out' }}
                      />
                    </ReactCrop>

                    {/* High-Fidelity Scanning Line */}
                    {isScanning && (
                      <div className="absolute inset-x-0 h-[2px] bg-gradient-to-r from-transparent via-cyan-400 to-transparent shadow-[0_0_20px_#22d3ee] animate-scan z-[120]" />
                    )}

                    {/* Scanning Status HUD */}
                    {isScanning && (
                      <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-[130]">
                        <div className="px-6 py-3 bg-black/60 backdrop-blur-md rounded-2xl border border-cyan-500/30 flex items-center gap-3 animate-in fade-in zoom-in duration-300">
                          <Scan className="w-4 h-4 text-cyan-400 animate-spin" />
                          <span className="text-[10px] font-black text-cyan-100 uppercase tracking-[0.2em]">{scanStatus}</span>
                        </div>
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center text-center py-10 bg-white/5 rounded-3xl border border-white/10 px-10 max-w-md w-full">
                    <div className="w-16 h-16 bg-red-500/10 rounded-2xl flex items-center justify-center mb-6">
                      <AlertCircle className="w-8 h-8 text-red-500" />
                    </div>
                    <h4 className="text-white font-black text-sm uppercase tracking-widest mb-2">Source Protected or Invalid</h4>
                    <p className="text-[10px] text-slate-500 mb-8 uppercase font-bold tracking-widest">External proxy failed or URL restricted.</p>

                    <div className="w-full space-y-3">
                      <label className="block w-full px-8 py-4 bg-emerald-400 text-[#0B0F2A] font-black text-[10px] uppercase rounded-2xl cursor-pointer hover:bg-emerald-300 active:scale-95 transition-all text-center">
                        Select Local File
                        <input type="file" className="hidden" accept="image/*" onChange={(e) => {
                          const f = e.target.files[0]; if (f) { const r = new FileReader(); r.onload = () => { setImage(r.result); setReadyForAI(true); setIsRestricted(false); setProxyStatus("success"); setError(false); }; r.readAsDataURL(f); }
                        }} />
                      </label>

                      <div className="relative">
                        <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
                          <ExternalLink className="w-4 h-4 text-slate-600" />
                        </div>
                        <input
                          className="w-full bg-black/40 border border-white/10 rounded-2xl pl-12 pr-4 py-4 text-xs font-bold text-white outline-none focus:border-violet-500 transition-all placeholder:text-slate-700"
                          placeholder="Paste Drive Link..."
                          onKeyDown={async (e) => {
                            if (e.key === 'Enter') {
                              const url = e.target.value.trim();
                              if (!url) return;
                              setScanStatus("Importing from Drive...");
                              setIsScanning(true);
                              try {
                                // Directly set the initialImage URL, the useEffect in this component will handle proxying
                                // BUT we want to force it to refresh or handle it here if it failed initially.
                                // So we call the manual prepare logic
                                const proxyUrl = `${API_URL}/api/proxy-image?url=${encodeURIComponent(url)}`;
                                const response = await fetch(proxyUrl);
                                if (!response.ok) throw new Error("Import failed");
                                const blob = await response.blob();
                                setImage(URL.createObjectURL(blob));
                                setReadyForAI(true);
                                setIsRestricted(false);
                                setProxyStatus("success");
                                setError(false);
                              } catch (err) { alert("Drive import failed. Ensure link is public."); }
                              finally { setIsScanning(false); }
                            }
                          }}
                        />
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="self-center flex flex-col items-center gap-10 animate-in fade-in slide-in-from-bottom-5 duration-700">
                <div className="relative">
                  <div className="absolute inset-0 bg-violet-500/20 blur-[60px] rounded-full animate-pulse" />
                  <Camera className="w-24 h-24 text-white relative z-10" />
                </div>

                <div className="space-y-4 text-center">
                  <h4 className="text-sm font-black uppercase tracking-[0.4em] text-white">IMAGE SOURCE REQUIRED</h4>
                  <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest max-w-[240px]">Select a source to begin the professional AI cropping process.</p>
                </div>

                <div className="grid grid-cols-1 gap-4 w-full max-w-[320px]">
                  <label className="flex items-center justify-center gap-4 px-8 py-5 bg-white text-black font-black text-xs uppercase rounded-[1.5rem] cursor-pointer hover:bg-violet-400 hover:text-white transition-all shadow-xl active:scale-95 group">
                    <Upload className="w-5 h-5 group-hover:scale-125 transition-transform" />
                    Local Computer
                    <input type="file" className="hidden" accept="image/*" onChange={(e) => {
                      const f = e.target.files[0]; if (f) { const r = new FileReader(); r.onload = () => { setImage(r.result); setReadyForAI(true); setIsRestricted(false); setProxyStatus("success"); setError(false); }; r.readAsDataURL(f); }
                    }} />
                  </label>

                  <button
                    onClick={() => {
                      console.log("Drive button clicked in Modal");
