      const s3 = setTimeout(() => {
        setShowLogo(true);
      }, 750);
      const s4 = setTimeout(() => {
        setShowTeamName(true);
      }, 950);
      const s5 = setTimeout(() => {
        console.log("Hiding hammer");
        setShowHammer(false);
      }, 2500);

      return () => {
        clearTimeout(reset);
        clearTimeout(s1);
        clearTimeout(s2);
        clearTimeout(s3);
        clearTimeout(s4);
        clearTimeout(s5);
      };
    }
  }, [isSold, type, playerName, price, teamName, teamLogo, teamShortName, playerImage]);

